    def setup_destination_progress_tab(self):
        self.destination_progress = DestinationProgressSetup(
            self, run_async=lambda work, success, failure: self.run_background_task(
                "Loading destination reconciliation…", work, success, failure, show_progress=False))
        self.destination_progress_tab_index = self.register_page(
            "destination_progress", self.setup_tabs, self.destination_progress,
            "Destination Reconciliation", position=self.setup_tabs.indexOf(self.stockpile_tab) + 1)
        self.destination_progress.settingsChanged.connect(
            lambda state: setattr(self, "destination_progress_settings", copy.deepcopy(state)))
        self.destination_progress.auditReady.connect(self.store_destination_order_audit)

    def destination_rule_context(self):
        return dict(
            areas=inventory_areas(getattr(self, "stockpile_data", None) or {}),
            haul_routes=copy.deepcopy(getattr(self, "destination_haul_routes", {}) or {}))

    def destination_allocation_context(self):
        panel = vars(self).get("destination_progress")
        if panel is None:
            return None
        context = panel.allocation_context(
            scenario_id=getattr(self, "active_scenario_id", "active"),
            site=getattr(self, "mine_input_choice", None),
            scenario_start=getattr(self, "start_time_choice", None),
            path=getattr(self, "file_path_choice", ""),
            inventories=getattr(self, "stockpile_data", None) or {})
        if context is not None:
            context["destination_rules"] = self.destination_rule_context()
            context["destination_rules"]["guidance"] = copy.deepcopy(getattr(self, "aps_destination_guidance", {}) or {})
        return context

    def sync_destination_progress_context(self):
        self.destination_progress.set_context(
            scenario_id=getattr(self, "active_scenario_id", "active"),
            site=getattr(self, "mine_input_choice", None),
            scenario_start=getattr(self, "start_time_choice", None),
            path=getattr(self, "file_path_choice", ""),
            inventories=getattr(self, "stockpile_data", None) or {},
            state=getattr(self, "destination_progress_settings", None))

    def store_destination_order_audit(self, snapshot):
        try:
            write_order_audit(snapshot, get_database_path())
            self.scenario_report_refresh_pending = True
        except (sqlite3.Error, OSError) as exc:
            self.destination_progress.validation.setText(f"Build order loaded, but the SQLite audit could not be saved: {exc}")

    def setup_opf_production_report_tab(self):
        self.opf_production_report = OPFProductionReport(
            self, run_async=lambda work, success, failure: self.run_background_task(
                "Loading product assay history…", work, success, failure, show_progress=False))
        self.opf_production_report_tab_index = self.register_page(
            "opf_production_report", self.workspace_tabs, self.opf_production_report,
            "OPF Production Report", position=self.workspace_tabs.indexOf(self.product_build_tab) + 1)
        self.opf_production_report.settingsChanged.connect(
            lambda state: setattr(self, "product_assay_report_settings", copy.deepcopy(state)))

    def sync_opf_production_report_context(self):
        report = getattr(self, "opf_production_report", None)
        if report is None:
            return
        active_opf = getattr(self, "opf_input_choice", None)
        opfs, targets = [active_opf] if active_opf else [], []
        for scenario_id, state in (getattr(self, "site_scenarios", {}) or {}).items():
            if scenario_id == getattr(self, "active_scenario_id", None):
                continue
            opf = state.get("opf_input_choice")
            if opf:
                opfs.append(opf)
                targets.extend({**row, "opf": row.get("opf") or opf} for row in product_targets_value(state, []) or [])
        current = self.read_product_targets_from_table(show_errors=False) if hasattr(self, "product_build_table") else None
        targets.extend({**row, "opf": row.get("opf") or active_opf}
                       for row in (current if current is not None else getattr(self, "product_targets", []) or []))
        report.set_context(scenario_id=getattr(self, "active_scenario_id", "active"),
                           scenario_start=getattr(self, "start_time_choice", None), opfs=opfs, active_opf=active_opf,
                           brands=self.product_brand_options(), targets=targets,
                           state=getattr(self, "product_assay_report_settings", {}))

    def default_product_brand_labels(self):
        return ["FB", "SS", "SF", "FF", "KF"]

    def parse_product_brand_labels(self, value):
        if isinstance(value, (list, tuple, set)):
            raw_labels = value
        else:
            raw_labels = str(value or "").replace(";", ",").split(",")
        labels = []
        for label in raw_labels:
            cleaned = str(label or "").strip().upper()
            if cleaned and cleaned not in labels:
                labels.append(cleaned)
        return labels or self.default_product_brand_labels()

    def product_brand_options(self):
        return self.parse_product_brand_labels(
            getattr(self, "product_brand_labels_choice", self.default_product_brand_labels())
        )

    def product_build_name_for_row(self, row_idx, brand, byproduct=None):
        brand = str(brand or "").strip().upper()
        byproduct = str(byproduct or "").strip().lower()
        if not brand:
            return f"Build {row_idx + 1}"

        brand_count = 0
        brand_column = self.product_build_headers.index("Brand")
        byproduct_column = self.product_build_headers.index("By-product")
        for index in range(row_idx + 1):
            if index == row_idx:
                row_brand = brand
                row_byproduct = byproduct
            else:
                brand_widget = self.product_build_table.cellWidget(index, brand_column)
                row_brand = (
                    brand_widget.currentText().strip().upper()
                    if isinstance(brand_widget, QComboBox)
                    else ""
                )
                byproduct_widget = self.product_build_table.cellWidget(
                    index, byproduct_column
                )
                row_byproduct = str(
                    byproduct_widget.currentData()
                    if isinstance(byproduct_widget, QComboBox) else ""
                ).strip().lower()
            if row_brand == brand and row_byproduct == byproduct:
                brand_count += 1
        lane_label = f" {byproduct.title()}" if byproduct else ""
        return f"{brand}{lane_label} Build {brand_count}"

    def set_product_build_count_from_input(self):
        try:
            count = int(self.product_build_count_input.text().strip() or 0)
        except ValueError:
            QMessageBox.warning(self, "Invalid Input", "Product build count must be a whole number.")
            return
        self.set_product_build_table_row_count(count)

    def set_product_build_table_row_count(self, count):
        count = max(int(count or 0), 0)
        existing = self.read_product_targets_from_table(show_errors=True)
        if existing is None:
            return
        self.product_build_table.setRowCount(count)
        for row_idx in range(count):
            source = existing[row_idx] if row_idx < len(existing) else {}
            self.populate_product_build_table_row(row_idx, source)
        self.renumber_product_build_rows()
        self.resize_product_build_table()

    def populate_product_build_table(self):
        settings = getattr(self, "product_targets", []) or []
        if hasattr(self, "product_build_table"):
            self.product_build_table.setColumnHidden(
                self.product_build_headers.index("By-product"),
                not bool(getattr(self, "byproducts_enabled", False)),
            )
        if hasattr(self, "group_2wp_build_targets_checkbox"):
            self.group_2wp_build_targets_checkbox.setChecked(bool(
                getattr(
                    self,
                    "group_2wp_build_targets_by_brand_choice",
                    False,
                )
            ))
        if hasattr(self, "product_build_count_input"):
            self.product_build_count_input.setText(str(len(settings)))
        self.product_build_table.setRowCount(len(settings))
        for row_idx, setting in enumerate(settings):
            self.populate_product_build_table_row(row_idx, setting)
        self.renumber_product_build_rows()
        self.resize_product_build_table()
        self.refresh_product_build_plan_scenario_label()

    @staticmethod
    def product_build_plan_scenario_summary(settings):
        scenarios = []
        fallback = False
        for setting in settings or []:
            if not isinstance(setting, dict):
                continue
            scenario = str(
                setting.get("planning_scenario") or ""
            ).strip()
            if scenario and scenario not in scenarios:
                scenarios.append(scenario)
            fallback = fallback or bool(setting.get(
                "planning_scenario_previous_week_fallback", False
            ))
        if not scenarios:
            return "", False
        return ", ".join(scenarios), fallback

    def refresh_product_build_plan_scenario_label(self):
        if not hasattr(self, "product_build_plan_scenario_label"):
            return
        scenario, fallback = self.product_build_plan_scenario_summary(
            getattr(self, "product_targets", []) or []
        )
        if not scenario:
            self.product_build_plan_scenario_label.clear()
            self.product_build_plan_scenario_label.setVisible(False)
            return
        suffix = " (previous-week fallback)" if fallback else ""
        self.product_build_plan_scenario_label.setText(
            f"2WP Plan Scenario Used: {scenario}{suffix}"
        )
        colour = "#9a5b00" if fallback else "#1e4f8a"
        background = "#fff7df" if fallback else "#edf6ff"
        self.product_build_plan_scenario_label.setStyleSheet(
            f"font-size: 12px; font-weight: 700; color: {colour}; "
            f"background-color: {background}; border: 1px solid {colour}; "
            "border-radius: 4px; padding: 6px 8px;"
        )
        self.product_build_plan_scenario_label.setVisible(True)

    def populate_product_build_table_row(self, row_idx, setting=None):
        setting = {**(setting or {}), **target_mode_fields(setting or {})}
        brand_combo = QComboBox()
        brand_combo.addItems(self.product_brand_options())
        selected_brand = str(setting.get("brand") or "").strip().upper()
        if selected_brand and brand_combo.findText(selected_brand) == -1:
            brand_combo.addItem(selected_brand)
        if selected_brand:
            brand_combo.setCurrentText(selected_brand)
        brand_column = self.product_build_headers.index("Brand")
        byproduct_column = self.product_build_headers.index("By-product")
        self.product_build_table.setCellWidget(row_idx, brand_column, brand_combo)

        byproduct_combo = QComboBox()
        byproduct_combo.addItem("Lump", "lump")
        byproduct_combo.addItem("Fines", "fines")
        selected_byproduct = str(setting.get("byproduct") or "").strip().lower()
        lane_index = byproduct_combo.findData(selected_byproduct)
        byproduct_combo.setCurrentIndex(lane_index if lane_index >= 0 else 0)
        self.product_build_table.setCellWidget(
            row_idx, byproduct_column, byproduct_combo
        )

        brand = brand_combo.currentText().strip().upper()
        lane = (
            str(byproduct_combo.currentData() or "").lower()
            if getattr(self, "byproducts_enabled", False) else ""
        )
        build_name = self.product_build_name_for_row(row_idx, brand, lane)
        build_item = QTableWidgetItem(build_name)
        # Row-owned metadata must move with deletion/reordering, never be
        # recovered by an index into the previous list of builds.
        build_item.setData(Qt.UserRole, copy.deepcopy(setting))
        build_item.setFlags(Qt.ItemIsEnabled)
        build_item.setTextAlignment(Qt.AlignCenter)
        self.product_build_table.setItem(row_idx, 0, build_item)
        opf_item = QTableWidgetItem(str(setting.get("opf") or getattr(self, "opf_input_choice", "") or ""))
        opf_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
        opf_item.setToolTip("The OPF carried with this build. New manual rows use the active OPF.")
        self.product_build_table.setItem(row_idx, self.product_build_headers.index("OPF"), opf_item)
        mode_combo = QComboBox()
        for value, label in TARGET_MODE_LABELS.items():
            mode_combo.addItem(value.title(), value)
            mode_combo.setItemData(mode_combo.count() - 1, label, Qt.ToolTipRole)
        mode_combo.setCurrentIndex(mode_combo.findData(setting["target_mode"]))
        mode_combo.setToolTip("Hard: existing Min/Max constraints. Soft: Target with configurable LQL/HQL behavior.")
        self.product_build_table.setCellWidget(row_idx, self.product_build_headers.index("Target mode"), mode_combo)
        mode_combo.currentIndexChanged.connect(lambda _index: self.product_target_mode_changed(mode_combo))
        brand_combo.currentTextChanged.connect(
            lambda _text: self.renumber_product_build_rows()
        )
        byproduct_combo.currentIndexChanged.connect(
            lambda _index: self.renumber_product_build_rows()
        )

        defaults = {
            "target_tonnes": 0,
            "target_fe_min": 0,
            "target_fe_max": 100,
            "target_si_min": 0,
            "target_si_max": 100,
            "target_al_min": 0,
            "target_al_max": 100,
            "target_p_min": 0,
            "target_p_max": 100,
            "target_mn_min": 0,
            "target_mn_max": 100,
        }
        keys = [
            "target_tonnes",
            "target_fe_min",
            "target_fe_max",
            "target_si_min",
            "target_si_max",
            "target_al_min",
            "target_al_max",
            "target_p_min",
            "target_p_max",
            "target_mn_min",
            "target_mn_max",
        ]
        target_column = self.product_build_headers.index("Target Tonnes")
        # Includes older 2WP projects that predate planning_grade_targets.
        imported_2wp = bool(setting.get("planning_scenario") or setting.get("planning_grade_targets"))
        for col_idx, key in enumerate(keys, start=target_column):
            value = setting.get(key, defaults[key])
            if key == "target_tonnes":
                try:
                    value = f"{math.floor(float(value)):,.0f}"
                except (TypeError, ValueError, OverflowError):
                    value = "0"
            elif value is not None and not imported_2wp:
                try:
                    value = f"{float(value):.2f}"
                except (TypeError, ValueError):
                    pass
            item = QTableWidgetItem("" if value is None else str(value))
            if imported_2wp and key != "target_tonnes":
                item.setData(IMPORTED_GRADE_ROLE, True)
                item.setToolTip(PRECISION_TOOLTIP)
            item.setTextAlignment(Qt.AlignCenter)
            self.product_build_table.setItem(row_idx, col_idx, item)

        for key, value in quality_fields(setting, validate=False).items():
            _, grade, part = key.split("_")
            label = f"{grade.title()} {part.upper() if part != 'target' else 'Target'}"
            item = QTableWidgetItem("" if value is None else str(value))
            item.setTextAlignment(Qt.AlignCenter)
            item.setToolTip("Quality specification (%). When supplied, LQL ≤ Target ≤ HQL. Blank means unspecified. Hard mode retains these as reference values; Soft mode uses these target settings.")
            if imported_2wp and part == "target":
                item.setData(IMPORTED_GRADE_ROLE, True)
                item.setToolTip(item.toolTip() + " " + PRECISION_TOOLTIP)
            self.product_build_table.setItem(row_idx, self.product_build_headers.index(label), item)

    def product_target_mode_changed(self, combo):
        column = self.product_build_headers.index("Target mode")
        row = next((r for r in range(self.product_build_table.rowCount()) if self.product_build_table.cellWidget(r, column) is combo), -1)
        if row < 0:
            return
        item = self.product_build_table.item(row, 0)
        data = copy.deepcopy(item.data(Qt.UserRole) or {})
        data["target_mode"] = combo.currentData()
        item.setData(Qt.UserRole, {**data, **target_mode_fields(data)})
        self.product_build_table.setCurrentCell(row, column)
        if self.product_build_grade_view.currentText() != "All grade fields":
            self.product_build_grade_view.setCurrentText("Min / Max" if combo.currentData() == "hard" else "LQL / Target / HQL")
        self.refresh_product_target_mode_controls()

    def refresh_product_target_mode_controls(self, *_):
        if not hasattr(self, "product_target_mode_controls"):
            return
        row = self.product_build_table.currentRow()
        item = self.product_build_table.item(row, 0) if row >= 0 else None
        self.product_target_mode_controls.set_row(item.data(Qt.UserRole) if item else None, item.text() if item else "")
        changed_build = item is not getattr(self, "_product_target_mode_selected_item", None)
        self._product_target_mode_selected_item = item
        if item and changed_build and self.product_build_grade_view.currentText() != "All grade fields":
            mode = target_mode_fields(item.data(Qt.UserRole) or {})["target_mode"]
            self.product_build_grade_view.setCurrentText("Min / Max" if mode == "hard" else "LQL / Target / HQL")
        column = self.product_build_headers.index("Target mode")
        soft = any(isinstance(self.product_build_table.cellWidget(r, column), QComboBox)
                   and self.product_build_table.cellWidget(r, column).currentData() == "soft"
                   for r in range(self.product_build_table.rowCount()))
        if hasattr(self, "product_target_mode_notice"):
            self.product_target_mode_notice.setVisible(soft)

    def update_selected_product_target_modes(self, values):
        row = self.product_build_table.currentRow()
        item = self.product_build_table.item(row, 0) if row >= 0 else None
        if item is not None:
            data = {**copy.deepcopy(item.data(Qt.UserRole) or {}), **values}
            item.setData(Qt.UserRole, {**data, **target_mode_fields(data)})

    def update_product_build_grade_view(self, *_):
        if not hasattr(self, "product_build_grade_view"):
            return
        selected = self.product_build_grade_view.currentIndex()
        for column, header in enumerate(self.product_build_headers):
            quality = header.rsplit(" ", 1)[-1] in {"LQL", "Target", "HQL"}
            hard = header.rsplit(" ", 1)[-1] in {"Min", "Max"}
            if quality or hard:
                self.product_build_table.setColumnHidden(column, (quality and selected == 0) or (hard and selected == 1))

    def resize_product_build_table(self):
        if not hasattr(self, "product_build_table"):
            return
        for col_idx in range(self.product_build_table.columnCount()):
            self.product_build_table.horizontalHeader().setSectionResizeMode(col_idx, QHeaderView.ResizeToContents)
        self.product_build_table.horizontalHeader().setSectionResizeMode(0, QHeaderView.Interactive)
        name_width = max((self.product_build_table.fontMetrics().horizontalAdvance(self.product_build_table.item(r, 0).text())
                          for r in range(self.product_build_table.rowCount()) if self.product_build_table.item(r, 0)), default=130)
        self.product_build_table.setColumnWidth(0, max(160, name_width + 28))
        if self.product_build_table.rowCount() and self.product_build_table.currentRow() < 0:
            self.product_build_table.setCurrentCell(0, 0)
        self.refresh_product_target_mode_controls()

    def read_product_targets_from_table(self, show_errors=True):
        if not hasattr(self, "product_build_table"):
            return []

        settings = []
        grade_keys = {
            "Fe": ("target_fe_min", "target_fe_max"),
            "Si": ("target_si_min", "target_si_max"),
            "Al": ("target_al_min", "target_al_max"),
            "P": ("target_p_min", "target_p_max"),
            "Mn": ("target_mn_min", "target_mn_max"),
        }

        def parse_number(row, col, label):
            item = self.product_build_table.item(row, col)
            text = item.text().strip() if item else ""
            try:
                return float((text or "0").replace(",", ""))
            except (TypeError, ValueError):
                if show_errors:
                    QMessageBox.warning(self, "Invalid Input", f"{label} in row {row + 1} must be a number.")
                return None

        brand_counts = {}
        for row_idx in range(self.product_build_table.rowCount()):
            brand_column = self.product_build_headers.index("Brand")
            byproduct_column = self.product_build_headers.index("By-product")
            brand_widget = self.product_build_table.cellWidget(row_idx, brand_column)
            brand = brand_widget.currentText().strip().upper() if isinstance(brand_widget, QComboBox) else ""
            byproduct_widget = self.product_build_table.cellWidget(
                row_idx, byproduct_column
            )
            byproduct = (
                str(byproduct_widget.currentData() or "").strip().lower()
                if getattr(self, "byproducts_enabled", False)
                and isinstance(byproduct_widget, QComboBox)
                else ""
            )
            if brand:
                count_key = (brand, byproduct)
                brand_counts[count_key] = brand_counts.get(count_key, 0) + 1
                lane_label = f" {byproduct.title()}" if byproduct else ""
                build_name = f"{brand}{lane_label} Build {brand_counts[count_key]}"
            else:
                build_name = f"Build {row_idx + 1}"
            target_tonnes = parse_number(
                row_idx,
                self.product_build_headers.index("Target Tonnes"),
                "Target Tonnes",
            )
            if target_tonnes is None:
                return None
            if target_tonnes < 0:
                if show_errors:
                    QMessageBox.warning(self, "Invalid Input", f"Target Tonnes in row {row_idx + 1} cannot be negative.")
                return None
            target_tonnes = math.floor(target_tonnes)

            setting = {
                **copy.deepcopy(self.product_build_table.item(row_idx, 0).data(Qt.UserRole) or {}),
                "build_id": row_idx + 1,
                "build_name": build_name,
                "brand": brand,
                "byproduct": byproduct,
                "target_tonnes": target_tonnes,
                "opf": self.product_build_table.item(row_idx, self.product_build_headers.index("OPF")).text().strip(),
                "target_mode": self.product_build_table.cellWidget(row_idx, self.product_build_headers.index("Target mode")).currentData(),
            }
            for grade_label, (min_key, max_key) in grade_keys.items():
                min_col = self.product_build_headers.index(f"{grade_label} Min")
                max_col = self.product_build_headers.index(f"{grade_label} Max")
                min_value = parse_number(row_idx, min_col, f"{grade_label} Min")
                max_value = parse_number(row_idx, max_col, f"{grade_label} Max")
                if min_value is None or max_value is None:
                    return None
                if min_value > max_value:
                    if show_errors:
                        QMessageBox.warning(
                            self,
                            "Invalid Input",
                            f"{grade_label} Min cannot be greater than {grade_label} Max in row {row_idx + 1}.",
                        )
                    return None
                setting[min_key] = min_value
                setting[max_key] = max_value
            for key in QUALITY_FIELDS:
                _, grade, part = key.split("_")
                label = f"{grade.title()} {part.upper() if part != 'target' else 'Target'}"
                item = self.product_build_table.item(row_idx, self.product_build_headers.index(label))
                setting[key] = item.text().strip() if item else None
            try:
                setting.update(quality_fields(setting))
                setting.update(target_mode_fields(setting))
            except ValueError as exc:
                if show_errors:
                    QMessageBox.warning(self, "Invalid Input", f"Product Targets row {row_idx + 1}: {exc}")
                return None
            # Runtime configurations are derived from these current row values.
            setting.pop("quality_limits", None)
            settings.append(setting)
        if getattr(self, "byproducts_enabled", False) and settings:
            configured_lanes = {setting.get("byproduct") for setting in settings}
            missing_lanes = [lane.title() for lane in BYPRODUCT_LANES if lane not in configured_lanes]
            if missing_lanes:
                if show_errors:
                    QMessageBox.warning(
                        self,
                        "Invalid Input",
                        "By-products are enabled, so Product Targets must "
                        f"contain at least one build for: {', '.join(missing_lanes)}.",
                    )
                return None
        return settings

    def update_product_build_name_for_row(self, row_idx, brand, byproduct=None):
        if not hasattr(self, "product_build_table") or row_idx >= self.product_build_table.rowCount():
            return
        brand = str(brand or "").strip().upper()
        build_name = self.product_build_name_for_row(row_idx, brand, byproduct)
        item = self.product_build_table.item(row_idx, 0)
        if item is None:
            item = QTableWidgetItem()
            item.setFlags(Qt.ItemIsEnabled)
            item.setTextAlignment(Qt.AlignCenter)
            self.product_build_table.setItem(row_idx, 0, item)
        item.setText(build_name)

    def delete_selected_product_build_rows(self):
        if not hasattr(self, "product_build_table"):
            return

        selected_rows = sorted(
            {index.row() for index in self.product_build_table.selectedIndexes()},
            reverse=True,
        )
        if not selected_rows:
            selected_rows = [self.product_build_table.currentRow()]
        selected_rows = [row for row in selected_rows if row >= 0]
        if not selected_rows:
            return

        for row in selected_rows:
            self.product_build_table.removeRow(row)

        self.renumber_product_build_rows()
        if hasattr(self, "product_build_count_input"):
            self.product_build_count_input.setText(str(self.product_build_table.rowCount()))
        self.store_product_targets(show_errors=False)
        self.resize_product_build_table()

    def renumber_product_build_rows(self):
        if not hasattr(self, "product_build_table"):
            return
        for row_idx in range(self.product_build_table.rowCount()):
            brand_widget = self.product_build_table.cellWidget(
                row_idx, self.product_build_headers.index("Brand")
            )
            brand = brand_widget.currentText() if isinstance(brand_widget, QComboBox) else ""
            byproduct_widget = self.product_build_table.cellWidget(
                row_idx, self.product_build_headers.index("By-product")
            )
            byproduct = (
                byproduct_widget.currentData()
                if getattr(self, "byproducts_enabled", False)
                and isinstance(byproduct_widget, QComboBox)
                else ""
            )
            self.update_product_build_name_for_row(row_idx, brand, byproduct)

    def store_product_targets(self, show_errors=True):
        settings = self.read_product_targets_from_table(show_errors=show_errors)
        if settings is None:
            return False
        self.product_targets = settings
        if self.calendar_inputs is None:
            self.calendar_inputs = {}
        self.calendar_inputs = migrate_product_target_state(self.calendar_inputs or {})
        self.calendar_inputs["product_targets"] = copy.deepcopy(self.product_targets)
        self.calendar_inputs["product_brand_labels"] = copy.deepcopy(self.product_brand_options())
        self.refresh_product_build_plan_scenario_label()
        if vars(self).get("opf_production_report") is not None and self.opf_production_report.isVisible():
            self.sync_opf_production_report_context()
        return True

    def navigate_to_product_targets(self):
        self.populate_product_build_table()
        self.set_page_enabled(self.product_build_tab_index, True)
        self.set_page_enabled(self.decision_levers_tab_index, True)
        self.show_page(self.product_build_tab_index)

    def handle_product_targets_submit(self):
        if not self.store_product_targets():
            return
        self.save_active_scenario_state()
        self.navigate_to_decision_levers()

    def navigate_to_decision_levers(self):
        self.load_solver_config_inputs()
        self.set_page_enabled(self.decision_levers_tab_index, True)
        self.show_page(self.decision_levers_tab_index)

    def handle_decision_levers_submit(self):
        if not self.store_solver_config_inputs():
            return
        self.save_active_scenario_state()
        self.setup_calendar()
        self.set_page_enabled(self.calendar_tab_index, True)
        self.show_page(self.calendar_tab_index)

    def load_2wp_product_build_targets(self):
        mine = getattr(self, "mine_input_choice", None)
        opf = getattr(self, "opf_input_choice", None)
        crusher = getattr(self, "crusher_input_choice", None)
        start_time = getattr(self, "start_time_choice", None)
        if not mine or not crusher or not start_time:
            QMessageBox.information(
                self,
                "BlendMaster",
                "Submit Site Configuration before loading 2WP product-build targets.",
            )
            return

        def work():
            return self.planning_plan_targets.fetch(
                mine,
                crusher,
                start_time,
                self.product_brand_options(),
                opf=opf,
                crusher_contribution_ratio=getattr(
                    self, "crusher_contribution_ratio_choice", 1.0
                ),
                planning_period_count=self.planning_period_count(),
                planning_category=self.data_stream_planning_categories.get(
                    "product", DEFAULT_PLANNING_CATEGORIES["product"]
                ),
                byproducts_enabled=bool(getattr(self, "byproducts_enabled", False)),
            )

        def success(settings):
            if not settings:
                planning_category = self.data_stream_planning_categories.get(
                    "product", DEFAULT_PLANNING_CATEGORIES["product"]
                )
                scenario_key = self.planning_plan_targets.latest_wednesday_scenario(
                    start_time
                )
                QMessageBox.information(
                    self,
                    "BlendMaster",
                    f"No overlapping 2WP {planning_category} targets were found "
                    f"for {mine} / {opf} / {crusher} using current scenario "
                    f"key {scenario_key}. Previous-week fallback is only "
                    "eligible on Wednesdays when that current plan has no "
                    "published rows.",
                )
                return
            self.group_2wp_build_targets_by_brand_choice = bool(
                self.group_2wp_build_targets_checkbox.isChecked()
            )
            if self.group_2wp_build_targets_by_brand_choice:
                settings = self.planning_plan_targets.group_builds_by_brand(
                    settings
                )
            extra_brands = [setting.get("brand") for setting in settings if setting.get("brand")]
            self.product_brand_labels_choice = self.parse_product_brand_labels(
                self.product_brand_options() + extra_brands
            )
            self.product_brand_labels_input.setText(", ".join(self.product_brand_labels_choice))
            self.product_targets = settings
            self.populate_product_build_table()
            self.store_product_targets(show_errors=False)
            self.save_active_scenario_state()
            scenario, fallback = self.product_build_plan_scenario_summary(
                settings
            )
            scenario_note = (
                f"\n\n2WP Plan Scenario Used: {scenario}"
                + (" (previous-week fallback)" if fallback else "")
                if scenario else ""
            )
            QMessageBox.information(
                self,
                "BlendMaster",
                f"Loaded {len(settings)} product build target(s) for "
                f"{mine} / {opf} / {crusher}.{scenario_note}",
            )

        self.run_background_task(
            f"Loading 2WP build targets for {mine} / {opf} / {crusher}...",
            work,
            success,
        )

    def create_solver_threshold_input(self, default_value, validator):
        input_field = QLineEdit()
        input_field.setText(default_value)
        input_field.setValidator(validator)
        input_field.setFixedWidth(70)
        return input_field

    def custom_constraint_available_fields(self):
        definitions = vars(self).get("field_definitions")
        return sorted(optimization_field_names(definitions))

    def populate_custom_constraint_table(self):
        if not hasattr(self, "custom_constraint_table"):
            return
        definitions = normalize_custom_constraints(
            getattr(self, "custom_constraint_definitions", [])
        )
        self.custom_constraint_definitions = definitions
        self.custom_constraint_table.setRowCount(len(definitions))
        for row, definition in enumerate(definitions):
            for column, key in enumerate(("name", "numerator", "denominator")):
                item = QTableWidgetItem(str(definition.get(key) or ""))
                item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                self.custom_constraint_table.setItem(row, column, item)
        self.custom_constraint_table.resizeRowsToContents()

    def custom_constraint_expression_combo(self, fields, value=""):
        combo = QComboBox()
        combo.setEditable(True)
        combo.addItems(fields)
        combo.setCurrentText(str(value or ""))
        completer = QCompleter(fields, combo)
        completer.setCaseSensitivity(Qt.CaseInsensitive)
        completer.setFilterMode(Qt.MatchContains)
        combo.setCompleter(completer)
        combo.lineEdit().setPlaceholderText(
            "Select a field or type an expression"
        )
        return combo

    def add_custom_constraint(self):
        self.open_custom_constraint_dialog()

    def edit_selected_custom_constraint(self, *_args):
        if not hasattr(self, "custom_constraint_table"):
            return
        row = self.custom_constraint_table.currentRow()
        if row < 0 or row >= len(self.custom_constraint_definitions):
            QMessageBox.information(
                self,
                "Custom Constraints",
                "Select a constraint to edit.",
            )
            return
        self.open_custom_constraint_dialog(row)

    def delete_selected_custom_constraint(self):
        if not hasattr(self, "custom_constraint_table"):
            return
        row = self.custom_constraint_table.currentRow()
        if row < 0 or row >= len(self.custom_constraint_definitions):
            return
        removed = self.custom_constraint_definitions.pop(row)
        key = constraint_key(removed.get("key") or removed.get("name"))
        deleted_calendar_keys = {
            f"crusher_custom_constraint_{key}_{suffix}"
            for suffix in ("min", "max")
        }
        for suffix in ("min", "max"):
            (self.calendar_inputs or {}).pop(
                f"crusher_custom_constraint_{key}_{suffix}", None
            )
        if hasattr(self, "main_table"):
            for table_row in range(self.main_table.rowCount() - 1, -1, -1):
                caption_item = self.main_table.item(table_row, 0)
                if (
                    caption_item is not None
                    and str(caption_item.data(Qt.UserRole) or "")
                    in deleted_calendar_keys
                ):
                    self.main_table.removeRow(table_row)
        self.populate_custom_constraint_table()

    def open_custom_constraint_dialog(self, row=None):
        if not self.database_view_is_current():
            QMessageBox.information(
                self,
                "Custom Constraints",
                "Refresh Database View successfully before adding or editing "
                "a custom constraint.",
            )
            return
        current = (
            self.custom_constraint_definitions[row]
            if row is not None and 0 <= row < len(self.custom_constraint_definitions)
            else {}
        )
        fields = self.custom_constraint_available_fields()
        dialog = QDialog(self)
        dialog.setWindowTitle(
            "Edit Custom Constraint" if current else "Add Custom Constraint"
        )
        dialog.resize(650, 230)
        layout = QVBoxLayout(dialog)
        form = QFormLayout()
        name_input = QLineEdit(str(current.get("name") or ""))
        numerator_input = self.custom_constraint_expression_combo(
            fields, current.get("numerator")
        )
        denominator_input = self.custom_constraint_expression_combo(
            fields, current.get("denominator") or "1"
        )
        form.addRow("Name:", name_input)
        form.addRow("Numerator:", numerator_input)
        form.addRow("Denominator:", denominator_input)
        layout.addLayout(form)
        hint = QLabel(
            "Calendar will add Min and Max rows for this constraint. Leave a "
            "Calendar bound blank when that side should not be enforced. "
            "Additive expressions sum across selected sources; weighted-average "
            "expressions use their declared weight; entering 1 is a scalar one. "
            "Reports repeat the whole-blend numerator, denominator and ratio on "
            "each source row and retain source audit contributions."
        )
        hint.setWordWrap(True)
        layout.addWidget(hint)
        buttons = QHBoxLayout()
        save_button = QPushButton("Save")
        cancel_button = QPushButton("Cancel")
        buttons.addStretch()
        buttons.addWidget(save_button)
        buttons.addWidget(cancel_button)
        layout.addLayout(buttons)
        cancel_button.clicked.connect(dialog.reject)

        def save_definition():
            name = name_input.text().strip()
            numerator = numerator_input.currentText().strip()
            denominator = denominator_input.currentText().strip() or "1"
            if not name:
                QMessageBox.warning(dialog, "Invalid Constraint", "Name cannot be blank.")
                return
            try:
                numerator_expression = SafeNumericExpression(numerator)
                denominator_expression = SafeNumericExpression(denominator)
            except CustomConstraintError as error:
                QMessageBox.warning(dialog, "Invalid Constraint", str(error))
                return
            unavailable = sorted(
                {
                    name.lower()
                    for name in (
                        numerator_expression.names
                        | denominator_expression.names
                    )
                }
                - set(fields)
            )
            if unavailable:
                QMessageBox.warning(
                    dialog,
                    "Invalid Constraint",
                    "These fields are not available in the current source data: "
                    + ", ".join(unavailable),
                )
                return
            key = current.get("key") or constraint_key(name)
            used_keys = {
                definition.get("key")
                for index, definition in enumerate(self.custom_constraint_definitions)
                if index != row
            }
            base_key = key
            suffix = 2
            while key in used_keys:
                key = f"{base_key}_{suffix}"
                suffix += 1
            definition = {
                "key": key,
                "name": name,
                "numerator": numerator,
                "denominator": denominator,
                "enabled": True,
            }
            if row is None:
                self.custom_constraint_definitions.append(definition)
            else:
                self.custom_constraint_definitions[row] = definition
            self.populate_custom_constraint_table()
            dialog.accept()

        save_button.clicked.connect(save_definition)
        dialog.exec_()

    def update_direct_tip_input_state(self, checked=None):
        direct_tip_enabled = self.direct_tip_enabled_checkbox.isChecked()
        self.direct_tip_cash_incentive_input.setEnabled(direct_tip_enabled)
        if hasattr(self, "two_wp_destination_turnover_incentive_input"):
            self.two_wp_destination_turnover_incentive_input.setEnabled(
                direct_tip_enabled
            )
        if hasattr(self, "two_wp_destination_turnover_guidance_checkbox"):
            self.two_wp_destination_turnover_guidance_checkbox.setEnabled(
                direct_tip_enabled
            )
        if hasattr(self, "min_grade_block_pair_duration_input"):
            self.min_grade_block_pair_duration_input.setEnabled(direct_tip_enabled)
        if hasattr(self, "stay_on_same_grade_block_pair_incentive_input"):
            self.stay_on_same_grade_block_pair_incentive_input.setEnabled(direct_tip_enabled)
        if hasattr(self, "grade_block_lock_checkbox"):
            self.grade_block_lock_checkbox.setEnabled(direct_tip_enabled)
        if hasattr(self, "require_whole_direct_tip_payloads_checkbox"):
            self.require_whole_direct_tip_payloads_checkbox.setEnabled(
                direct_tip_enabled
            )

    def update_rehandle_cycle_time_input_state(self, checked=None):
        if not hasattr(self, "haulage_cost_per_hour_input"):
            return
        # The switch is configured later on Decision Levers; keep its cost
        # editable here even when the penalty itself is currently disabled.
        self.haulage_cost_per_hour_input.setEnabled(True)

    def is_direct_tip_enabled(self):
        solver_config = self.normalized_solver_config()
        return bool(solver_config.get("direct_tip_enabled", True))

    def normalized_solver_config(self, solver_config=None):
        defaults = {
            "soft_grade_preferences": objective_config(),
            "throughput_incentive_per_tonne": 1_000_100.0,
            "source_selection_tie_break_penalty": 0.001,
            "stockpile_feasibility_mode": "stockpile_must_be_feasible",
            "min_feed_duration_hours": None,
            "direct_tip_enabled": True,
            "direct_tip_cash_incentive": 10.0,
            "two_wp_destination_turnover_guidance_enabled": False,
            "two_wp_destination_turnover_incentive": 10.0,
            "stay_on_same_blend_incentive": 0.0,
            "blend_option_timeout_seconds": 30.0,
            "max_blend_options_per_steady_state": 12,
            "contingency_max_blend_options_per_steady_state": 12,
            "contingency_plan_count": 0,
            "contingency_distinctness_mode": (
                "stockpile_or_grade_block_pairing"
            ),
            "min_grade_block_pair_duration_hours": 0.0,
            "stay_on_same_grade_block_pair_incentive": 0.0,
            "grade_block_lock_enabled": False,
            "require_whole_direct_tip_payloads": False,
            "prefer_fewer_stockpiles": False,
            "fewer_stockpiles_incentive": 10.0,
            "balance_preference": "none",
            "balance_preference_incentive": 1.0,
            "prefer_amt_stockpiles": False,
            "amt_preference_incentive": 1.0,
            "prefer_contaminated_stockpiles": False,
            "contaminated_preference_incentive": 1.0,
            "contaminant_thresholds": {
                "si": 5.0,
                "al": 3.0,
                "p": 0.1,
                "mn": 0.1,
            },
            "prefer_low_fe_stockpiles": False,
            "low_fe_preference_incentive": 1.0,
            "low_fe_threshold": 58.0,
            "allow_offspec_steady_states_for_product_build": False,
            "enable_product_build_repair_loop": False,
            "enforce_calendar_crusher_grade_targets": True,
            "brand_guidance_mode": "ignore",
            "brand_guidance_enabled": False,
            "brand_guidance_incentive": 0.0,
            "timing_guidance_enabled": False,
            "timing_guidance_incentive": 0.0,
            "timing_guidance_tolerance_hours": 0.0,
            "active_blend_guidance_enabled": False,
            "active_blend_guidance_incentive": 0.0,
            "rehandle_cycle_time_penalty_enabled": False,
            "haulage_cost_per_hour": 5.0,
            "custom_constraints": [],
            "strict_mapped_fields": True,
        }
        incoming = solver_config if solver_config is not None else self.solver_config
        if not incoming:
            return defaults

        merged = copy.deepcopy(defaults)
        incoming = copy.deepcopy(incoming)
        if "contingency_max_blend_options_per_steady_state" not in incoming:
            incoming["contingency_max_blend_options_per_steady_state"] = (
                incoming.get("max_blend_options_per_steady_state", 12)
            )
        contaminant_thresholds = incoming.pop("contaminant_thresholds", None)
        merged.update(incoming)
        merged["soft_grade_preferences"] = objective_config(merged.get("soft_grade_preferences"))
        if isinstance(contaminant_thresholds, dict):
            merged["contaminant_thresholds"].update(contaminant_thresholds)
        if "brand_guidance_enabled" not in incoming:
            merged["brand_guidance_enabled"] = (
                merged.get("brand_guidance_mode", "ignore") != "ignore"
            )
        try:
            if float(merged.get("haulage_cost_per_hour") or 0) <= 0:
                merged["haulage_cost_per_hour"] = 5.0
        except (TypeError, ValueError):
            merged["haulage_cost_per_hour"] = 5.0
        try:
            merged["custom_constraints"] = normalize_custom_constraints(
                merged.get("custom_constraints")
            )
            self.custom_constraint_normalization_warning = ""
        except CustomConstraintError as error:
            self.custom_constraint_normalization_warning = str(error)
            raise ValueError(
                "Invalid saved custom constraint: " + str(error)
            ) from error
        definitions = normalize_field_definitions(
            vars(self).get("field_definitions")
        )
        merged["optimisation_source_property_fields"] = sorted(
            optimization_field_names(definitions)
        )
        merged["source_property_kinds"] = {
            row["name"]: row["kind"] for row in definitions
        }
        merged["source_property_weights"] = field_weight_map(definitions)
        merged["crusher_tonnes_stream"] = str(
            merged.get("crusher_tonnes_stream")
            or vars(self).get("crusher_tonnes_stream")
            or "modelled_rom_wmt"
        )
        merged["reclaimer_tonnes_stream"] = str(
            merged.get("reclaimer_tonnes_stream")
            or vars(self).get("reclaimer_tonnes_stream")
            or "modelled_rom_wmt"
        )
        merged["product_build_tonnes_stream"] = str(
            merged.get("product_build_tonnes_stream")
            or vars(self).get("product_build_tonnes_stream")
            or "modelled_product_wmt"
        )
        merged["byproducts_enabled"] = bool(
            merged.get("byproducts_enabled", vars(self).get("byproducts_enabled", False))
        )
        merged["byproduct_quantity_fields"] = normalize_byproduct_quantity_fields(
            merged.get("byproduct_quantity_fields")
            or vars(self).get("byproduct_quantity_fields")
        )
        merged["byproduct_grade_fields"] = normalize_byproduct_grade_fields(
            merged.get("byproduct_grade_fields")
            or vars(self).get("byproduct_grade_fields")
        )
        if merged["byproducts_enabled"]:
            merged["optimisation_source_property_fields"] = sorted(set(
                merged["optimisation_source_property_fields"]
                + list(merged["byproduct_quantity_fields"].values())
                + [
                    field
                    for lane_fields in merged["byproduct_grade_fields"].values()
                    for field in lane_fields.values()
                ]
            ))
        return merged

