    def database_view_input_signature(self):
        """Return the inputs that determine the APS payload snapshot."""
        signature = {
            "period_count": self.planning_period_count(),
            "expit_inputs": self.expit_input_cache_signature(),
            "excluded_amt_footprints": sorted(self.excluded_amt_footprints()),
        }
        return json.dumps(signature, sort_keys=True, default=str)

    @staticmethod
    def expit_input_file_fingerprint(file_path):
        """Return a cheap content-change fingerprint for a schedule input."""
        raw_path = str(file_path or "").strip()
        if not raw_path:
            return {"path": "", "exists": False}
        normalized_path = os.path.normcase(os.path.abspath(raw_path))
        try:
            stats = os.stat(normalized_path)
        except OSError:
            return {"path": normalized_path, "exists": False}
        return {
            "path": normalized_path,
            "exists": True,
            "size": int(stats.st_size),
            "modified_ns": int(stats.st_mtime_ns),
        }

    @staticmethod
    def expit_signature_datetime(value):
        if value is None or value == "":
            return ""
        try:
            timestamp = pd.Timestamp(value)
            if pd.isna(timestamp):
                return ""
            return timestamp.isoformat()
        except (TypeError, ValueError):
            return str(value)

    def expit_input_cache_signature(
        self,
        start_time=None,
        site_context=None,
        schedule_path=None,
        two_wp_path=None,
        selected_agents=None,
        expit_mode=None,
        reevaluate_direct_tip=None,
        selected_crusher=None,
    ):
        """Identify every input capable of changing solver-ready payloads."""
        context = site_context or self.active_site_context()
        schedule_path = (
            schedule_path
            if schedule_path is not None
            else getattr(self, "file_path_24hr_choice", "")
        )
        two_wp_path = (
            two_wp_path
            if two_wp_path is not None
            else getattr(self, "file_path_choice", "")
        )
        selected_agents = (
            selected_agents
            if selected_agents is not None
            else getattr(self, "selected_24hr_expit_agents", [])
        )
        expit_mode = (
            expit_mode
            if expit_mode is not None
            else getattr(self, "expit_mode_choice", 1)
        )
        reevaluate_direct_tip = (
            reevaluate_direct_tip
            if reevaluate_direct_tip is not None
            else getattr(self, "reevaluate_aps_direct_tip_choice", False)
        )
        selected_crusher = (
            selected_crusher
            if selected_crusher is not None
            else getattr(self, "aps_direct_tip_crusher_choice", [])
        )
        definitions = normalize_field_definitions(
            context.get("field_definitions")
        )
        signature = {
            "cache_version": EXPIT_INPUT_CACHE_VERSION,
            "destination_guidance_version": (
                ExpitDataHandler.DESTINATION_GUIDANCE_VERSION
            ),
            "start_time": UserInputs.expit_signature_datetime(
                start_time
                if start_time is not None
                else getattr(self, "start_time_choice", None)
            ),
            "expit_mode": int(expit_mode or 1),
            "completion_tolerance_pct": float(
                context.get(
                    "expit_completion_tolerance_pct",
                    getattr(self, "expit_completion_tolerance_pct", 10.0),
                )
                or 10.0
            ),
            "24hr_file": UserInputs.expit_input_file_fingerprint(schedule_path),
            "2wp_file": UserInputs.expit_input_file_fingerprint(two_wp_path),
            "agents": sorted(
                str(value).strip().upper()
                for value in selected_agents or []
                if str(value).strip()
            ),
            "reevaluate_direct_tip": bool(reevaluate_direct_tip),
            "selected_crusher": sorted(
                str(value).strip().upper()
                for value in (
                    selected_crusher
                    if isinstance(selected_crusher, (list, tuple, set))
                    else [selected_crusher]
                )
                if str(value).strip()
            ),
            "site": {
                key: context.get(key)
                for key in ("mine", "opf", "crusher", "product_brands")
            },
            "movement_rules": context.get("direct_tip_movement_rules", []),
            "grade_mappings": context.get("aps_grade_field_mappings", {}),
            "property_mappings": context.get(
                "aps_source_property_field_mappings", {}
            ),
            "field_definitions": definitions,
            "cb_lump_fines_mode": context.get("cb_lump_fines_mode"),
            "cb_lump_percentage": context.get("cb_lump_percentage"),
        }
        return json.dumps(signature, sort_keys=True, default=str)

    def expit_input_cache_allowed(self, time_mode=None, expit_mode=None):
        """Return whether an Expit snapshot may be reused for this run."""
        try:
            time_mode = int(
                time_mode
                if time_mode is not None
                else getattr(self, "time_mode_choice", 1)
            )
        except (TypeError, ValueError):
            time_mode = 1
        try:
            expit_mode = int(
                expit_mode
                if expit_mode is not None
                else getattr(self, "expit_mode_choice", 1)
            )
        except (TypeError, ValueError):
            expit_mode = 1
        if not (time_mode == 1 and expit_mode == 2):
            return True
        return max(int(getattr(
            self, "expit_refresh_tolerance_minutes", 0
        ) or 0), 0) > 0

    @staticmethod
    def expit_signatures_match_except_start_time(left, right):
        try:
            left_payload = json.loads(str(left or ""))
            right_payload = json.loads(str(right or ""))
        except (TypeError, ValueError, json.JSONDecodeError):
            return False
        if not isinstance(left_payload, dict) or not isinstance(
            right_payload, dict
        ):
            return False
        left_payload.pop("start_time", None)
        right_payload.pop("start_time", None)
        return left_payload == right_payload

    def read_reusable_expit_input_cache(self, signature):
        """Read an exact cache hit or a fresh current-time equivalent."""
        manager = DatabaseManager()
        transactions, metadata = manager.read_expit_input_cache(signature)
        current_time_reconciliation = (
            int(getattr(self, "time_mode_choice", 1) or 1) == 1
            and int(getattr(self, "expit_mode_choice", 1) or 1) == 2
        )
        tolerance = max(int(getattr(
            self, "expit_refresh_tolerance_minutes", 0
        ) or 0), 0)
        if transactions is not None and not current_time_reconciliation:
            metadata = dict(metadata or {})
            metadata["cache_match"] = "exact"
            return transactions, metadata
        if transactions is not None and current_time_reconciliation:
            created_at = pd.to_datetime(
                (metadata or {}).get("cache_created_at"),
                errors="coerce", utc=True,
            )
            age_minutes = (
                max(
                    (
                        pd.Timestamp.now(tz="UTC") - created_at
                    ).total_seconds() / 60.0,
                    0.0,
                )
                if not pd.isna(created_at) else float("inf")
            )
            if tolerance > 0 and age_minutes <= tolerance:
                metadata = dict(metadata or {})
                metadata.update({
                    "cache_match": "fresh_current_time",
                    "cache_age_minutes": age_minutes,
                    "cache_tolerance_minutes": tolerance,
                })
                return transactions, metadata
        if not current_time_reconciliation or tolerance <= 0:
            return None, {}

        latest, latest_signature, metadata = (
            manager.read_latest_expit_input_cache()
        )
        if latest is None or not self.expit_signatures_match_except_start_time(
            latest_signature, signature
        ):
            return None, {}
        created_at = pd.to_datetime(
            (metadata or {}).get("cache_created_at"), errors="coerce",
            utc=True,
        )
        if pd.isna(created_at):
            return None, {}
        age_minutes = max(
            (
                pd.Timestamp.now(tz="UTC") - created_at
            ).total_seconds() / 60.0,
            0.0,
        )
        if age_minutes > tolerance:
            return None, {}
        metadata = dict(metadata or {})
        metadata.update({
            "cache_match": "fresh_current_time",
            "cache_age_minutes": age_minutes,
            "cache_tolerance_minutes": tolerance,
        })
        return latest, metadata

    def database_view_is_current(self):
        if getattr(self, "database_view_refresh_in_progress", False):
            return False
        try:
            current_signature = self.database_view_input_signature()
        except Exception:
            return False
        return (
            getattr(self, "database_view_snapshot_signature", None)
            == current_signature
        )

    def database_view_periods(self):
        period_count = getattr(
            self, "database_view_period_count_snapshot", None
        )
        if period_count is None:
            period_count = self.planning_period_count()
        periods = PeriodManager(period_count)
        periods.calculate_periods(
            getattr(self, "database_view_start_time_snapshot", None)
            or self.start_time_choice
            or datetime.now()
        )
        return periods

    def database_view_record_with_streams(
        self, record, streams, fallback=None, source_warnings=None
    ):
        """Flatten stored and optimiser-resolved grades into one audit row."""
        record = evidence_display_record(dict(record or {}))
        fallback = fallback or {}
        normalized_streams = normalise_grade_streams(streams, fallback)

        # Stockpile modelled ROM is physically unbranded. Older saved
        # inventory rows and chunks can therefore contain only the ``*``
        # vector. Publish an equal vector for every configured brand at the
        # Database View boundary without altering brand-specific adjusted ROM.
        # APS rows are excluded because their mapped modelled ROM can genuinely
        # differ by brand.
        source_type = str(record.get("source_type") or "").strip().lower()
        if "stockpile" in source_type or source_type.startswith("amt chunk"):
            record.update(reconciliation_columns(record.get("reconciliation") or fallback.get("reconciliation")))
        if "stockpile" in source_type or source_type.startswith("amt chunk"):
            # Inventory and AMT ROM WMT is their physical opening balance.
            # This direct value also repairs legacy saved chunks containing a
            # footprint-level mapped ROM quantity in modelled_properties.
            opening_wmt = numeric(
                record.get("tonnes", record.get("balance"))
            )
            if opening_wmt is not None:
                record["source_wmt"] = opening_wmt
            rom_by_brand = normalized_streams.setdefault("modelled_rom", {})
            unbranded_rom = rom_by_brand.get("*")
            if not isinstance(unbranded_rom, dict):
                unbranded_rom = next(
                    (
                        values
                        for values in rom_by_brand.values()
                        if isinstance(values, dict)
                    ),
                    None,
                )
            if isinstance(unbranded_rom, dict):
                rom_by_brand["*"] = copy.deepcopy(unbranded_rom)
                for brand in configured_brands(
                    self.product_brand_labels_choice
                ):
                    rom_by_brand[brand] = copy.deepcopy(unbranded_rom)
        elif source_type == "aps grade block":
            # APS payload is the physical ROM WMT available to direct tipping.
            # It is scheduling data rather than a site-specific Mining.csv
            # property mapping, so publish it under the same canonical field.
            opening_wmt = numeric(record.get("tonnes"))
            if opening_wmt is not None:
                record["source_wmt"] = opening_wmt
                record["modelled_rom_wmt"] = opening_wmt

        record["selected_stream"] = self.selected_data_stream
        for analyte in ANALYTES:
            record[f"grade_{analyte}"] = numeric(
                fallback.get(f"grade_{analyte}")
                if f"grade_{analyte}" in fallback
                else fallback.get(f"source_grade_{analyte}")
            )
        record.update(flatten_grade_streams(normalized_streams))

        # Keep the field registry visible as a complete source schema. An
        # unmapped field is deliberately represented by None, not omitted.
        defined_values = record.get("defined_fields") or {}
        if isinstance(defined_values, dict):
            for key, value in defined_values.items():
                record[key] = value
        numeric_properties = source_properties_from_mapping(record)
        for definition in normalize_field_definitions(
            vars(self).get("field_definitions")
        ):
            name = definition["name"]
            value = (
                defined_values.get(name)
                if isinstance(defined_values, dict) and name in defined_values
                else record.get(name, numeric_properties.get(name))
            )
            if value is None:
                for stream in STREAMS:
                    prefix = f"{stream}_"
                    if not name.startswith(prefix):
                        continue
                    analyte = name[len(prefix):]
                    if analyte not in ANALYTES:
                        break
                    brand_map = normalized_streams.get(stream) or {}
                    candidate_brands = [
                        *configured_brands(self.product_brand_labels_choice),
                        "__unbranded__",
                        *brand_map.keys(),
                    ]
                    for brand in dict.fromkeys(candidate_brands):
                        candidate = numeric(
                            (brand_map.get(brand) or {}).get(analyte)
                        )
                        if candidate is not None:
                            value = candidate
                            break
                    break
            record[name] = value

        fallback_groups = {}
        for brand in configured_brands(self.product_brand_labels_choice):
            brand_key = "".join(
                character.lower() if character.isalnum() else "_"
                for character in brand
            ).strip("_") or "unbranded"
            grades, fallbacks = resolve_grade_vector(
                normalized_streams,
                self.selected_data_stream,
                brand,
                fallback,
            )
            fallback_by_analyte = {
                warning["analyte"]: warning for warning in fallbacks
            }
            for analyte in ANALYTES:
                record[f"selected_{brand_key}_{analyte}"] = grades[analyte]
                warning = fallback_by_analyte.get(analyte)
                if warning:
                    provenance = (
                        f"{warning['requested_stream']}[{warning['requested_brand']}]"
                        f" -> {warning['used_stream']}[{warning['used_brand']}]"
                    )
                    record[f"fallback_{brand_key}_{analyte}"] = provenance
                    route = (
                        brand,
                        warning["requested_stream"],
                        warning["requested_brand"],
                        warning["used_stream"],
                        warning["used_brand"],
                    )
                    fallback_groups.setdefault(route, []).append(analyte)
                else:
                    record[f"fallback_{brand_key}_{analyte}"] = ""

        if isinstance(source_warnings, str):
            source_warnings = [source_warnings]
        warnings = [str(value) for value in (source_warnings or []) if str(value)]
        if "stockpile" in source_type or source_type.startswith("amt chunk"):
            warnings.extend((record.get("reconciliation") or fallback.get("reconciliation") or {}).get("warnings", []))
        analyte_labels = {
            "fe": "Fe", "si": "Si", "al": "Al", "p": "P", "mn": "Mn"
        }
        fallback_summaries = []
        for route, analytes in fallback_groups.items():
            brand, requested_stream, requested_brand, used_stream, used_brand = route
            fallback_summaries.append(
                f"{brand} fallback for "
                + ", ".join(analyte_labels.get(value, value) for value in analytes)
                + f": {requested_stream}[{requested_brand}] -> "
                + f"{used_stream}[{used_brand}]"
            )
        if source_type.startswith("amt chunk"):
            quality = copy.deepcopy(record.get("data_quality") or {})
            if not quality:
                quality = {
                    "lineage_coverage_pct": record.get("lineage_coverage_pct"),
                    "mapped_field_coverage_pct": {
                        name: record.get(f"{name}_coverage_pct")
                        for name in (
                            definition["name"]
                            for definition in normalize_field_definitions(
                                vars(self).get("field_definitions")
                            )
                        )
                        if record.get(f"{name}_coverage_pct") is not None
                    },
                    "geometry_quarantine_count": record.get(
                        "geometry_quarantine_count"
                    ),
                    "geometry_quarantine_hexes": record.get(
                        "geometry_quarantine_hexes"
                    ),
                }
                product_coverage = {}
                for warning in warnings:
                    for product, label, percentage in re.findall(
                        r"PROD([123])\s+(Fe|SiO₂|Al₂O₃|P|Mn)\s+(\d+(?:\.\d+)?)%",
                        warning,
                    ):
                        product_coverage[
                            f"PROD{product} {label}"
                        ] = float(percentage)
                quality["product_grade_coverage_pct"] = product_coverage
            opf_value = vars(self).get("opf_input_choice", "")
            product_slot = amt_modelled_product_slot(opf_value)
            product_grades_applicable = bool(product_slot) and not is_dry_plant(
                opf_value
            )
            if product_grades_applicable:
                product_prefix = str(product_slot).upper()
                labels = {
                    "fe": "Fe", "si": "SiO₂", "al": "Al₂O₃",
                    "p": "P", "mn": "Mn",
                }
                product_coverage = {
                    key: value
                    for key, value in dict(
                        quality.get("product_grade_coverage_pct") or {}
                    ).items()
                    if str(key).upper().startswith(product_prefix + " ")
                }
                for label in labels.values():
                    product_coverage.setdefault(
                        f"{product_prefix} {label}", None
                    )
                quality["product_grade_coverage_pct"] = product_coverage
            record["warnings"] = format_chunk_quality_warning(
                quality,
                fallbacks=fallback_summaries,
                product_grades_applicable=product_grades_applicable,
            )
        else:
            record["warnings"] = "; ".join(dict.fromkeys([
                *warnings, *fallback_summaries
            ]))
        record.pop("data_quality", None)
        # Database View now presents the exact Define Fields schema. Preserve
        # the canonical stream keys populated above; raw ``grade_*`` aliases
        # remain in the record only as hidden compatibility/audit data.
        return record

    @staticmethod
    def database_view_modelled_property_audit(values, coverage):
        """Return one canonical Database View field per AMT property.

        AMT properties are already modelled values.  Prefixing every key with
        ``modelled_`` produced duplicate and sometimes double-prefixed names
        (for example ``modelled_modelled_product_fe``).  Physical properties
        retain their common inventory/AMT key, while grade-stream properties
        use the same ``grade_<stream>_<analyte>`` family as all other sources.
        """
        fields = {}
        grade_pattern = re.compile(
            r"^(insitu|modelled_rom|adjusted_rom|modelled_product|adjusted_product)_"
            r"(fe|si|al|p|mn)$"
        )

        def audit_name(raw_name):
            name = canonical_property_key(raw_name)
            if not name:
                return ""
            match = grade_pattern.fullmatch(name)
            return f"grade_{name}" if match else name

        for raw_name, value in (values or {}).items():
            name = audit_name(raw_name)
            if name:
                fields[name] = value
        for raw_name, value in (coverage or {}).items():
            name = audit_name(raw_name)
            if not name:
                continue
            percentage = numeric(value)
            fields[f"{name}_coverage_pct"] = (
                percentage * 100.0 if percentage is not None else None
            )
        return fields

    @staticmethod
    def amt_chunk_footprint(chunk):
        """Return a stable parent footprint from current or legacy chunk rows."""
        if not isinstance(chunk, dict):
            return ""
        footprint = str(
            chunk.get("footprint")
            or chunk.get("FOOTPRINT")
            or chunk.get("parent_stockpile")
            or chunk.get("PARENT_STOCKPILE")
            or ""
        ).strip()
        if not footprint:
            source_id = str(
                chunk.get("hex")
                or chunk.get("HEX")
                or chunk.get("chunk_id")
                or chunk.get("CHUNK_ID")
                or chunk.get("source_id")
                or chunk.get("SOURCE_ID")
                or ""
            ).strip()
            footprint = re.sub(
                r"_CHUNK_\d+$", "", source_id, flags=re.IGNORECASE
            )
        return footprint.strip().upper()

    def selected_amt_footprints(self):
        """Return the selected inventory footprints represented spatially."""
        selected = {
            str(name).strip().upper()
            for name, enabled in (
                vars(self).get("stockpile_data_AMT_column", {}) or {}
            ).items()
            if bool(enabled) and str(name).strip()
        }
        for name, attributes in (
            vars(self).get("updated_stockpile_data", {}) or {}
        ).items():
            if not isinstance(attributes, dict):
                continue
            raw_flag = attributes.get("amt", attributes.get("AMT"))
            if isinstance(raw_flag, str):
                raw_flag = raw_flag.strip().lower() in {
                    "1", "true", "yes", "y", "amt"
                }
            if raw_flag and str(name).strip():
                selected.add(str(name).strip().upper())
        return selected - zeroed_amt_footprints(vars(self).get("AMT_stockpile_data")) - self.excluded_amt_footprints()

    def excluded_amt_footprints(self):
        return excluded_footprints(vars(self).get("AMT_footprint_exclusions"))

    def included_stockpile_data(self):
        return included_footprints(vars(self).get("updated_stockpile_data"), vars(self).get("AMT_footprint_exclusions"))

    def included_AMT_snapshot(self, snapshot):
        return included_footprints(snapshot, vars(self).get("AMT_footprint_exclusions"))

    def prune_excluded_AMT_state(self):
        """Remove excluded material without changing the inventory selection."""
        excluded = self.excluded_amt_footprints()
        draw = vars(self).get("draw_AMT_map")
        if draw is not None:
            draw.excluded_footprints = excluded
        if not excluded:
            return
        for name in ("AMT_stockpile_data", "AMT_chunk_settings", "total_AMT_stockpile_balances"):
            if name in vars(self):
                setattr(self, name, self.included_AMT_snapshot(vars(self)[name]))
        for name in ("hex_sequence_table", "hex_sequence_table_argument"):
            if name in vars(self):
                setattr(self, name, [r for r in vars(self)[name] or [] if self.amt_chunk_footprint(r) not in excluded])
        if draw is not None:
            if hasattr(draw, "selected_points"):
                draw.selected_points = [r for r in draw.selected_points or [] if self.amt_chunk_footprint(r) not in excluded]
            if isinstance(getattr(draw, "data", None), pd.DataFrame) and "footprint" in draw.data:
                draw.data = draw.data[~draw.data["footprint"].astype(str).str.strip().str.upper().isin(excluded)].copy()
            for name in ("chunk_settings", "dig_paths", "geometry_outliers", "reclaim_directions", "cut_directions"):
                if isinstance(getattr(draw, name, None), dict):
                    setattr(draw, name, self.included_AMT_snapshot(getattr(draw, name)))
            if hasattr(draw, "get_unique_footprints"):
                draw.unique_footprints = draw.get_unique_footprints()

    def set_amt_footprint_excluded(self, footprint, excluded):
        """Persist an explicit participation decision; restoration needs fresh data."""
        key = str(footprint).strip().upper()
        selected = {str(n).strip().upper(): r for n, r in (vars(self).get("updated_stockpile_data") or {}).items()}
        if key not in selected or not selected[key].get("amt", False):
            return False
        records = normalize_amt_exclusions(vars(self).get("AMT_footprint_exclusions"))
        if bool(excluded) == (key in excluded_footprints(records)):
            return False
        if excluded:
            rows = next((r for n, r in (vars(self).get("AMT_stockpile_data") or {}).items() if str(n).strip().upper() == key), [])
            first = rows[0] if rows else {}
            records[key] = exclusion_audit(
                key, reason="Excluded using Include footprint in AMT setup.", timestamp=datetime.now().isoformat(),
                raw_wmt=raw_amt_hex_total(rows), inventory_wmt=numeric(selected[key].get("balance")),
                spatial_wmt=numeric(first.get("SPATIALLY_CORRECTED_STOCKPILE_WMT")),
                final_wmt=sum(max(numeric(r.get("FINAL_WMT", r.get("balance"))) or 0, 0) for r in rows) if rows else None,
                source_rows=len(rows),
            )
        else:
            records[key] = {"schema_version": 1, "footprint_id": key, "excluded": False,
                            "restored_at": datetime.now().isoformat(), "last_exclusion": records[key]}
        self.AMT_footprint_exclusions = records
        self.prune_excluded_AMT_state()
        self.AMT_enrichment_signature = ""
        self.AMT_chunk_reconciliation_signature = ""
        self.database_view_snapshot_signature = None
        self.database_view_rows = []
        self.database_view_refresh_pending = True
        self._reconciliation_review_signature = ""
        self._available_mapping_fields_cache = {}
        return True

    def handle_AMT_footprint_inclusion_change(self, row, _column):
        if _column != self.AMT_column_index("Include footprint"):
            return
        name = self.AMT_stockpile_table.item(row, 0)
        item = self.AMT_stockpile_table.item(row, _column)
        if not name or not item or not self.set_amt_footprint_excluded(name.text(), item.checkState() != Qt.Checked):
            return
        # Persist only retained rows. Exclusion itself never fetches or enriches.
        self.opening_stockpile_inventories.save_AMT_to_database(self.AMT_stockpile_data)
        if vars(self).get("stockpile_data"):
            self.opening_stockpile_inventories.save_to_database(self.included_AMT_snapshot(self.stockpile_data))
        DatabaseManager.clear_scheduling_reports()
        self.current_sqlite_report_df = pd.DataFrame()
        self.scenario_report_refresh_pending = True
        self.current_decision_dataframe = pd.DataFrame()
        self.decision_run_dataframe = pd.DataFrame()
        self.finish_AMT_stockpile_table(self.selected_AMT_data_source(), self.AMT_stockpile_data, reuse_prepared=True)
        self.refresh_AMT_map_data_from_database()
        self.set_AMT_cache_status("Footprint selection updated; previous scheduling reports need recalculation. Use Refresh AMT Data from Snowflake to load restored footprints.")
        self.save_active_scenario_state()

    def validate_AMT_participation(self):
        if self.excluded_amt_footprints() and not self.included_stockpile_data():
            raise ValueError("All AMT footprints are excluded. Select at least one conventional inventory stockpile or restore an AMT footprint before continuing.")

    def prune_zeroed_amt_chunks(self):
        """Remove known zeroed footprints from every live scheduling snapshot."""
        self.prune_excluded_AMT_state()
        zeroed = zeroed_amt_footprints(vars(self).get("AMT_stockpile_data"))
        if not zeroed:
            return 0
        removed = 0
        def keep(rows):
            nonlocal removed
            kept = [row for row in rows or [] if self.amt_chunk_footprint(row) not in zeroed]
            removed += len(rows or []) - len(kept)
            return kept
        for name in ("hex_sequence_table", "hex_sequence_table_argument"):
            if name in vars(self):
                setattr(self, name, keep(vars(self)[name]))
        draw = vars(self).get("draw_AMT_map")
        if draw is not None and hasattr(draw, "selected_points"):
            draw.selected_points = keep(draw.selected_points)
        if removed:
            self.AMT_chunk_reconciliation_signature = ""
            self.database_view_rows = []
            self.database_view_snapshot_signature = None
            self.database_view_refresh_pending = True
            self.total_AMT_stockpile_balances = {
                name: value for name, value in (vars(self).get("total_AMT_stockpile_balances") or {}).items()
                if str(name).strip().upper() not in zeroed
            }
        return removed

    def submitted_amt_chunks(self):
        """Merge canonical, solver-snapshot and current-map AMT chunk rows.

        The Qt state is authoritative after submission, but a Dash callback can
        finish just after that snapshot is captured.  Including the live map
        rows prevents Database View from temporarily presenting a valid chunked
        footprint as a weighted-average stockpile.  Canonical rows win when the
        same chunk exists in more than one source.
        """
        sources = [
            vars(self).get("hex_sequence_table", []) or [],
            vars(self).get("hex_sequence_table_argument", []) or [],
        ]
        draw_amt = vars(self).get("draw_AMT_map")
        if draw_amt is not None:
            sources.append(getattr(draw_amt, "selected_points", []) or [])

        chunks = []
        seen = set()
        zeroed = zeroed_amt_footprints(vars(self).get("AMT_stockpile_data")) | self.excluded_amt_footprints()
        for source in sources:
            for chunk in source:
                if not isinstance(chunk, dict):
                    continue
                footprint = self.amt_chunk_footprint(chunk)
                chunk_id = str(
                    chunk.get("hex")
                    or chunk.get("HEX")
                    or chunk.get("chunk_id")
                    or chunk.get("CHUNK_ID")
                    or chunk.get("source_id")
                    or chunk.get("SOURCE_ID")
                    or ""
                ).strip().upper()
                sequence = numeric(
                    chunk.get("sequence", chunk.get("SEQUENCE"))
                )
                identity = chunk_id or (footprint, sequence)
                if not footprint or footprint in zeroed or identity in seen:
                    continue
                seen.add(identity)
                chunks.append(copy.deepcopy(chunk))
        return chunks

    def database_view_stockpile_rows(self):
        records = []
        selected_stockpiles = copy.deepcopy(
            self.included_stockpile_data()
        )
        selected_chunks = self.submitted_amt_chunks()
        zeroed = zeroed_amt_footprints(vars(self).get("AMT_stockpile_data"))

        chunks_by_footprint = {}
        for chunk in selected_chunks:
            footprint_key = self.amt_chunk_footprint(chunk)
            if footprint_key:
                chunks_by_footprint.setdefault(footprint_key, []).append(chunk)

        amt_selections = {
            str(name).strip().upper(): bool(selected)
            for name, selected in (
                vars(self).get("stockpile_data_AMT_column", {}) or {}
            ).items()
        }

        for stockpile_name, attributes in selected_stockpiles.items():
            attributes = attributes or {}
            stockpile_key = str(stockpile_name).strip().upper()
            chunks = chunks_by_footprint.get(stockpile_key, [])
            raw_amt_flag = attributes.get(
                "amt", attributes.get("AMT", amt_selections.get(stockpile_key))
            )
            if isinstance(raw_amt_flag, str):
                raw_amt_flag = raw_amt_flag.strip().lower() in {
                    "1", "true", "yes", "y", "amt"
                }
            # A submitted chunk is the authoritative representation choice.
            # It must suppress the weighted-average inventory instance even if
            # a live/restored scenario contains a stale or missing AMT flag.
            if chunks or bool(raw_amt_flag):
                if stockpile_key in zeroed:
                    continue
                footprint_rows = (
                    getattr(self, "AMT_stockpile_data", {}) or {}
                ).get(stockpile_name, []) or []
                provenance = footprint_rows[0] if footprint_rows else {}
                if not chunks:
                    records.append(self.database_view_record_with_streams(
                        {
                            "source_type": "AMT Stockpile - No Chunks",
                            "source_id": stockpile_name,
                            "parent_stockpile": stockpile_name,
                            "tonnes": 0.0,
                        },
                        attributes.get("grade_streams")
                        or attributes.get("GRADE_STREAMS"),
                        attributes,
                        [
                            "Selected as AMT but no submitted chunk matching "
                            f"{stockpile_name} was found. Return to AMT "
                            "Stockpiles and regenerate or resubmit this footprint."
                        ],
                    ))
                    continue

                for chunk in sorted(
                    chunks,
                    key=lambda item: (
                        numeric(item.get("sequence")) or float("inf"),
                        str(item.get("hex") or item.get("chunk_id") or ""),
                    ),
                ):
                    lineage_audit = self.database_view_chunk_lineage_audit(
                        chunk,
                        footprint_rows,
                        single_chunk=(len(chunks) == 1),
                    )
                    chunk_quality = copy.deepcopy(
                        chunk.get("data_quality") or {}
                    )
                    if (
                        chunk_quality.get("lineage_coverage_pct") is None
                        and lineage_audit.get("lineage_coverage_pct") is not None
                    ):
                        chunk_quality["lineage_coverage_pct"] = (
                            lineage_audit["lineage_coverage_pct"]
                        )
                    chunk_id = (
                        chunk.get("hex")
                        or chunk.get("chunk_id")
                        or chunk.get("source_id")
                        or ""
                    )
                    modelled_payload = chunk.get("modelled_properties") or {}
                    modelled_values = (
                        modelled_payload.get("values", {})
                        if isinstance(modelled_payload, dict) else {}
                    )
                    modelled_coverage = (
                        modelled_payload.get("coverage", {})
                        if isinstance(modelled_payload, dict) else {}
                    )
                    property_audit = self.database_view_modelled_property_audit(
                        modelled_values, modelled_coverage
                    )
                    records.append(self.database_view_record_with_streams(
                        {
                            "source_type": "AMT Chunk",
                            "source_id": chunk_id,
                            "parent_stockpile": stockpile_name,
                            "build_or_chunk": chunk_id,
                            "sequence": chunk.get("sequence"),
                            "tonnes": numeric(
                                chunk.get("balance", chunk.get("tonnes"))
                            ) or 0.0,
                            "grade_block_count": (
                                chunk.get("grade_block_count")
                                if chunk.get("grade_block_count") is not None
                                else lineage_audit.get("grade_block_count")
                            ),
                            "lineage_coverage_pct": (
                                chunk.get("lineage_coverage_pct")
                                if chunk.get("lineage_coverage_pct") is not None
                                else lineage_audit.get("lineage_coverage_pct")
                            ),
                            "lineage_unmatched_wmt": (
                                chunk.get("lineage_unmatched_wmt")
                                if chunk.get("lineage_unmatched_wmt") is not None
                                else lineage_audit.get("lineage_unmatched_wmt")
                            ),
                            "raw_wmt": chunk.get("raw_wmt"),
                            "spatially_corrected_wmt": chunk.get(
                                "spatially_corrected_wmt"
                            ),
                            "spatial_adjustment_wmt": chunk.get(
                                "spatial_adjustment_wmt"
                            ),
                            "ledger_adjustment_wmt": chunk.get(
                                "ledger_adjustment_wmt"
                            ),
                            "geometry_quarantine_count": chunk.get(
                                "geometry_quarantine_count"
                            ),
                            "geometry_quarantine_wmt": chunk.get(
                                "geometry_quarantine_wmt"
                            ),
                            "geometry_quarantine_hexes": chunk.get(
                                "geometry_quarantine_hexes"
                            ),
                            "cb_split_method": chunk.get(
                                "cb_split_method", ""
                            ),
                            "cb_split_warning": chunk.get(
                                "cb_split_warning", ""
                            ),
                            "data_quality": chunk_quality,
                            "defined_fields": chunk.get("defined_fields", {}),
                            "source_properties": chunk.get(
                                "source_properties", {}
                            ),
                            "matched_inventory_stockpile": provenance.get(
                                "AMT_INVENTORY_STOCKPILE",
                                provenance.get(
                                    "internal_recon_inventory_stockpile",
                                    provenance.get("INTERNAL_RECON_INVENTORY_STOCKPILE", ""),
                                ),
                            ),
                            "matched_inventory_build": provenance.get(
                                "AMT_INVENTORY_BUILD",
                                provenance.get(
                                    "internal_recon_inventory_build",
                                    provenance.get("INTERNAL_RECON_INVENTORY_BUILD", ""),
                                ),
                            ),
                            "matched_inventory_time": provenance.get(
                                "AMT_INVENTORY_TRANSACTION_DATETIME",
                                provenance.get(
                                    "internal_recon_inventory_transaction_datetime",
                                    provenance.get("INTERNAL_RECON_INVENTORY_TRANSACTION_DATETIME", ""),
                                ),
                            ),
                            **property_audit,
                        },
                        chunk.get("grade_streams")
                        or chunk.get("GRADE_STREAMS"),
                        chunk,
                        chunk.get("grade_stream_warnings")
                        or chunk.get("GRADE_STREAM_WARNINGS")
                        or [],
                    ))
                continue

            inventory_audit = inventory_additional_values(attributes)
            records.append(self.database_view_record_with_streams(
                {
                    "source_type": "Inventory Stockpile",
                    "source_id": stockpile_name,
                    "parent_stockpile": stockpile_name,
                    "build_or_chunk": attributes.get("build", ""),
                    "tonnes": numeric(attributes.get("balance")) or 0.0,
                    "defined_fields": attributes.get("defined_fields", {}),
                    "source_properties": attributes.get(
                        "source_properties", {}
                    ),
                    **inventory_audit,
                },
                attributes.get("grade_streams")
                or attributes.get("GRADE_STREAMS"),
                attributes,
                attributes.get("grade_stream_warnings")
                or attributes.get("GRADE_STREAM_WARNINGS")
                or [],
            ))
        return records

    @staticmethod
    def database_view_chunk_lineage_audit(
        chunk, footprint_rows, *, single_chunk=False
    ):
        """Recover chunk lineage audit values from its member AMT hexes."""
        chunk = chunk if isinstance(chunk, dict) else {}
        member_hexes = chunk.get("member_hexes")
        if isinstance(member_hexes, str):
            member_hexes = {
                value.strip() for value in member_hexes.split(",")
                if value.strip()
            }
        elif isinstance(member_hexes, (list, tuple, set)):
            member_hexes = {
                str(value).strip() for value in member_hexes
                if str(value).strip()
            }
        else:
            member_hexes = set()

        rows = []
        for row in footprint_rows or []:
            if not isinstance(row, dict):
                continue
            hex_id = str(row.get("HEX", row.get("hex", "")) or "").strip()
            if member_hexes and hex_id not in member_hexes:
                continue
            if not member_hexes and not single_chunk:
                continue
            rows.append(row)
        if not rows:
            return {}

        lineage_keys = set()
        total_wmt = 0.0
        matched_wmt = 0.0
        for row in rows:
            tonnes = numeric(
                row.get(
                    "FINAL_WMT",
                    row.get("final_wmt", row.get("BALANCE", row.get("balance"))),
                )
            )
            tonnes = max(tonnes or 0.0, 0.0)
            total_wmt += tonnes

            lineage = row.get("GRADE_BLOCK_LINEAGE", row.get("grade_block_lineage"))
            if lineage is None:
                lineage = row.get(
                    "GRADE_BLOCK_LINEAGE_JSON",
                    row.get("grade_block_lineage_json"),
                )
            if isinstance(lineage, str):
                try:
                    lineage = json.loads(lineage)
                except (TypeError, ValueError):
                    lineage = []
            for contribution in lineage if isinstance(lineage, list) else []:
                key = str((contribution or {}).get("lineage_key") or "")
                if key and key.upper() != "UNMATCHED":
                    lineage_keys.add(key)

            matched = numeric(row.get(
                "LINEAGE_MATCHED_FINAL_WMT",
                row.get("lineage_matched_final_wmt"),
            ))
            if matched is None:
                coverage = numeric(row.get(
                    "LINEAGE_COVERAGE_PCT",
                    row.get("lineage_coverage_pct"),
                ))
                matched = (
                    tonnes * min(max(coverage, 0.0), 100.0) / 100.0
                    if coverage is not None else 0.0
                )
            matched_wmt += min(max(matched, 0.0), tonnes)

        if total_wmt <= 0:
            return {}
        unmatched_wmt = max(total_wmt - matched_wmt, 0.0)
        if unmatched_wmt < 1e-6:
            unmatched_wmt = 0.0
        return {
            "grade_block_count": len(lineage_keys),
            "lineage_coverage_pct": matched_wmt / total_wmt * 100.0,
            "lineage_unmatched_wmt": unmatched_wmt,
        }

    def database_view_grade_block_rows(self, transactions):
        """Consolidate APS payload movements to one tonnes/grades row per block."""
        if transactions is None or transactions.empty:
            return []

        definitions = vars(self).get("field_definitions")
        property_kinds = (
            {
                row["name"]: row["kind"]
                for row in normalize_field_definitions(definitions)
            }
            if definitions is not None else {}
        )
        property_weights = (
            field_weight_map(definitions) if definitions is not None else {}
        )

        grouped = {}
        for transaction in transactions.to_dict(orient="records"):
            source = str(
                transaction.get("source")
                or transaction.get("direct_tip_id")
                or "Unidentified grade block"
            ).strip()
            tonnes = max(numeric(transaction.get("payload")) or 0.0, 0.0)
            group = grouped.setdefault(source, {
                "tonnes": 0.0,
                "raw_mass": {analyte: 0.0 for analyte in ANALYTES},
                "raw_tonnes": {analyte: 0.0 for analyte in ANALYTES},
                "grade_streams": None,
                "source_properties": {},
            })
            previous_tonnes = group["tonnes"]
            group["tonnes"] += tonnes
            previous_properties = group["source_properties"]
            incoming_properties = source_properties_from_mapping(transaction)
            group["source_properties"] = merge_source_properties(
                previous_properties,
                previous_tonnes,
                incoming_properties,
                tonnes,
                property_kinds,
                property_weights,
            )

            fallback = {
                f"grade_{analyte}": transaction.get(
                    f"source_grade_{analyte}"
                )
                for analyte in ANALYTES
            }
            for analyte in ANALYTES:
                value = numeric(fallback.get(f"grade_{analyte}"))
                if value is not None and tonnes > 0:
                    group["raw_mass"][analyte] += value * tonnes
                    group["raw_tonnes"][analyte] += tonnes

            streams = normalise_grade_streams(
                transaction.get("grade_streams"), fallback
            )
            group["grade_streams"] = weighted_merge_grade_streams(
                group["grade_streams"],
                previous_tonnes,
                streams,
                tonnes,
                previous_properties,
                incoming_properties,
                property_weights,
            )

        rows = []
        for source, group in grouped.items():
            fallback = {
                f"grade_{analyte}": (
                    group["raw_mass"][analyte]
                    / group["raw_tonnes"][analyte]
                    if group["raw_tonnes"][analyte] > 0
                    else None
                )
                for analyte in ANALYTES
            }
            streams = normalise_grade_streams(
                group["grade_streams"], fallback
            )
            streams = reweight_grade_streams_from_properties(
                streams, group["source_properties"]
            )
            rows.append(self.database_view_record_with_streams(
                {
                    **group["source_properties"],
                    "source_type": "APS Grade Block",
                    "source_id": source,
                    "parent_stockpile": "",
                    "build_or_chunk": "",
                    "sequence": "",
                    "tonnes": group["tonnes"],
                },
                streams,
                fallback,
            ))
        return rows

    def prepare_database_view_data(self, refresh_generation=None):
        """Build source tonnes/grades and retain the exact APS run snapshot."""
        request_signature = getattr(
            self, "database_view_signature_snapshot", None
        )
        records = self.database_view_stockpile_rows()
        warnings = []
        transactions = pd.DataFrame()
        schedule_path = str(
            getattr(self, "file_path_24hr_choice", "") or ""
        ).strip()
        expit_cache_signature = getattr(
            self, "database_view_expit_cache_signature_snapshot", ""
        )
        expit_cache_allowed = bool(getattr(
            self, "database_view_expit_cache_allowed_snapshot", False
        ))
        expit_cache_hit = False
        if schedule_path:
            try:
                site_context = copy.deepcopy(
                    getattr(
                        self,
                        "database_view_site_context_snapshot",
                        None,
                    )
                    or self.active_site_context()
                )
                if expit_cache_allowed:
                    transactions, _cache_metadata = (
                        self.read_reusable_expit_input_cache(
                            expit_cache_signature
                        )
                    )
                    expit_cache_hit = transactions is not None
                if transactions is None or not expit_cache_hit:
                    transactions = self.run_program.prepare_expit_payload_transactions(
                        getattr(self, "database_view_start_time_snapshot", None)
                        or self.start_time_choice,
                        self.expit_mode_choice,
                        schedule_path,
                        getattr(self, "reevaluate_aps_direct_tip_choice", False),
                        getattr(self, "aps_direct_tip_crusher_choice", []),
                        site_context,
                        getattr(self, "file_path_choice", ""),
                        getattr(self, "selected_24hr_expit_agents", []),
                    )
                warnings.extend(
                    transactions.attrs.get(
                        "source_property_warnings", []
                    )
                )
            except Exception as exc:
                warnings.append(f"APS 24HR payload preparation failed: {exc}")
                transactions = pd.DataFrame()

        periods = self.database_view_periods()
        window_start = pd.Timestamp(
            getattr(self, "database_view_start_time_snapshot", None)
            or self.start_time_choice
            or datetime.now()
        )
        window_end = pd.Timestamp(periods.horizon_end())
        horizon_transactions = transactions.copy()
        if not horizon_transactions.empty:
            delivered = pd.to_datetime(
                horizon_transactions.get("delivered_datetime"),
                errors="coerce",
            )
            horizon_transactions = horizon_transactions[
                delivered.notna()
                & (delivered >= window_start)
                & (delivered < window_end)
            ].copy()
            if horizon_transactions.empty:
                valid_deliveries = delivered.dropna()
                observed_range = (
                    f" Observed APS delivery range: "
                    f"{valid_deliveries.min()} to {valid_deliveries.max()}."
                    if not valid_deliveries.empty
                    else " APS delivery timestamps are missing or invalid."
                )
                warnings.append(
                    "No APS 24HR payloads have delivery times inside the "
                    f"configured planning horizon ({window_start} to "
                    f"{window_end}).{observed_range}"
                )

        records.extend(
            self.database_view_grade_block_rows(horizon_transactions)
        )

        return {
            "records": records,
            "transactions": transactions,
            "warnings": warnings,
            "window_start": window_start,
            "window_end": window_end,
            "signature": (
                request_signature
                or self.database_view_input_signature()
            ),
            "expit_cache_signature": expit_cache_signature,
            "expit_cache_hit": expit_cache_hit,
            "refresh_generation": refresh_generation,
        }

    def apply_database_view_stockpile_calculations(
        self, records, transactions
    ):
        """Expose the stockpile readiness calculations used by DataLoader."""
        calendar = copy.deepcopy(
            getattr(self, "database_view_calendar_inputs", None)
            or getattr(self, "calendar_inputs", None)
            or {}
        )
        stockpiles = getattr(self, "updated_stockpile_data", {}) or {}
        start_time = (
            getattr(self, "database_view_start_time_snapshot", None)
            or self.start_time_choice
            or datetime.now()
        )
        periods = self.database_view_periods()
        horizon_start = pd.Timestamp(start_time)
        horizon_end = pd.Timestamp(periods.horizon_end())
        period_pairs = list(zip(periods.period_keys(), periods.period_labels()))
        transaction_rows = (
            transactions.to_dict(orient="records")
            if transactions is not None and not transactions.empty
            else []
        )

        for stockpile_name, attributes in stockpiles.items():
            attributes = attributes or {}
            calendar_name = str(
                attributes.get("name") or stockpile_name
            )
            states = calendar.get(
                f"stockpiles_{calendar_name}_state", {}
            ) or {}
            maximums = calendar.get(
                f"stockpiles_{calendar_name}_maximum_quantity", {}
            ) or {}
            related = [
                transaction for transaction in transaction_rows
                if str(transaction.get("destination") or "").replace(
                    "Stockpiles/", ""
                ) == stockpile_name
            ]
            incoming_tonnes = sum(
                numeric(transaction.get("payload")) or 0.0
                for transaction in related
            )
            related_in_horizon = []
            for transaction in related:
                delivered = pd.to_datetime(
                    transaction.get("delivered_datetime"), errors="coerce"
                )
                if (
                    pd.notna(delivered)
                    and horizon_start <= delivered < horizon_end
                ):
                    related_in_horizon.append(transaction)
            horizon_incoming_tonnes = sum(
                numeric(transaction.get("payload")) or 0.0
                for transaction in related_in_horizon
            )
            outside_horizon_tonnes = (
                incoming_tonnes - horizon_incoming_tonnes
            )
            delivered_times = [
                pd.to_datetime(
                    transaction.get("delivered_datetime"), errors="coerce"
                )
                for transaction in related
            ]
            delivered_times = [
                value for value in delivered_times if pd.notna(value)
            ]
            latest_delivery = max(delivered_times) if delivered_times else None

            source_rows = [
                record for record in records
                if record.get("source_type") in {
                    "Inventory Stockpile",
                    "AMT Chunk",
                    "AMT Stockpile - No Chunks",
                }
                and str(record.get("parent_stockpile") or "").upper()
                == str(stockpile_name).upper()
            ]
            ordered_chunks = sorted(
                [
                    record for record in source_rows
                    if record.get("source_type") == "AMT Chunk"
                ],
                key=lambda record: (
                    numeric(record.get("sequence")) or float("inf"),
                    str(record.get("source_id") or ""),
                ),
            )
            if ordered_chunks:
                initial_balance = (
                    numeric(ordered_chunks[0].get("tonnes")) or 0.0
                )
                total_selected_tonnes = sum(
                    numeric(record.get("tonnes")) or 0.0
                    for record in ordered_chunks
                )
            else:
                initial_balance = numeric(attributes.get("balance")) or 0.0
                total_selected_tonnes = initial_balance

            reclaim_threshold = (
                numeric(attributes.get("reclaim_threshold")) or 0.0
            )
            projected_balance = initial_balance + incoming_tonnes
            is_ready = projected_balance >= reclaim_threshold
            auto_turnover = latest_delivery if related and is_ready else None
            preplan_state = str(states.get("Preplan") or "")
            auto_ready_at_start = (
                auto_turnover is None
                or auto_turnover.to_pydatetime() <= start_time
            )

            for record in source_rows:
                record["opening_model_balance"] = initial_balance
                record["total_selected_stockpile_tonnes"] = total_selected_tonnes
                record["aps_incoming_tonnes"] = incoming_tonnes
                record["aps_incoming_tonnes_in_horizon"] = (
                    horizon_incoming_tonnes
                )
                record["aps_incoming_tonnes_outside_horizon"] = (
                    outside_horizon_tonnes
                )
                record["projected_balance_after_aps"] = projected_balance
                record["reclaim_threshold"] = reclaim_threshold
                record["auto_turnover_datetime"] = auto_turnover or ""
                record["is_ready_after_aps"] = is_ready
                for period_key, period_label in period_pairs:
                    record[f"calendar_state_{period_key}"] = states.get(
                        period_label, ""
                    )
                    record[f"calendar_max_tonnes_{period_key}"] = maximums.get(
                        period_label, ""
                    )

                is_first_chunk = (
                    record.get("source_type") != "AMT Chunk"
                    or record is ordered_chunks[0]
                )
                first_available = (
                    is_first_chunk
                    and initial_balance >= 0
                    and (
                        preplan_state == "Reclaim"
                        or (
                            preplan_state == "Auto"
                            and auto_ready_at_start
                            and initial_balance >= reclaim_threshold
                        )
                    )
                )
                record["available_at_scenario_start"] = first_available
                if (
                    is_first_chunk
                    and preplan_state == "Auto"
                    and not auto_ready_at_start
                ):
                    readiness_warning = (
                        "Auto stockpile withheld until APS deliveries "
                        f"complete at {auto_turnover}."
                    )
                    if pd.Timestamp(auto_turnover) >= horizon_end:
                        readiness_warning += (
                            " That turnover is outside the configured "
                            "planning horizon."
                        )
                    existing = str(record.get("warnings") or "")
                    record["warnings"] = "; ".join(
                        value
                        for value in (existing, readiness_warning)
                        if value
                    )

    def open_database_view(self, navigate=True):
        self.set_page_enabled(self.database_view_tab_index, True)
        self.database_view_refresh_pending = True
        if navigate:
            self.show_page(self.database_view_tab_index, force=True)
        self.refresh_database_view()

    def refresh_database_view(self):
        if getattr(self, "database_view_refresh_in_progress", False):
            return
        self.reconcile_saved_AMT_chunk_grade_streams()
        self.database_view_refresh_in_progress = True
        self.database_view_refresh_pending = False
        self.database_view_refresh_generation = (
            getattr(self, "database_view_refresh_generation", 0) + 1
        )
        refresh_generation = self.database_view_refresh_generation
        self.database_view_rows = []
        self.database_view_expit_payload_transactions = None
        self.database_view_snapshot_signature = None
        self.database_view_table.clearContents()
        self.database_view_table.setRowCount(0)
        self.database_view_table.setColumnCount(0)
        self.database_view_continue_button.setEnabled(False)
        self.database_view_period_count_snapshot = self.planning_period_count()
        self.database_view_start_time_snapshot = (
            self.start_time_choice or datetime.now()
        )
        self.database_view_site_context_snapshot = self.active_site_context()
        self.database_view_expit_cache_signature_snapshot = (
            self.expit_input_cache_signature(
                start_time=self.database_view_start_time_snapshot,
                site_context=self.database_view_site_context_snapshot,
            )
        )
        self.database_view_expit_cache_allowed_snapshot = (
            self.expit_input_cache_allowed()
        )
        self.database_view_signature_snapshot = (
            self.database_view_input_signature()
        )
        self.database_view_refresh_button.setEnabled(False)
        self.database_view_summary_label.setText(
            "Preparing selected stockpiles, AMT chunks, and APS grade blocks..."
        )
        self.run_background_task(
            "Preparing Database View model inputs...",
            lambda: self.prepare_database_view_data(refresh_generation),
            self.finish_database_view_data,
            lambda error: self.handle_database_view_error(
                error, refresh_generation
            ),
        )

    def finish_database_view_data(self, result):
        if result.get("refresh_generation") != getattr(
            self, "database_view_refresh_generation", None
        ):
            return
        self.database_view_refresh_in_progress = False
        self.database_view_refresh_button.setEnabled(True)
        if result.get("signature") != self.database_view_input_signature():
            self.database_view_refresh_pending = True
            self.database_view_rows = []
            self.database_view_expit_payload_transactions = None
            self.database_view_snapshot_signature = None
            self.database_view_continue_button.setEnabled(False)
            self.database_view_warning_label.setText(
                "Database View inputs changed while it was being prepared. "
                "Refresh the view before continuing."
            )
            self.database_view_warning_label.show()
            self.database_view_summary_label.setText(
                "Database View refresh required."
            )
            return
        self.database_view_rows = result.get("records", []) or []
        self.database_view_expit_payload_transactions = result.get(
            "transactions", pd.DataFrame()
        )
        expit_cache_signature = str(
            result.get("expit_cache_signature") or ""
        )
        if (
            expit_cache_signature
            and not result.get("expit_cache_hit", False)
            and self.database_view_expit_payload_transactions is not None
        ):
            DatabaseManager().write_expit_input_cache(
                self.database_view_expit_payload_transactions,
                expit_cache_signature,
                metadata={
                    "source": "database_view",
                    "scenario_start": self.expit_signature_datetime(
                        getattr(self, "database_view_start_time_snapshot", None)
                    ),
                },
            )
        expit_attributes = dict(
            getattr(
                self.database_view_expit_payload_transactions,
                "attrs",
                {},
            ) or {}
        )
        if expit_attributes.get("expit_sequence_summary"):
            self.expit_sequence_snapshot = {
                "transactions": self.database_view_expit_payload_transactions,
                "planned_transactions": expit_attributes.get(
                    "expit_sequence_planned_transactions", pd.DataFrame()
                ),
                "audit": expit_attributes.get(
                    "expit_sequence_audit", pd.DataFrame()
                ),
                "geometry": expit_attributes.get(
                    "expit_sequence_geometry", pd.DataFrame()
                ),
                "geological_blocks": expit_attributes.get(
                    "expit_sequence_geological_blocks", pd.DataFrame()
                ),
                "actual_movements": expit_attributes.get(
                    "expit_sequence_actual_movements", pd.DataFrame()
                ),
                "summary": expit_attributes.get(
                    "expit_sequence_summary", {}
                ),
                "warnings": expit_attributes.get(
                    "expit_sequence_warnings", []
                ),
            }
            DatabaseManager().write_expit_sequence_reconciliation(
                expit_attributes
            )
        self.database_view_snapshot_signature = result.get("signature")
        self.database_view_refresh_pending = False
        warnings = result.get("warnings", []) or []
        self.database_view_warning_label.setText("\n".join(warnings))
        self.database_view_warning_label.setVisible(bool(warnings))
        self.populate_database_view_table()
        self.database_view_continue_button.setEnabled(True)

        counts = {}
        tonnes = 0.0
        for record in self.database_view_rows:
            source_type = str(record.get("source_type") or "Unknown")
            counts[source_type] = counts.get(source_type, 0) + 1
            tonnes += numeric(record.get("tonnes")) or 0.0
        count_text = ", ".join(
            f"{source_type}: {count}"
            for source_type, count in counts.items()
        ) or "No source rows"
        self.database_view_summary_label.setText(
            f"Planning window: {result.get('window_start')} to "
            f"{result.get('window_end')} | {count_text} | "
            f"Total audited source tonnes: {tonnes:,.0f}"
            + (
                " | Expit inputs: restored from saved project"
                if result.get("expit_cache_hit", False)
                else ""
            )
        )

    def handle_database_view_error(
        self, error_message, refresh_generation=None
    ):
        if (
            refresh_generation is not None
            and refresh_generation != getattr(
                self, "database_view_refresh_generation", None
            )
        ):
            return
        self.database_view_refresh_in_progress = False
        self.database_view_refresh_pending = True
        self.database_view_rows = []
        self.database_view_expit_payload_transactions = None
        self.database_view_snapshot_signature = None
        self.database_view_refresh_button.setEnabled(True)
        self.database_view_continue_button.setEnabled(False)
        self.database_view_table.clearContents()
        self.database_view_table.setRowCount(0)
        self.database_view_table.setColumnCount(0)
        self.database_view_warning_label.setText(str(error_message))
        self.database_view_warning_label.show()
        self.database_view_summary_label.setText(
            "Database View could not be prepared."
        )

    @staticmethod
    def database_view_is_coverage_field(header):
        return str(header or "").lower().endswith("_coverage_pct")

    @classmethod
    def database_view_is_automatic_audit_field(cls, header):
        name = str(header or "").strip().lower()
        return bool(
            cls.database_view_is_coverage_field(name)
            or name.startswith("recon_")
            or "lineage" in name
            or name == "grade_block_count"
        )

    def database_view_all_headers(self, include_coverage=None):
        fixed = [
            "source_type", "source_id", "parent_stockpile",
            "build_or_chunk", "sequence", "selected_stream",
        ]
        defined = [
            row["name"] for row in normalize_field_definitions(
                vars(self).get("field_definitions")
            )
        ]
        audit = sorted({
            key
            for record in self.database_view_rows
            for key in record
            if self.database_view_is_automatic_audit_field(key)
        })
        headers = list(dict.fromkeys(evidence_display_column(h) for h in [*fixed, *defined, *audit, "warnings"]
                                    if evidence_display_column(h) is not None))
        if include_coverage is None:
            include_coverage = bool(
                getattr(self, "database_view_show_coverage_fields", False)
            )
        if not include_coverage:
            headers = [
                header for header in headers
                if not self.database_view_is_coverage_field(header)
            ]
        return headers

    def default_database_view_columns(self, headers):
        identity = {
            "source_type", "source_id", "parent_stockpile",
            "build_or_chunk", "sequence", "selected_stream",
        }
        return [
            header for header in headers
            if (
                header in identity
                or header.startswith("recon_")
                or header in {"modelled_rom_wmt", "modelled_rom_dmt"}
                or header.startswith("insitu_")
                or header.startswith(f"{getattr(self, 'selected_data_stream', '')}_")
            )
        ]

    def database_view_headers(self):
        for name in ("database_view_selected_columns", "database_view_known_columns"):
            previous = vars(self).get(name)
            if previous is not None:
                setattr(self, name, list(dict.fromkeys(evidence_display_column(h) for h in previous
                                                      if evidence_display_column(h) is not None)))
        all_headers = self.database_view_all_headers()
        selected = getattr(self, "database_view_selected_columns", None)
        if selected is None:
            selected = self.default_database_view_columns(all_headers)
            self.database_view_selected_columns = list(selected)
        else:
            known = getattr(self, "database_view_known_columns", None)
            if known is not None:
                new_defaults = [
                    header
                    for header in self.default_database_view_columns(
                        all_headers
                    )
                    if header not in set(known)
                ]
                if new_defaults:
                    selected = [*selected, *new_defaults]
                    self.database_view_selected_columns = list(
                        dict.fromkeys(selected)
                    )
        self.database_view_known_columns = list(all_headers)
        selected_set = set(selected)
        headers = [header for header in all_headers if header in selected_set]
        if not headers and all_headers:
            headers = self.default_database_view_columns(all_headers)
            self.database_view_selected_columns = list(headers)
        return headers

    def update_database_view_column_button(self):
        if not hasattr(self, "database_view_column_button"):
            return
        all_headers = self.database_view_all_headers()
        selected = set(
            getattr(self, "database_view_selected_columns", []) or []
        )
        selected_count = sum(header in selected for header in all_headers)
        total_count = len(all_headers)
        self.database_view_column_button.setText(
            f"Choose Fields... ({selected_count}/{total_count})"
        )

    def choose_database_view_columns(self):
        all_headers = self.database_view_all_headers(include_coverage=True)
        if not all_headers:
            return
        selected = set(
            getattr(self, "database_view_selected_columns", None)
            or self.default_database_view_columns(all_headers)
        )
        dialog = QDialog(self)
        dialog.setWindowTitle("Database View Fields")
        dialog.resize(520, 650)
        layout = QVBoxLayout(dialog)
        search = QLineEdit()
        search.setPlaceholderText("Type to find a field...")
        coverage_checkbox = QCheckBox("Show coverage fields (audit / troubleshooting)")
        coverage_checkbox.setChecked(bool(
            getattr(self, "database_view_show_coverage_fields", False)
        ))
        coverage_checkbox.setToolTip(
            "Coverage is the percentage of source mass for which the field "
            "could be derived. It does not change optimisation inputs."
        )
        field_list = QListWidget()
        for header in all_headers:
            item = QListWidgetItem(self.user_facing_field_label(header))
            item.setData(Qt.UserRole, header)
            item.setFlags(
                item.flags() | Qt.ItemIsUserCheckable | Qt.ItemIsEnabled
            )
            item.setCheckState(
                Qt.Checked if header in selected else Qt.Unchecked
            )
            field_list.addItem(item)

        def filter_fields(text):
            needle = str(text or "").strip().lower()
            show_coverage = coverage_checkbox.isChecked()
            for index in range(field_list.count()):
                item = field_list.item(index)
                header = item.data(Qt.UserRole)
                item.setHidden(
                    (not show_coverage and self.database_view_is_coverage_field(header))
                    or bool(needle and needle not in item.text().lower())
                )

        def set_checked(headers_to_check):
            headers_to_check = set(headers_to_check)
            for index in range(field_list.count()):
                item = field_list.item(index)
                item.setCheckState(
                    Qt.Checked if item.data(Qt.UserRole) in headers_to_check else Qt.Unchecked
                )

        search.textChanged.connect(filter_fields)
        layout.addWidget(search)
        layout.addWidget(coverage_checkbox)
        layout.addWidget(field_list, stretch=1)
        coverage_checkbox.toggled.connect(
            lambda _checked: filter_fields(search.text())
        )
        filter_fields(search.text())
        actions = QHBoxLayout()
        defaults_button = QPushButton("Defaults")
        defaults_button.clicked.connect(
            lambda: set_checked(self.default_database_view_columns(all_headers))
        )
        all_button = QPushButton("Select All")
        all_button.clicked.connect(lambda: set_checked([
            header for header in all_headers
            if coverage_checkbox.isChecked()
            or not self.database_view_is_coverage_field(header)
        ]))
        apply_button = QPushButton("Apply")
        cancel_button = QPushButton("Cancel")
        apply_button.clicked.connect(dialog.accept)
        cancel_button.clicked.connect(dialog.reject)
        actions.addWidget(defaults_button)
        actions.addWidget(all_button)
        actions.addStretch()
        actions.addWidget(apply_button)
        actions.addWidget(cancel_button)
        layout.addLayout(actions)
        if dialog.exec_() != QDialog.Accepted:
            return
        chosen = [
            field_list.item(index).data(Qt.UserRole)
            for index in range(field_list.count())
            if field_list.item(index).checkState() == Qt.Checked
        ]
        self.database_view_selected_columns = (
            chosen or self.default_database_view_columns(all_headers)
        )
        self.database_view_show_coverage_fields = coverage_checkbox.isChecked()
        self.database_view_known_columns = list(all_headers)
        self.populate_database_view_table()
        self.save_active_scenario_state()

    @staticmethod
    def database_view_source_base_key(record):
        """Return the stable identity portion of a Database View source."""
        record = record or {}
        return json.dumps(
            [
                str(record.get("source_type") or ""),
                str(record.get("source_id") or ""),
                str(record.get("parent_stockpile") or ""),
            ],
            ensure_ascii=True,
            separators=(",", ":"),
        )

    def database_view_source_descriptors(self):
        """Describe each source column with a stable key and unique caption."""
        base_keys = []
        base_labels = []
        for index, record in enumerate(self.database_view_rows):
            base_keys.append(self.database_view_source_base_key(record))
            base_labels.append(
                str(
                    record.get("source_id")
                    or record.get("build_or_chunk")
                    or record.get("parent_stockpile")
                    or f"Source {index + 1}"
                )
            )

        label_counts = {}
        for label in base_labels:
            label_counts[label] = label_counts.get(label, 0) + 1
        key_occurrences = {}
        caption_occurrences = {}
        descriptors = []
        for index, record in enumerate(self.database_view_rows):
            base_key = base_keys[index]
            key_occurrences[base_key] = key_occurrences.get(base_key, 0) + 1
            key = f"{base_key}#{key_occurrences[base_key]}"

            base_label = base_labels[index]
            caption = base_label
            if label_counts.get(base_label, 0) > 1:
                context = str(record.get("source_type") or "Source")
                parent = str(record.get("parent_stockpile") or "").strip()
                if parent and parent != base_label:
                    context = f"{context} | {parent}"
                caption = f"{base_label} [{context}]"
            caption_occurrences[caption] = (
                caption_occurrences.get(caption, 0) + 1
            )
            if caption_occurrences[caption] > 1:
                caption = f"{caption} #{caption_occurrences[caption]}"

            search_text = " ".join(
                str(value)
                for value in record.values()
                if value is not None
            ).lower()
            descriptors.append({
                "key": key,
                "label": caption,
                "record_index": index,
                "record": record,
                "source_type": str(record.get("source_type") or ""),
                "search_text": search_text,
            })
        return descriptors

    def database_view_selected_source_descriptors(self):
        """Resolve saved source choices and auto-select newly appearing sources."""
        descriptors = self.database_view_source_descriptors()
        current_keys = [descriptor["key"] for descriptor in descriptors]
        selected = getattr(self, "database_view_selected_sources", None)
        known_values = list(
            getattr(self, "database_view_known_sources", None) or []
        )
        known = set(known_values)
        if selected is None:
            selected = list(current_keys)
        else:
            selected = list(selected)
            selected.extend(
                key for key in current_keys
                if key not in known and key not in selected
            )
        self.database_view_selected_sources = list(dict.fromkeys(selected))
        self.database_view_known_sources = list(
            dict.fromkeys([*known_values, *current_keys])
        )
        selected_set = set(self.database_view_selected_sources)
        return [
            descriptor for descriptor in descriptors
            if descriptor["key"] in selected_set
        ]

    def update_database_view_source_button(self):
        if not hasattr(self, "database_view_source_button"):
            return
        descriptors = self.database_view_source_descriptors()
        selected = set(
            getattr(self, "database_view_selected_sources", []) or []
        )
        selected_count = sum(
            descriptor["key"] in selected for descriptor in descriptors
        )
        self.database_view_source_button.setText(
            f"Choose Sources... ({selected_count}/{len(descriptors)})"
        )

    def choose_database_view_sources(self):
        descriptors = self.database_view_source_descriptors()
        if not descriptors:
            return
        # Resolve defaults and newly appearing sources before building the list.
        self.database_view_selected_source_descriptors()
        selected = set(self.database_view_selected_sources or [])
        dialog = QDialog(self)
        dialog.setWindowTitle("Database View Sources")
        dialog.resize(620, 650)
        layout = QVBoxLayout(dialog)
        search = QLineEdit()
        search.setPlaceholderText("Type to find a source, stockpile or type...")
        source_list = QListWidget()
        for descriptor in descriptors:
            item = QListWidgetItem(descriptor["label"])
            item.setData(Qt.UserRole, descriptor["key"])
            item.setToolTip(
                " | ".join(
                    value for value in (
                        descriptor["source_type"],
                        str(descriptor["record"].get("parent_stockpile") or ""),
                        str(descriptor["record"].get("build_or_chunk") or ""),
                    ) if value
                )
            )
            item.setFlags(
                item.flags() | Qt.ItemIsUserCheckable | Qt.ItemIsEnabled
            )
            item.setCheckState(
                Qt.Checked
                if descriptor["key"] in selected
                else Qt.Unchecked
            )
            source_list.addItem(item)

        def filter_sources(text):
            needle = str(text or "").strip().lower()
            for index, descriptor in enumerate(descriptors):
                item = source_list.item(index)
                item.setHidden(
                    bool(
                        needle
                        and needle not in descriptor["label"].lower()
                        and needle not in descriptor["search_text"]
                    )
                )

        def set_checked(check):
            state = Qt.Checked if check else Qt.Unchecked
            for index in range(source_list.count()):
                source_list.item(index).setCheckState(state)

        search.textChanged.connect(filter_sources)
        layout.addWidget(search)
        layout.addWidget(source_list, stretch=1)
        actions = QHBoxLayout()
        all_button = QPushButton("Select All")
        all_button.clicked.connect(lambda: set_checked(True))
        none_button = QPushButton("Clear")
        none_button.clicked.connect(lambda: set_checked(False))
        apply_button = QPushButton("Apply")
        cancel_button = QPushButton("Cancel")
        apply_button.clicked.connect(dialog.accept)
        cancel_button.clicked.connect(dialog.reject)
        actions.addWidget(all_button)
        actions.addWidget(none_button)
        actions.addStretch()
        actions.addWidget(apply_button)
        actions.addWidget(cancel_button)
        layout.addLayout(actions)
        if dialog.exec_() != QDialog.Accepted:
            return
        self.database_view_selected_sources = [
            source_list.item(index).data(Qt.UserRole)
            for index in range(source_list.count())
            if source_list.item(index).checkState() == Qt.Checked
        ]
        self.database_view_known_sources = list(
            dict.fromkeys([
                *(self.database_view_known_sources or []),
                *(descriptor["key"] for descriptor in descriptors),
            ])
        )
        self.populate_database_view_table()
        self.save_active_scenario_state()

    def populate_database_view_table(self):
        table = self.database_view_table
        fields = self.database_view_headers()
        sources = self.database_view_selected_source_descriptors()
        table.setSortingEnabled(False)
        table.clearContents()
        table.setRowCount(len(fields))
        table.setColumnCount(len(sources) + 1)
        field_header = QTableWidgetItem("Field")
        field_header.setToolTip("Database field or calculated property")
        table.setHorizontalHeaderItem(0, field_header)
        for column_index, descriptor in enumerate(sources, start=1):
            source_header = QTableWidgetItem(descriptor["label"])
            source_header.setData(Qt.UserRole, descriptor["key"])
            source_header.setToolTip(
                " | ".join(
                    value for value in (
                        descriptor["source_type"],
                        str(descriptor["record"].get("parent_stockpile") or ""),
                        str(descriptor["record"].get("build_or_chunk") or ""),
                    ) if value
                )
            )
            table.setHorizontalHeaderItem(column_index, source_header)

        for row_index, field in enumerate(fields):
            # Database View is the canonical BlendMaster schema, not a second
            # raw-source catalogue. Show Define Fields names verbatim.
            field_item = QTableWidgetItem(str(field))
            field_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            field_item.setData(Qt.UserRole, field)
            field_item.setToolTip(str(field))
            field_item.setBackground(QColor("#f1f5f9"))
            table.setItem(row_index, 0, field_item)
            for column_index, descriptor in enumerate(sources, start=1):
                value = descriptor["record"].get(field, "")
                display = self.database_view_display_value(
                    field,
                    value,
                    vars(self).get("field_definitions"),
                )
                item = QTableWidgetItem(display)
                item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                item.setToolTip(display)
                item.setData(Qt.UserRole, descriptor["key"])
                if field.startswith("fallback_") and display:
                    item.setBackground(QColor("#fff3cd"))
                elif (
                    (
                        field.startswith("grade_")
                        or (
                            field.startswith("selected_")
                            and field != "selected_stream"
                        )
                    )
                    and not display
                ):
                    item.setBackground(QColor("#fee2e2"))
                table.setItem(row_index, column_index, item)
        table.horizontalHeader().setSectionResizeMode(QHeaderView.Interactive)
        table.resizeColumnToContents(0)
        table.setColumnWidth(
            0, min(max(table.columnWidth(0), 180), 360)
        )
        for column_index in range(1, table.columnCount()):
            table.resizeColumnToContents(column_index)
            table.setColumnWidth(
                column_index,
                min(max(table.columnWidth(column_index), 100), 260),
            )
        self.update_database_view_column_button()
        self.update_database_view_source_button()
        self.apply_database_view_filters()

    @staticmethod
    def database_view_display_value(header, value, field_definitions=None):
        """Format audit quantities as sums and weighted values as averages."""
        if value is None or (isinstance(value, float) and math.isnan(value)):
            return ""
        number = numeric(value)
        declared_kinds = {
            row["name"]: row["kind"]
            for row in normalize_field_definitions(field_definitions)
        }
        sum_property = (
            source_property_kind(header, declared_kinds) == "additive"
            or
            header == "tonnes"
            or header.endswith("_wmt")
            or header.endswith("_dmt")
            or header.endswith("_tonnes")
            or header.endswith("_volume")
            or header.endswith("_count")
            or header == "balancedmt"
        )
        weighted_average_property = (
            source_property_kind(header, declared_kinds) in {"intensive", "unknown"}
            or
            header.startswith("grade_")
            or (
                header.startswith("selected_")
                and header != "selected_stream"
            )
            or header.startswith("modelled_")
            or header.endswith("_coverage_pct")
            or (
                header in INVENTORY_ADDITIONAL_FIELDS
                and header not in INVENTORY_TEXT_FIELDS
                and header not in INVENTORY_INTEGER_FIELDS
            )
        )
        if number is not None and sum_property:
            return f"{number:,.0f}"
        if number is not None and weighted_average_property:
            return f"{number:,.2f}"
        return str(value)

    def apply_database_view_filters(self, *_args):
        if not hasattr(self, "database_view_table"):
            return
        source_type = str(
            self.database_view_source_filter.currentData() or ""
        )
        search = self.database_view_search.text().strip().lower()
        descriptors = {
            descriptor["key"]: descriptor
            for descriptor in self.database_view_source_descriptors()
        }
        self.database_view_table.setColumnHidden(0, False)
        for column_index in range(1, self.database_view_table.columnCount()):
            header_item = self.database_view_table.horizontalHeaderItem(
                column_index
            )
            source_key = (
                header_item.data(Qt.UserRole)
                if header_item is not None else None
            )
            descriptor = descriptors.get(source_key, {})
            type_matches = (
                not source_type
                or descriptor.get("source_type", "") == source_type
            )
            search_matches = (
                not search
                or search in descriptor.get("label", "").lower()
                or search in descriptor.get("search_text", "")
            )
            self.database_view_table.setColumnHidden(
                column_index, not (type_matches and search_matches)
            )

    def continue_from_database_view(self):
        if getattr(self, "database_view_refresh_in_progress", False):
            return
        if (
            getattr(self, "database_view_snapshot_signature", None)
            != self.database_view_input_signature()
        ):
            self.refresh_database_view()
            return
        self.activate_manual_setup_tab()
        self.navigate_to_solver_configuration()

    def setup_define_fields(self):
        """Create the canonical field contract shared by every source type."""
        self.define_fields_tab = QWidget()
        self.define_fields_tab_index = self.register_page(
            "define_fields",
            self.setup_tabs,
            self.define_fields_tab,
            "Define Fields",
            position=3,
        )
        self.set_page_enabled(self.define_fields_tab_index, False)
        layout = QVBoxLayout(self.define_fields_tab)
        layout.setContentsMargins(14, 12, 14, 12)
        title = QLabel("Define Fields")
        title.setStyleSheet("font-size: 22px; font-weight: 700; color: #1f2933;")
        help_text = QLabel(
            "Define the stable BlendMaster fields that every source will expose. "
            "Weighted-average fields must use an additive weight field defined in "
            "a higher row. Fields selected for optimisation are available to custom "
            "constraints and written to solver reports; their additive weight fields "
            "are selected automatically. The optimiser's selected grade vector and "
            "configured crusher, reclaimer and product-build quantity fields always "
            "flow because they are compulsory runtime inputs, regardless of a grade "
            "row's checkbox."
        )
        help_text.setWordWrap(True)
        help_text.setStyleSheet("color: #607080;")
        layout.addWidget(title)
        layout.addWidget(help_text)

        self.define_fields_table = CustomTableWidget()
        self.define_fields_table.setColumnCount(5)
        self.define_fields_table.setHorizontalHeaderLabels([
            "Field Name", "Type", "Weight Field", "Use in Optimisation", "Required"
        ])
        self.define_fields_table.verticalHeader().setVisible(False)
        self.define_fields_table.horizontalHeader().setSectionResizeMode(
            0, QHeaderView.Stretch
        )
        for column in range(1, 5):
            self.define_fields_table.horizontalHeader().setSectionResizeMode(
                column, QHeaderView.ResizeToContents
            )
        self.define_fields_table.cellChanged.connect(
            self.handle_define_fields_table_changed
        )
        layout.addWidget(self.define_fields_table, stretch=1)

        buttons = QHBoxLayout()
        add_button = QPushButton("Add Field")
        delete_button = QPushButton("Delete Selected")
        up_button = QPushButton("Move Up")
        down_button = QPushButton("Move Down")
        import_button = QPushButton("Import Fields...")
        export_button = QPushButton("Export Fields...")
        submit_button = QPushButton("Submit")
        add_button.clicked.connect(self.add_defined_field)
        delete_button.clicked.connect(self.delete_defined_field)
        up_button.clicked.connect(lambda: self.move_defined_field(-1))
        down_button.clicked.connect(lambda: self.move_defined_field(1))
        import_button.clicked.connect(self.import_field_definitions)
        export_button.clicked.connect(self.export_field_definitions)
        submit_button.clicked.connect(self.handle_define_fields_submit)
        for button in (add_button, delete_button, up_button, down_button):
            buttons.addWidget(button)
        buttons.addStretch()
        buttons.addWidget(import_button)
        buttons.addWidget(export_button)
        buttons.addWidget(submit_button)
        layout.addLayout(buttons)
        self.populate_define_fields_table()

    @staticmethod
    def field_definition_exchange_payload(values):
        """Return the portable JSON contract for Define Fields."""
        return {
            "format": "blendmaster_field_definitions",
            "version": 1,
            "field_definitions": validate_field_definitions(values),
        }

    @staticmethod
    def field_definitions_from_exchange_payload(payload):
        """Validate a list or a versioned Define Fields JSON payload."""
        if isinstance(payload, dict):
            format_name = str(payload.get("format") or "").strip()
            if format_name and format_name != "blendmaster_field_definitions":
                raise ValueError(
                    "This JSON file is not a BlendMaster field-definitions export."
                )
            values = payload.get("field_definitions")
        else:
            values = payload
        if not isinstance(values, list):
            raise ValueError(
                "The import must contain a 'field_definitions' list."
            )
        return validate_field_definitions(values)

    def export_field_definitions(self):
        try:
            definitions = self.capture_define_fields_table()
            payload = self.field_definition_exchange_payload(definitions)
        except ValueError as exc:
            QMessageBox.warning(self, "Export Fields", str(exc))
            return
        file_path, _ = QFileDialog.getSaveFileName(
            self,
            "Export BlendMaster Fields",
            "blendmaster_fields.json",
            "JSON Files (*.json)",
        )
        if not file_path:
            return
        if not file_path.lower().endswith(".json"):
            file_path += ".json"
        try:
            with open(file_path, "w", encoding="utf-8") as output_file:
                json.dump(payload, output_file, indent=2, ensure_ascii=False)
        except OSError as exc:
            QMessageBox.warning(
                self, "Export Fields", f"Unable to export fields: {exc}"
            )
            return
        QMessageBox.information(
            self,
            "Export Fields",
            f"Exported {len(definitions)} field definitions to:\n{file_path}",
        )

    def import_field_definitions(self):
        file_path, _ = QFileDialog.getOpenFileName(
            self,
            "Import BlendMaster Fields",
            "",
            "JSON Files (*.json)",
        )
        if not file_path:
            return
        try:
            with open(file_path, "r", encoding="utf-8") as input_file:
                payload = json.load(input_file)
            definitions = self.field_definitions_from_exchange_payload(payload)
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            QMessageBox.warning(
                self, "Import Fields", f"Unable to import fields: {exc}"
            )
            return

        self.field_definitions = definitions
        targets = {row["name"] for row in definitions}
        self.field_mappings = [
            mapping
            for mapping in normalize_field_mappings(self.field_mappings)
            if mapping["target_field"] in targets
        ]
        self.populate_define_fields_table()
        self.populate_map_fields_table()
        self.refresh_map_available_fields()
        self.save_active_scenario_state()
        QMessageBox.information(
            self,
            "Import Fields",
            f"Imported {len(definitions)} field definitions. Review them, then Submit.",
        )

    def field_definition_row(self, row):
        name_item = self.define_fields_table.item(row, 0)
        kind_combo = self.define_fields_table.cellWidget(row, 1)
        weight_combo = self.define_fields_table.cellWidget(row, 2)
        optimisation_widget = self.define_fields_table.cellWidget(row, 3)
        required_item = self.define_fields_table.item(row, 4)
        optimisation_checkbox = (
            optimisation_widget.layout().itemAt(0).widget()
            if optimisation_widget is not None else None
        )
        return {
            "name": name_item.text().strip() if name_item else "",
            "kind": kind_combo.currentData() if isinstance(kind_combo, QComboBox) else "",
            "weight_field": (
                weight_combo.currentData()
                if isinstance(weight_combo, QComboBox) else ""
            ),
            "use_in_optimisation": bool(
                optimisation_checkbox and optimisation_checkbox.isChecked()
            ),
            "required": bool(
                required_item and required_item.data(Qt.UserRole)
            ),
        }

    def capture_define_fields_table(self):
        rows = [
            self.field_definition_row(row)
            for row in range(self.define_fields_table.rowCount())
        ]
        self.field_definitions = validate_field_definitions(rows)
        return self.field_definitions

    def populate_define_fields_table(self):
        if not hasattr(self, "define_fields_table"):
            return
        rows = normalize_field_definitions(
            getattr(self, "field_definitions", None)
        )
        self.field_definitions = copy.deepcopy(rows)
        table = self.define_fields_table
        table.blockSignals(True)
        table.setRowCount(len(rows))
        earlier_additives = []
        for row_index, definition in enumerate(rows):
            required = bool(definition.get("required"))
            name_item = QTableWidgetItem(definition["name"])
            name_flags = Qt.ItemIsEnabled | Qt.ItemIsSelectable
            if not required:
                name_flags |= Qt.ItemIsEditable
            name_item.setFlags(name_flags)
            name_item.setToolTip(definition.get("description", ""))
            table.setItem(row_index, 0, name_item)

            kind_combo = QComboBox()
            for kind in FIELD_KINDS:
                kind_combo.addItem(kind.replace("_", " ").title(), kind)
            kind_combo.setCurrentIndex(max(kind_combo.findData(definition["kind"]), 0))
            kind_combo.setEnabled(not required)
            kind_combo.currentIndexChanged.connect(
                self.handle_define_fields_table_changed
            )
            table.setCellWidget(row_index, 1, kind_combo)

            weight_combo = QComboBox()
            weight_combo.addItem("", "")
            for additive in earlier_additives:
                weight_combo.addItem(additive, additive)
            weight = definition.get("weight_field", "")
            if weight and weight_combo.findData(weight) < 0:
                weight_combo.addItem(weight, weight)
            weight_combo.setCurrentIndex(max(weight_combo.findData(weight), 0))
            weight_combo.setEnabled(definition["kind"] == "weighted_average")
            table.setCellWidget(row_index, 2, weight_combo)

            optimisation_checkbox = QCheckBox()
            optimisation_checkbox.setChecked(bool(
                definition.get("use_in_optimisation")
            ))
            optimisation_container = QWidget()
            checkbox_layout = QHBoxLayout(optimisation_container)
            checkbox_layout.setContentsMargins(0, 0, 0, 0)
            checkbox_layout.setAlignment(Qt.AlignCenter)
            checkbox_layout.addWidget(optimisation_checkbox)
            table.setCellWidget(row_index, 3, optimisation_container)

            required_item = QTableWidgetItem("Yes" if required else "No")
            required_item.setData(Qt.UserRole, required)
            required_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            required_item.setTextAlignment(Qt.AlignCenter)
            table.setItem(row_index, 4, required_item)
            if definition["kind"] == "additive":
                earlier_additives.append(definition["name"])
        table.blockSignals(False)

    def handle_define_fields_table_changed(self, *_args):
        """Refresh dependent weight choices while preserving current edits."""
        if not hasattr(self, "define_fields_table"):
            return
        table = self.define_fields_table
        earlier_additives = []
        for row in range(table.rowCount()):
            name_item = table.item(row, 0)
            name = canonical_property_key(name_item.text() if name_item else "")
            kind_combo = table.cellWidget(row, 1)
            weight_combo = table.cellWidget(row, 2)
            kind = kind_combo.currentData() if isinstance(kind_combo, QComboBox) else ""
            if isinstance(weight_combo, QComboBox):
                current = weight_combo.currentData() or ""
                weight_combo.blockSignals(True)
                weight_combo.clear()
                weight_combo.addItem("", "")
                for additive in earlier_additives:
                    weight_combo.addItem(additive, additive)
                if current and weight_combo.findData(current) >= 0:
                    weight_combo.setCurrentIndex(weight_combo.findData(current))
                weight_combo.setEnabled(kind == "weighted_average")
                weight_combo.blockSignals(False)
            if kind == "additive" and name:
                earlier_additives.append(name)

    def add_defined_field(self):
        try:
            rows = [
                self.field_definition_row(row)
                for row in range(self.define_fields_table.rowCount())
            ]
        except Exception:
            rows = copy.deepcopy(self.field_definitions)
        existing = {canonical_property_key(row.get("name")) for row in rows}
        number = 1
        name = f"new_field_{number}"
        while name in existing:
            number += 1
            name = f"new_field_{number}"
        rows.append({
            "name": name,
            "kind": "additive",
            "weight_field": "",
            "required": False,
            "use_in_optimisation": False,
        })
        self.field_definitions = rows
        self.populate_define_fields_table()
        self.define_fields_table.setCurrentCell(len(rows) - 1, 0)
        self.define_fields_table.editItem(
            self.define_fields_table.item(len(rows) - 1, 0)
        )

    def delete_defined_field(self):
        row = self.define_fields_table.currentRow()
        if row < 0:
            return
        definition = self.field_definition_row(row)
        if definition.get("required"):
            QMessageBox.information(
                self, "Define Fields", "Required fields cannot be deleted."
            )
            return
        self.define_fields_table.removeRow(row)
        self.handle_define_fields_table_changed()

    def move_defined_field(self, offset):
        row = self.define_fields_table.currentRow()
        target = row + int(offset)
        if row < 0 or target < 0 or target >= self.define_fields_table.rowCount():
            return
        rows = [
            self.field_definition_row(index)
            for index in range(self.define_fields_table.rowCount())
        ]
        rows[row], rows[target] = rows[target], rows[row]
        self.field_definitions = rows
        self.populate_define_fields_table()
        self.define_fields_table.setCurrentCell(target, 0)

    def handle_define_fields_submit(self):
        try:
            self.capture_define_fields_table()
        except ValueError as exc:
            QMessageBox.warning(self, "Define Fields", str(exc))
            return
        # Make automatically-required additive weights visible if the user
        # returns to this step.
        self.populate_define_fields_table()
        targets = {row["name"] for row in self.field_definitions}
        self.field_mappings = [
            mapping for mapping in normalize_field_mappings(self.field_mappings)
            if mapping["target_field"] in targets
        ]
        self.populate_map_fields_table()
        self.refresh_map_available_fields()
        self.set_page_enabled(self.map_fields_tab_index, True)
        self.save_active_scenario_state()
        self.show_page(self.map_fields_tab_index, force=True)

