    def current_24hr_aps_path(self):
        for widget_name in (
            "map_fields_file_path_24hr",
            "data_streams_file_path_24hr",
            "file_path_24hr",
        ):
            widget = vars(self).get(widget_name)
            if widget is not None:
                widget_path = widget.text().strip()
                if widget_path:
                    return widget_path
        return str(getattr(self, "file_path_24hr_choice", "") or "").strip()

    def set_24hr_mining_path(
        self,
        file_path,
        reset_agents=False,
        show_mapping_errors=False,
    ):
        """Keep the Data Streams and Guidance 24HR selectors in sync."""
        normalized_path = str(file_path or "").strip()
        previous_path = str(
            getattr(self, "file_path_24hr_choice", "") or ""
        ).strip()
        self.file_path_24hr_choice = normalized_path

        for widget_name in (
            "map_fields_file_path_24hr",
            "data_streams_file_path_24hr",
            "file_path_24hr",
        ):
            widget = vars(self).get(widget_name)
            if widget is not None and widget.text() != normalized_path:
                widget.setText(normalized_path)

        if reset_agents and normalized_path != previous_path:
            if hasattr(self, "expit_agent_input"):
                self.set_24hr_expit_agent_items([], [])
            self.available_24hr_expit_agents = []
            self.selected_24hr_expit_agents = []

        self.refresh_aps_grade_field_headers(
            show_errors=show_mapping_errors
        )
        if vars(self).get("map_fields_available_list") is not None:
            self.refresh_map_available_fields()

    @staticmethod
    def distinct_aps_csv_headers(path):
        with open(
            path,
            "r",
            encoding="utf-8-sig",
            errors="replace",
            newline="",
        ) as csv_file:
            raw_headers = next(csv.reader(csv_file), [])
        return list(dict.fromkeys(
            str(header).strip()
            for header in raw_headers
            if str(header).strip()
        ))

    def refresh_aps_grade_field_headers(self, show_errors=False):
        """Load distinct CSV header values without reading the schedule body."""
        header_list = getattr(self, "aps_header_list", None)
        status_label = getattr(self, "aps_header_status_label", None)
        if header_list is None or status_label is None:
            return []

        path = self.current_24hr_aps_path()
        header_list.clear()
        if not path:
            status_label.setText("No 24HR APS file selected.")
            return []
        if not os.path.isfile(path):
            status_label.setText(f"24HR APS file not found: {path}")
            return []

        try:
            headers = self.distinct_aps_csv_headers(path)
        except (OSError, csv.Error) as exc:
            status_label.setText(f"Unable to read 24HR APS fields: {exc}")
            if show_errors:
                QMessageBox.warning(
                    self,
                    "24HR APS Fields",
                    f"Unable to read the selected 24HR APS file:\n{exc}",
                )
            return []

        header_list.addItems(headers)
        status_label.setText(
            f"{len(headers)} distinct fields from {os.path.basename(path)}"
        )
        filter_text = (
            self.aps_header_filter.text()
            if hasattr(self, "aps_header_filter")
            else ""
        )
        self.filter_aps_grade_field_headers(filter_text)
        return headers

    def filter_aps_grade_field_headers(self, text):
        header_list = getattr(self, "aps_header_list", None)
        if header_list is None:
            return
        search = str(text or "").strip().lower()
        for row in range(header_list.count()):
            item = header_list.item(row)
            item.setHidden(bool(search and search not in item.text().lower()))

    def set_aps_mapping_target(self, mapping_type, row, column):
        if mapping_type == "grade" and column >= 2:
            self.aps_mapping_target = (mapping_type, row, column)
        elif mapping_type == "property" and column == 2:
            self.aps_mapping_target = (mapping_type, row, column)

    def apply_aps_header_to_mapping_cell(self, header_item):
        mapping_type, row, column = getattr(
            self, "aps_mapping_target", ("grade", -1, -1)
        )
        table = (
            getattr(self, "aps_source_property_mapping_table", None)
            if mapping_type == "property"
            else getattr(self, "aps_grade_mapping_table", None)
        )
        if table is None or header_item is None:
            return
        valid_column = (
            column == 2 if mapping_type == "property" else column >= 2
        )
        if row < 0 or not valid_column or row >= table.rowCount():
            QMessageBox.information(
                self,
                "APS Field Mapping",
                "Select a grade or source-property 24HR APS mapping cell first.",
            )
            return
        table.setItem(row, column, QTableWidgetItem(header_item.text()))
        table.setCurrentCell(row, column)

    def populate_aps_grade_mapping_table(self):
        table = getattr(self, "aps_grade_mapping_table", None)
        if table is None:
            return
        brands = configured_brands(self.product_brand_labels_choice)
        mappings = normalise_aps_grade_field_mappings(
            self.aps_grade_field_mappings, brands
        )
        self.aps_grade_field_mappings = copy.deepcopy(mappings)
        rows = [
            ("ROM", brand, (mappings.get("rom", {}) or {}).get(brand, {}))
            for brand in brands
        ]
        rows.extend(
            ("Product", brand, (mappings.get("product", {}) or {}).get(brand, {}))
            for brand in brands
        )
        table.setRowCount(len(rows))
        for row_index, (stream_label, brand, fields) in enumerate(rows):
            for column, value in enumerate((stream_label, brand)):
                item = QTableWidgetItem(value)
                item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                table.setItem(row_index, column, item)
            for offset, analyte in enumerate(ANALYTES, start=2):
                table.setItem(row_index, offset, QTableWidgetItem(str((fields or {}).get(analyte, "") or "")))

    def capture_aps_grade_mapping_table(self):
        mappings = {"rom": {}, "product": {}}
        table = self.aps_grade_mapping_table
        for row in range(table.rowCount()):
            stream = str(table.item(row, 0).text() if table.item(row, 0) else "").lower()
            brand = str(table.item(row, 1).text() if table.item(row, 1) else "").strip().upper()
            fields = {
                analyte: str(table.item(row, column).text() if table.item(row, column) else "").strip()
                for column, analyte in enumerate(ANALYTES, start=2)
            }
            if stream == "rom" and brand:
                mappings["rom"][brand] = fields
            elif stream == "product" and brand:
                mappings["product"][brand] = fields
        self.aps_grade_field_mappings = normalise_aps_grade_field_mappings(
            mappings, self.product_brand_labels_choice
        )

    def populate_aps_source_property_mapping_table(self):
        table = getattr(self, "aps_source_property_mapping_table", None)
        if table is None:
            return
        mappings = normalise_aps_source_property_mappings(
            getattr(self, "aps_source_property_field_mappings", None)
        )
        self.aps_source_property_field_mappings = copy.deepcopy(mappings)
        catalogue = list(APS_SOURCE_PROPERTY_CATALOGUE)
        known = {field for _group, field, _label in catalogue}
        catalogue.extend(
            ("Saved / Custom", field, field)
            for field in mappings
            if field not in known
        )
        table.setRowCount(len(catalogue))
        for row, (group, field, description) in enumerate(catalogue):
            group_item = QTableWidgetItem(group)
            group_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            table.setItem(row, 0, group_item)
            field_item = QTableWidgetItem(field)
            field_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            field_item.setToolTip(description)
            table.setItem(row, 1, field_item)
            header_item = QTableWidgetItem(str(mappings.get(field) or ""))
            header_item.setToolTip(
                f"{description}. Drag or double-click a 24HR APS field to map it."
            )
            table.setItem(row, 2, header_item)

    def capture_aps_source_property_mapping_table(self):
        table = getattr(self, "aps_source_property_mapping_table", None)
        if table is None:
            return
        mappings = {}
        for row in range(table.rowCount()):
            field_item = table.item(row, 1)
            header_item = table.item(row, 2)
            field = str(field_item.text() if field_item else "").strip()
            header = str(header_item.text() if header_item else "").strip()
            if field:
                mappings[field] = header
        self.aps_source_property_field_mappings = (
            normalise_aps_source_property_mappings(mappings)
        )

    def load_cb_lump_fines_settings(self):
        combo = getattr(self, "cb_lump_fines_mode_input", None)
        percentage = getattr(self, "cb_lump_percentage_input", None)
        if combo is None or percentage is None:
            return
        mode = str(getattr(self, "cb_lump_fines_mode", "derived") or "derived")
        index = combo.findData(mode)
        combo.setCurrentIndex(index if index >= 0 else 0)
        percentage.setText(f"{float(getattr(self, 'cb_lump_percentage', 50.0)):g}")
        self.update_cb_lump_fines_controls()

    def load_byproduct_build_settings(self):
        checkbox = getattr(self, "byproducts_enabled_checkbox", None)
        if checkbox is None:
            return
        checkbox.setChecked(bool(getattr(self, "byproducts_enabled", False)))
        quantities = normalize_byproduct_quantity_fields(
            getattr(self, "byproduct_quantity_fields", None)
        )
        grades = normalize_byproduct_grade_fields(
            getattr(self, "byproduct_grade_fields", None)
        )
        def restore_selector(selector, value):
            value = str(value or "").strip()
            if not value:
                selector.setCurrentText("")
                return
            if selector.findText(value, Qt.MatchFixedString) < 0:
                # A loaded project can reference a user-defined field that was
                # not present when the Data Streams page was first constructed.
                selector.addItem(value)
            selector.setCurrentText(value)

        for lane, selector in getattr(
            self, "byproduct_quantity_selectors", {}
        ).items():
            restore_selector(selector, quantities[lane])
        for lane, selectors in getattr(
            self, "byproduct_grade_selectors", {}
        ).items():
            for analyte, selector in selectors.items():
                restore_selector(selector, grades[lane][analyte])
        self.update_byproduct_build_controls()

    def update_byproduct_build_controls(self, *_args):
        is_cb = self.is_cloudbreak_site()
        label = vars(self).get("byproducts_enabled_label")
        checkbox = vars(self).get("byproducts_enabled_checkbox")
        enabled = bool(checkbox and checkbox.isChecked() and is_cb)
        if label is not None:
            label.setVisible(is_cb)
        if checkbox is not None:
            checkbox.setVisible(is_cb)
            checkbox.setEnabled(is_cb)
        for widget in vars(self).get("byproduct_build_rows", []):
            widget.setVisible(is_cb)
            widget.setEnabled(enabled)
        product_selector = vars(self).get("product_build_tonnes_selector")
        if product_selector is not None:
            product_selector.setEnabled(not enabled)
        table = vars(self).get("product_build_table")
        if table is not None:
            self.byproducts_enabled = enabled
            table.setColumnHidden(
                self.product_build_headers.index("By-product"), not enabled
            )
            self.renumber_product_build_rows()

    def capture_byproduct_build_settings(self, *, validate=True):
        checkbox = getattr(self, "byproducts_enabled_checkbox", None)
        is_cb = self.is_cloudbreak_site()
        self.byproducts_enabled = bool(
            checkbox and checkbox.isChecked() and is_cb
        )
        quantities = {}
        grades = {}
        for lane in BYPRODUCT_LANES:
            selector = getattr(self, "byproduct_quantity_selectors", {}).get(lane)
            quantities[lane] = str(
                selector.currentText() if selector is not None else ""
            ).strip().lower()
            grades[lane] = {}
            for analyte in PRODUCT_BUILD_ANALYTES:
                grade_selector = getattr(
                    self, "byproduct_grade_selectors", {}
                ).get(lane, {}).get(analyte)
                grades[lane][analyte] = str(
                    grade_selector.currentText() if grade_selector is not None else ""
                ).strip().lower()

        if self.byproducts_enabled and validate:
            definitions = {
                str(row.get("name") or "").strip().lower(): str(
                    row.get("kind") or ""
                ).strip().lower()
                for row in normalize_field_definitions(
                    getattr(self, "field_definitions", None)
                )
            }
            errors = []
            for lane in BYPRODUCT_LANES:
                quantity = quantities[lane]
                if definitions.get(quantity) != "additive":
                    errors.append(
                        f"{lane.title()} Quantity Field must be a defined additive field."
                    )
                for analyte in PRODUCT_BUILD_ANALYTES:
                    field = grades[lane][analyte]
                    if definitions.get(field) != "weighted_average":
                        errors.append(
                            f"{lane.title()} {analyte.upper()} Grade Field must be a defined weighted-average field."
                        )
            if errors:
                raise ValueError("\n".join(errors))
        self.byproduct_quantity_fields = normalize_byproduct_quantity_fields(
            quantities
        )
        self.byproduct_grade_fields = normalize_byproduct_grade_fields(grades)

    def is_cloudbreak_site(self):
        mine = str(vars(self).get("mine_input_choice", "") or "").strip().upper()
        return mine == "CB" or "CLOUDBREAK" in mine

    def update_cb_lump_fines_controls(self, *_args):
        is_cb = self.is_cloudbreak_site()
        combo = getattr(self, "cb_lump_fines_mode_input", None)
        percentage = getattr(self, "cb_lump_percentage_input", None)
        calculated = bool(
            combo is not None and combo.currentData() == "calculated"
        )
        for widget_name in (
            "cb_lump_fines_mode_label", "cb_lump_fines_mode_input",
            "cb_lump_percentage_label", "cb_lump_percentage_input",
        ):
            widget = getattr(self, widget_name, None)
            if widget is not None:
                widget.setVisible(is_cb)
        if percentage is not None:
            percentage.setEnabled(is_cb and calculated)

    def capture_cb_lump_fines_settings(self):
        combo = getattr(self, "cb_lump_fines_mode_input", None)
        percentage = getattr(self, "cb_lump_percentage_input", None)
        if combo is not None:
            self.cb_lump_fines_mode = str(combo.currentData() or "derived")
        if percentage is not None:
            value = numeric(percentage.text())
            if value is None or not 0 <= value <= 100:
                raise ValueError(
                    "CB Lump Percentage must be between 0 and 100."
                )
            self.cb_lump_percentage = float(value)

    def populate_recon_factor_table(self):
        table = self.recon_factor_table
        table.blockSignals(True)
        factors = self.historical_recon_factors or {}
        factor_rows = []
        for brand in configured_brands(self.product_brand_labels_choice):
            record = factors.get(brand, {}) or {}
            factor_rows.extend([
                (brand, "blend", "Blend"),
                (brand, "regression", "Regression"),
            ])
            special = DataStreamReconciliation.CB_CAMPAIGN_FACTOR
            if record.get(special):
                factor_rows.append((
                    brand,
                    special,
                    "SF - CBFL Campaign Fines",
                ))
        table.setRowCount(len(factor_rows))
        row = 0
        for brand, factor_type, factor_label in factor_rows:
            record = factors.get(brand, {})
            source_by_analyte = record.get("source_brand_by_analyte", {}) or {}
            source_labels = {"fe": "Fe", "si": "SiO₂", "al": "Al₂O₃", "p": "P", "mn": "Mn"}
            source_brand = ", ".join(
                f"{source_labels[analyte]} "
                f"{(source_by_analyte.get(analyte, {}) or {}).get(factor_type, record.get('source_brand', brand))}"
                for analyte in ANALYTES
            )
            windows = record.get("lookback_days", {}) or {}
            window_labels = {"fe": "Fe", "si": "SiO₂", "al": "Al₂O₃", "p": "P", "mn": "Mn"}
            window_text = ", ".join(
                f"{window_labels[analyte]} "
                + (
                    f"{(windows.get(analyte, {}) or {}).get(factor_type)}d"
                    if (windows.get(analyte, {}) or {}).get(factor_type)
                    else "Standard SF fallback"
                    if factor_type == DataStreamReconciliation.CB_CAMPAIGN_FACTOR
                    else "Default"
                )
                for analyte in ANALYTES
            )
            for column, text_value in enumerate(
                (brand, factor_label, source_brand, window_text)
            ):
                item = QTableWidgetItem(str(text_value))
                item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                table.setItem(row, column, item)
            values = record.get(factor_type, {}) or {}
            for analyte_index, analyte in enumerate(ANALYTES):
                value_record = values.get(analyte, {}) or {}
                calculated = float(value_record.get("calculated", 1.0) or 1.0)
                effective = float(value_record.get("effective", calculated) or calculated)
                calc_item = QTableWidgetItem(f"{calculated:.4f}")
                calc_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                table.setItem(row, 4 + analyte_index * 2, calc_item)
                effective_item = QTableWidgetItem(f"{effective:.4f}")
                effective_item.setData(Qt.UserRole, (brand, factor_type, analyte))
                effective_item.setData(Qt.UserRole + 1, effective_item.text())
                effective_item.setData(Qt.UserRole + 2, effective)
                locked = bool(value_record.get("locked", False))
                if locked:
                    effective_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                    effective_item.setToolTip("Dry-plant regression is fixed at 1.0.")
                table.setItem(row, 5 + analyte_index * 2, effective_item)
            row += 1
        table.blockSignals(False)
        review = vars(self).get("reconciliation_review")
        if review is not None:
            review.set_context(vars(self).get("reconciliation_settings"), self.opf_input_choice,
                               configured_brands(self.product_brand_labels_choice))
            self.data_streams_submit_button.setEnabled(False)

    def reconciliation_controls_changed(self, settings):
        self.reconciliation_settings = normalise_reconciliation_settings(settings)
        self._reconciliation_application_cache = None
        self._reconciliation_review_signature = ""
        self._reconciliation_review_generation = vars(self).get("_reconciliation_review_generation", 0) + 1
        self._reconciliation_review_pending = False
        self.data_streams_submit_button.setEnabled(False)
        self.reconciliation_review.set_busy(False)

    def reconciliation_global_factor_changed(self, item):
        if item.data(Qt.UserRole):
            self._reconciliation_review_signature = ""
            self._reconciliation_review_generation = vars(self).get("_reconciliation_review_generation", 0) + 1
            self._reconciliation_review_pending = False
            self.reconciliation_review.set_busy(False)
            self.data_streams_submit_button.setEnabled(False)
            self.reconciliation_review.mark_stale("Global factors edited. Calculate review before submitting.")

    def refresh_reconciliation_history(self, _checked=False):
        self.data_stream_input_cache_signature = ""
        self.data_stream_input_cache_result = {}
        self.prepare_data_streams()

    def reconciliation_review_signature(self):
        state = vars(self)
        return reconciliation_fingerprint({"algorithm_version": RECONCILIATION_ALGORITHM_VERSION, **{name: state.get(name) for name in (
            "reconciliation_settings", "reconciliation_inputs", "historical_recon_factors",
            "opf_input_choice", "product_brand_labels_choice", "start_time_choice",
            "updated_stockpile_data", "AMT_stockpile_data", "hex_sequence_table", "field_mappings", "AMT_footprint_exclusions")}})

    def calculate_reconciliation_review(self):
        """Preview evidence on copies; do not persist grades or alter AMT chunks."""
        application = self.reconciliation_application()
        if application is None:
            return [], {}, []
        state, audits, warnings = vars(self), [], []
        selected = included_footprints(state.get("updated_stockpile_data"), state.get("AMT_footprint_exclusions"))
        zeroed = zeroed_amt_footprints(state.get("AMT_stockpile_data"))
        def resolve(row, name, kind):
            row = copy.deepcopy(row)
            self.apply_source_reconciliation(application, row, row.get("grade_streams") or {}, name, kind)
            return row["reconciliation"]
        for name, row in selected.items():
            if not row.get("amt", row.get("AMT", False)):
                audit = resolve(row, name, "inventory")
                audit["review_label"] = f"Inventory · {name} · {row.get('build', '')}"
                audits.append(audit)
                continue
            if str(name).strip().upper() in zeroed:
                audit = resolve({"FINAL_WMT": 0}, name, "amt")
                audit["review_label"] = f"AMT · {name} · zeroed footprint"
                audit["warnings"].append("Footprint tonnes are zero under the raw AMT / inventory rule; no material is available for chunks.")
                audits.append(audit)
                continue
            hexes = {str(r.get("HEX", r.get("hex", ""))): resolve(r, name, "amt")
                     for r in (state.get("AMT_stockpile_data") or {}).get(name, [])
                     if (numeric(r.get("FINAL_WMT", r.get("balance"))) or 0) > 0}
            chunks = [c for c in state.get("hex_sequence_table", []) or [] if c.get("footprint") == name]
            if not chunks:
                children = list(hexes.values())
                if not children:
                    children = [resolve({"FINAL_WMT": max(numeric(row.get("balance")) or 0, 0)}, name, "amt")]
                    warnings.append(f"{name}: AMT hexes are not loaded; the evidence match score is unscored and global fallback is shown.")
                audit = aggregate_reconciliation([(a, a["source_wmt"]) for a in children], source_id=name, source_kind="amt_footprint_preview")
                audit.update(review_label=f"AMT · {name} · before chunking", review_children=children)
                audits.append(audit)
            for chunk in chunks:
                members = chunk.get("member_hexes") or []
                if isinstance(members, str):
                    members = [v.strip() for v in members.split(",") if v.strip()]
                children = [hexes[str(h)] for h in dict.fromkeys(members) if str(h) in hexes]
                total = max(numeric(chunk.get("balance")) or 0, 0)
                if not math.isclose(sum(a["source_wmt"] for a in children), total, rel_tol=1e-6, abs_tol=.001):
                    children = [resolve({"FINAL_WMT": total}, name, "amt")]
                    warnings.append(f"{name} chunk {chunk.get('sequence')}: current member hexes do not match chunk WMT; global fallback shown. Refresh AMT chunks.")
                audit = aggregate_reconciliation([(a, a["source_wmt"]) for a in children], source_id=name, source_kind="amt_chunk")
                audit.update(review_label=f"AMT chunk · {name} · {chunk.get('sequence', '')}", review_children=children)
                audits.append(audit)
        for audit in audits:
            warnings.extend(audit.get("warnings", []))
        for resolver in application.resolvers.values():
            warnings.extend(resolver.history_warnings)
        overall = aggregate_reconciliation([(a, a.get("source_wmt", 0)) for a in audits], source_kind="overall")
        return audits, overall, list(dict.fromkeys(warnings))

    def update_reconciliation_review(self):
        review = vars(self).get("reconciliation_review")
        if review is None:
            return []
        if normalise_reconciliation_settings(vars(self).get("reconciliation_settings"))["method"] == "auto_max_confidence":
            self.start_confidence_search_review()
            return []
        review.set_busy(False)
        try:
            audits, overall, warnings = self.calculate_reconciliation_review()
        except (ValueError, TypeError) as exc:
            review.mark_stale(f"Review could not be calculated: {exc}")
            self._reconciliation_review_signature = ""
            self.data_streams_submit_button.setEnabled(False)
            return [f"Reconciliation review: {exc}"]
        review.set_review(audits, overall, warnings)
        self._reconciliation_review_signature = self.reconciliation_review_signature()
        self.data_streams_submit_button.setEnabled(True)
        return warnings

    def start_confidence_search_review(self):
        """Compute against an isolated snapshot so the UI remains responsive."""
        names = ("reconciliation_settings", "reconciliation_inputs", "historical_recon_factors",
                 "opf_input_choice", "product_brand_labels_choice", "start_time_choice", "field_mappings",
                 "updated_stockpile_data", "AMT_stockpile_data", "hex_sequence_table", "AMT_footprint_exclusions")
        context = SimpleNamespace(**copy.deepcopy({name: vars(self).get(name) for name in names}))
        context.reconciliation_application = lambda: UserInputs.reconciliation_application(context)
        context.apply_source_reconciliation = lambda *args, **kwargs: UserInputs.apply_source_reconciliation(context, *args, **kwargs)
        signature = self.reconciliation_review_signature()
        generation = vars(self).get("_reconciliation_review_generation", 0) + 1
        self._reconciliation_review_generation = generation
        self._reconciliation_review_pending = True
        self._reconciliation_review_signature = ""
        self.data_streams_submit_button.setEnabled(False)
        self.reconciliation_review.set_busy(True)

        def calculate():
            return UserInputs.calculate_reconciliation_review(context), vars(context).get("_reconciliation_application_cache")

        def finish(result=None, error=None):
            if generation != vars(self).get("_reconciliation_review_generation"):
                return
            self._reconciliation_review_pending = False
            self.reconciliation_review.set_busy(False)
            if signature != self.reconciliation_review_signature():
                self.reconciliation_review.mark_stale("Sources or settings changed. Calculate review again.")
                self.data_streams_submit_button.setEnabled(False)
                return
            if error:
                self.reconciliation_review.mark_stale(f"Evidence match search could not be completed: {error}")
                self.data_streams_submit_button.setEnabled(False)
                return
            (audits, overall, warnings), cache = result
            self._reconciliation_application_cache = cache
            self.reconciliation_review.set_review(audits, overall, warnings)
            self._reconciliation_review_signature = signature
            self.data_streams_submit_button.setEnabled(True)
            label = vars(self).get("data_stream_warning_label")
            if label is not None:
                text = "\n".join(dict.fromkeys([*label.text().splitlines(), *warnings]))
                label.setText(text)
                label.setVisible(bool(text))
            self.advance_agent_after_reconciliation()

        self.run_background_task("Finding the highest evidence match score within the guardrails...",
                                 calculate, finish, lambda error: finish(error=error))

    def advance_agent_after_reconciliation(self):
        if (vars(self).get("agent_workflow_after_data_streams", False)
                and not vars(self).get("_reconciliation_review_pending", False)
                and self.data_streams_submit_button.isEnabled()):
            self.agent_workflow_after_data_streams = False
            self.agent_workflow_after_site_config = False
            self.handle_data_streams_submit()
            QTimer.singleShot(250, self.agent_workflow_apply_stockpiles)

    def capture_recon_factor_table(self):
        for row in range(self.recon_factor_table.rowCount()):
            for analyte_index, _analyte in enumerate(ANALYTES):
                item = self.recon_factor_table.item(row, 5 + analyte_index * 2)
                if item is None:
                    continue
                key = item.data(Qt.UserRole)
                if not key:
                    continue
                brand, factor_type, analyte = key
                value_record = self.historical_recon_factors[brand][factor_type][analyte]
                if value_record.get("locked"):
                    value_record["effective"] = 1.0
                    continue
                if item.text() == item.data(Qt.UserRole + 1):
                    # Display rounding is not a manual factor edit.
                    value_record["effective"] = item.data(Qt.UserRole + 2)
                    continue
                try:
                    value = float(item.text())
                except (TypeError, ValueError):
                    value = 1.0
                if not math.isfinite(value) or value <= 0:
                    value = 1.0
                    self.historical_recon_warnings.append(
                        f"{brand} / {factor_type} / {analyte}: invalid override defaulted to 1.0."
                    )
                value_record["effective"] = value

    def selected_planning_category(self):
        stream = self.selected_data_stream
        category_key = "product" if stream in {"modelled_product", "adjusted_product"} else "rom"
        if category_key == "product":
            return str(
                self.data_stream_planning_categories.get("product")
                or DEFAULT_PLANNING_CATEGORIES["product"]
            ).strip()
        return str(
            self.data_stream_planning_categories.get("rom")
            or DEFAULT_PLANNING_CATEGORIES["rom"]
        ).strip()

    def reconciliation_inventory_builds(self):
        if normalise_reconciliation_settings(vars(self).get("reconciliation_settings"))["method"] == "standard":
            return []
        return sorted({
            str(row.get("build") or row.get("BUILD") or "").strip().upper()
            for row in (vars(self).get("updated_stockpile_data") or {}).values()
            if not bool(row.get("amt", row.get("AMT", False)))
            and str(row.get("build") or row.get("BUILD") or "").strip()
        })

    def fetch_advanced_reconciliation_inputs(self):
        """Bulk reads run in the existing Data Streams background worker."""
        settings = normalise_reconciliation_settings(vars(self).get("reconciliation_settings"))
        if settings["method"] == "standard":
            return {}
        result = {"samples": [], "inventory_lineage": {}, "warnings": []}
        service = ReconciliationHistory(self.data_stream_reconciliation.inventory_loader)
        try:
            result["samples"], warnings = service.fetch(
                self.start_time_choice, self.opf_input_choice, self.product_brand_labels_choice,
                max_lookback_days=required_history_days(settings, self.opf_input_choice,
                                                       configured_brands(self.product_brand_labels_choice)),
            )
            result["warnings"].extend(warnings)
        except Exception as exc:
            result["warnings"].append(f"Advanced history unavailable; using standard global factors. {exc}")
        try:
            records, warnings = service.fetch_inventory_lineage(
                self.start_time_choice, self.reconciliation_inventory_builds(),
            )
            result["inventory_lineage"] = {r["build"]: r for r in records}
            result["warnings"].extend(warnings)
        except Exception as exc:
            result["warnings"].append(f"Inventory lineage unavailable; using standard global factors. {exc}")
        return result

    def reconciliation_factors_pending(self):
        """Advanced settings survive an opening refresh; their factors do not."""
        state = vars(self)
        return (
            normalise_reconciliation_settings(state.get("reconciliation_settings"))["method"] != "standard"
            and not state.get("historical_recon_factors")
        )

    def reconciliation_application(self):
        state = vars(self)
        settings = normalise_reconciliation_settings(state.get("reconciliation_settings"))
        if settings["method"] == "standard":
            return None
        inputs = state.get("reconciliation_inputs") or {}
        arguments = dict(samples=inputs.get("samples", []),
                         standard_factors=state.get("historical_recon_factors", {}),
                         opf=state.get("opf_input_choice"), brands=state.get("product_brand_labels_choice"),
                         scenario_start=state.get("start_time_choice"), settings=settings)
        signature = reconciliation_fingerprint({"algorithm_version": RECONCILIATION_ALGORITHM_VERSION, **arguments})
        cache = state.get("_reconciliation_application_cache")
        if not cache or cache[0] != signature:
            cache = (signature, ReconciliationApplication(**arguments))
            self._reconciliation_application_cache = cache
        return cache[1]

    def apply_source_reconciliation(self, application, row, streams, source_id, source_kind):
        if application is None:
            row.pop("reconciliation", None)
            return streams
        if source_kind == "amt":
            blocks, warnings = amt_reconciliation_lineage(row)
            total = numeric(row.get("FINAL_WMT", row.get("balance")))
            hex_id = row.get("HEX", row.get("hex"))
        else:
            build = str(row.get("build") or row.get("BUILD") or "").strip().upper()
            lineage = (vars(self).get("reconciliation_inputs") or {}).get("inventory_lineage", {}).get(build, {})
            # Exact build identity is required; never match a footprint to an old build.
            blocks = lineage.get("contributing_blocks", [])
            total = numeric(row.get("balance", row.get("BALANCE", row.get("BALANCE_WMT"))))
            reference_wmt = numeric(lineage.get("inventory_wmt"))
            if reference_wmt is not None and reference_wmt > 0 and total is not None and total > 0:
                blocks = [{**b, "feed_wmt": b["feed_wmt"] * total / reference_wmt} for b in blocks]
            warnings = list(lineage.get("warnings", []))
            hex_id = None
        raw_fields = {str(k).lower(): v for k, v in flatten_available_source_fields(row).items()}
        mappings = mapping_lookup(vars(self).get("field_mappings"), source_kind)
        grade_coverage = {}
        for stream in ("modelled_rom", "modelled_product"):
            grade_coverage[stream] = {}
            for analyte in ANALYTES:
                source = str(mappings.get(f"{stream}_{analyte}") or "").lower()
                coverage = numeric(raw_fields.get(f"{source}_coverage_pct"))
                if coverage is None:
                    coverage = numeric(raw_fields.get(f"modelled_{source}_coverage_pct"))
                if coverage is not None:
                    grade_coverage[stream][analyte] = coverage / 100.0
        streams, audit = application.apply(
            streams, source_id=source_id, source_kind=source_kind,
            source_wmt=max(total or 0.0, 0.0), contributing_blocks=blocks, hex_id=hex_id,
            warnings=warnings, grade_coverage=grade_coverage,
        )
        row["reconciliation"] = audit
        return streams

    def overall_reconciliation_confidence(self):
        """Current selected inventory and AMT chunk confidence, once per source."""
        selected = vars(self).get("updated_stockpile_data") or {}
        sources = [(row.get("reconciliation"), max(numeric(row.get("balance", row.get("BALANCE"))) or 0.0, 0.0))
                   for row in selected.values() if not row.get("amt", row.get("AMT", False))]
        amt_names = {name for name, row in selected.items() if row.get("amt", row.get("AMT", False))}
        chunks = vars(self).get("hex_sequence_table") or []
        chunked_names = {c.get("footprint") for c in chunks}
        sources.extend((c.get("reconciliation"), max(numeric(c.get("balance")) or 0.0, 0.0))
                       for c in chunks if c.get("footprint") in amt_names)
        sources.extend((row.get("reconciliation"), max(numeric(row.get("FINAL_WMT")) or 0.0, 0.0))
                       for name, rows in (vars(self).get("AMT_stockpile_data") or {}).items()
                       if name in amt_names and name not in chunked_names for row in rows)
        return aggregate_reconciliation(sources, source_kind="overall")

    def data_stream_input_request_signature(self):
        """Identify the Snowflake inputs that determine recon and 2WP data."""
        payload = {
            "reconciliation_history": {
                "advanced": normalise_reconciliation_settings(vars(self).get("reconciliation_settings"))["method"] != "standard",
                "max_days": required_history_days(vars(self).get("reconciliation_settings"), self.opf_input_choice,
                                                   configured_brands(self.product_brand_labels_choice)),
            },
            "reconciliation_inventory_builds": self.reconciliation_inventory_builds(),
            "start_time": self.start_time_choice,
            "mine": self.mine_input_choice,
            "opf": self.opf_input_choice,
            "brands": configured_brands(self.product_brand_labels_choice),
            "crushers": sorted(
                str(value) for value in (self.selected_site_crushers or [])
            ),
            "crusher_ratio": self.crusher_contribution_ratio_choice,
            "planning_period_count": self.planning_period_count(),
            "planning_category": self.selected_planning_category(),
            "auto_load_2wp": bool(self.auto_load_2wp_targets_choice),
            "group_2wp_by_brand": bool(
                self.group_2wp_build_targets_by_brand_choice
            ),
            "byproducts_enabled": bool(getattr(self, "byproducts_enabled", False)),
        }
        return json.dumps(payload, sort_keys=True, default=str, separators=(",", ":"))

    def schedule_data_stream_refresh(self, *_args):
        if (
            not getattr(self, "stockpile_data", None)
            or getattr(self, "scenario_switch_in_progress", False)
            or getattr(self, "project_load_restore_in_progress", False)
        ):
            return
        QTimer.singleShot(50, self.prepare_data_streams)

    def prepare_data_streams(self):
        if not self.stockpile_data:
            return
        # The Data Streams page is constructed before Site Configuration is
        # submitted. Refresh Cloudbreak-only visibility on every entry so the
        # checkbox and all explicit Lump/Fines field selectors cannot retain
        # their initial hidden state.
        self.update_byproduct_build_controls()
        self.update_cb_lump_fines_controls()
        self.apply_canonical_field_mappings()
        self.capture_cb_lump_fines_settings()
        self.capture_byproduct_build_settings(validate=False)
        overrides = {}
        if self.historical_recon_factors:
            self.capture_recon_factor_table()
            for brand, record in self.historical_recon_factors.items():
                for factor_type in (
                    "blend",
                    "regression",
                    DataStreamReconciliation.CB_CAMPAIGN_FACTOR,
                ):
                    for analyte, factor_record in (record.get(factor_type, {}) or {}).items():
                        overrides[(brand, factor_type, analyte)] = factor_record.get("effective")
        self.data_stream_effective_overrides = overrides
        self.selected_data_stream = self.data_stream_selector.currentData() or DEFAULT_STREAM
        self.data_stream_planning_categories = normalise_planning_categories({
            "rom": self.rom_planning_category_input.text(),
            "product": self.product_planning_category_input.text(),
        })
        request_signature = self.data_stream_input_request_signature()
        cached_result = getattr(self, "data_stream_input_cache_result", None)
        if (
            str(getattr(self, "data_stream_input_cache_signature", "") or "")
            == request_signature
            and isinstance(cached_result, dict)
            and cached_result
        ):
            self.finish_data_stream_inputs(copy.deepcopy(cached_result))
            return
        if (
            str(getattr(self, "data_stream_input_request_inflight", "") or "")
            == request_signature
        ):
            return
        self.data_stream_input_request_inflight = request_signature
        self.data_streams_submit_button.setEnabled(False)
        review = vars(self).get("reconciliation_review")
        if review is not None:
            review.set_busy(True)
        self.run_background_task(
            "Calculating OPF blend and regression reconciliation factors...",
            self.data_stream_fetch_snapshot(),
            lambda result: self.finish_cached_data_stream_inputs(
                request_signature, result
            ),
            lambda error_message: self.handle_data_stream_inputs_error(
                error_message, request_signature
            ),
        )

    def data_stream_fetch_snapshot(self):
        """Freeze the warehouse context before dispatch; workers never read changing widgets/state."""
        names = ("start_time_choice", "opf_input_choice", "product_brand_labels_choice",
                 "mine_input_choice", "selected_site_crushers", "crusher_contribution_ratio_choice",
                 "auto_load_2wp_targets_choice", "group_2wp_build_targets_by_brand_choice",
                 "byproducts_enabled", "reconciliation_settings")
        context = SimpleNamespace(**{name: copy.deepcopy(vars(self).get(name)) for name in names})
        context.data_stream_reconciliation = self.data_stream_reconciliation
        context.planning_plan_targets = self.planning_plan_targets
        builds = self.reconciliation_inventory_builds()
        periods, category = self.planning_period_count(), self.selected_planning_category()
        context.reconciliation_inventory_builds = lambda: builds
        context.planning_period_count = lambda: periods
        context.selected_planning_category = lambda: category
        context.fetch_advanced_reconciliation_inputs = lambda: UserInputs.fetch_advanced_reconciliation_inputs(context)
        return lambda: UserInputs.fetch_data_stream_inputs(context)

    def fetch_data_stream_inputs(self):
        try:
            factors, warnings = self.data_stream_reconciliation.fetch(
                self.start_time_choice,
                self.opf_input_choice,
                self.product_brand_labels_choice,
            )
        except Exception as exc:
            factors, warnings = self.data_stream_reconciliation.default_factors(
                self.opf_input_choice,
                self.product_brand_labels_choice,
                f"Snowflake reconciliation unavailable; factors defaulted to 1.0. {exc}",
            )
        reconciliation_inputs = self.fetch_advanced_reconciliation_inputs()
        warnings.extend(reconciliation_inputs.get("warnings", []))
        build_targets = {crusher: [] for crusher in self.selected_site_crushers}
        target_errors = {}
        if self.auto_load_2wp_targets_choice:
            planning_category = self.selected_planning_category()
            if not planning_category:
                target_errors["Planning Category"] = (
                    "Product-stream 2WP Planning Category is not configured; "
                    "automatic targets were skipped. Enter the confirmed category or use manual builds."
                )
            for crusher in self.selected_site_crushers:
                if not planning_category:
                    continue
                try:
                    targets = self.planning_plan_targets.fetch(
                        self.mine_input_choice,
                        crusher,
                        self.start_time_choice,
                        self.product_brand_labels_choice,
                        opf=self.opf_input_choice,
                        crusher_contribution_ratio=self.crusher_contribution_ratio_choice,
                        planning_period_count=self.planning_period_count(),
                        planning_category=planning_category,
                        byproducts_enabled=bool(getattr(self, "byproducts_enabled", False)),
                    )
                    if self.group_2wp_build_targets_by_brand_choice:
                        targets = self.planning_plan_targets.group_builds_by_brand(targets)
                    build_targets[crusher] = targets
                except Exception as exc:
                    target_errors[crusher] = str(exc)
        return {
            "factors": factors,
            "reconciliation_inputs": reconciliation_inputs,
            "warnings": warnings,
            "build_targets": build_targets,
            "target_errors": target_errors,
        }

    def finish_cached_data_stream_inputs(self, request_signature, result):
        if (
            str(getattr(self, "data_stream_input_request_inflight", "") or "")
            == str(request_signature or "")
        ):
            self.data_stream_input_request_inflight = ""
        if self.data_stream_input_request_signature() != request_signature:
            return
        self.data_stream_input_cache_signature = str(request_signature or "")
        self.data_stream_input_cache_result = copy.deepcopy(result or {})
        self.finish_data_stream_inputs(copy.deepcopy(result or {}))

    def finish_data_stream_inputs(self, result):
        self.reconciliation_inputs = copy.deepcopy(result.get("reconciliation_inputs") or {})
        self.historical_recon_factors = copy.deepcopy(result.get("factors", {}))
        for (brand, factor_type, analyte), effective in getattr(
            self, "data_stream_effective_overrides", {}
        ).items():
            value_record = (
                self.historical_recon_factors.get(brand, {})
                .get(factor_type, {})
                .get(analyte)
            )
            if value_record and not value_record.get("locked") and numeric(effective) not in (None, 0):
                value_record["effective"] = float(effective)
        self.historical_recon_warnings = copy.deepcopy(result.get("warnings", []))
        self.data_stream_pending_build_targets = copy.deepcopy(
            result.get("build_targets", {})
        )
        self.data_stream_target_errors = copy.deepcopy(
            result.get("target_errors", {})
        )
        self.populate_recon_factor_table()
        display_warnings = list(self.historical_recon_warnings)
        display_warnings.extend(self.update_reconciliation_review())
        display_warnings.extend(self.aps_grade_mapping_warnings())
        display_warnings.extend(
            f"2WP targets ({crusher}): {message}"
            for crusher, message in self.data_stream_target_errors.items()
        )
        warning_text = "\n".join(display_warnings)
        self.data_stream_warning_label.setText(warning_text)
        self.data_stream_warning_label.setVisible(bool(warning_text))
        if vars(self).get("reconciliation_review") is None:
            self.data_streams_submit_button.setEnabled(True)
        self.advance_agent_after_reconciliation()

    def handle_data_stream_inputs_error(self, error_message, request_signature=None):
        if (
            not request_signature
            or str(getattr(self, "data_stream_input_request_inflight", "") or "")
            == str(request_signature)
        ):
            self.data_stream_input_request_inflight = ""
        if (
            request_signature
            and self.data_stream_input_request_signature() != request_signature
        ):
            return
        factors, warnings = self.data_stream_reconciliation.default_factors(
            self.opf_input_choice,
            self.product_brand_labels_choice,
            f"Data Streams setup failed; factors defaulted to 1.0. {error_message}",
        )
        result = {
            "factors": factors,
            "warnings": warnings,
            "build_targets": {},
            "target_errors": {},
        }
        if request_signature:
            self.data_stream_input_cache_signature = str(request_signature)
            self.data_stream_input_cache_result = copy.deepcopy(result)
        self.finish_data_stream_inputs(result)

    @staticmethod
    def cb_split_source_label(row, source_family="source", source_name=None):
        """Return an actionable identity for CB split validation messages."""
        row = row if isinstance(row, dict) else {}

        def first(*keys):
            for key in keys:
                value = row.get(key)
                if value is not None and str(value).strip():
                    return str(value).strip()
            return ""

        family = str(source_family or "source").strip().lower()
        if family in {"amt", "amt hex", "amt_chunk", "amt chunk"}:
            footprint = first("FOOTPRINT", "footprint") or str(
                source_name or ""
            ).strip()
            build = first(
                "LOCATION_NAME", "location_name",
                "AMT_INVENTORY_BUILD", "amt_inventory_build",
            )
            hex_name = first("HEX", "hex")
            parts = [f"AMT stockpile {footprint or '<unknown>'}"]
            if build:
                parts.append(f"build {build}")
            if hex_name:
                identifier = (
                    "chunk" if family in {"amt_chunk", "amt chunk"} else "hex"
                )
                parts.append(f"{identifier} {hex_name}")
            return " / ".join(parts)

        name = str(source_name or "").strip() or first(
            "NAME", "name", "STOCKPILENAME", "stockpilename"
        )
        build = first(
            "BUILD", "build", "STOCKPILEBUILDNAME", "stockpilebuildname"
        )
        parts = [f"Inventory stockpile {name or '<unknown>'}"]
        if build:
            parts.append(f"build {build}")
        return " / ".join(parts)

    def apply_cb_split_to_inventory_row(self, row, source_name=None):
        """Attach canonical CB PROD1 split properties to one inventory row."""
        row = row if isinstance(row, dict) else {}
        state = self.__dict__
        if not self.is_cloudbreak_site():
            return ""
        mode = str(state.get("cb_lump_fines_mode", "derived") or "derived")
        if mode != "calculated":
            method = "mapped_source"
            if numeric(row.get("PROD1_LUMP_WMT", row.get("prod1_lump_wmt"))) is None:
                method = "mapped_source_unavailable"
            row["CB_SPLIT_METHOD"] = row["cb_split_method"] = method
            return ""
        source_label = self.cb_split_source_label(
            row, "inventory", source_name=source_name
        )
        head_grades, fines_grades = self.cb_calculated_grade_vectors(
            row, source_label=source_label, source_family="inventory"
        )
        defined = dict(row.get("defined_fields") or {})
        try:
            calculated = self.cb_split_configured_fields(calculate_cb_lump_fines(
                row,
                state.get("cb_lump_percentage", 50.0),
                product_wmt=defined.get(
                    "modelled_product_wmt", row.get("modelled_product_wmt")
                ),
                product_dmt=defined.get(
                    "modelled_product_dmt", row.get("modelled_product_dmt")
                ),
                head_grades=head_grades,
                fines_grades=fines_grades,
            ))
        except ValueError as exc:
            raise ValueError(f"{source_label}: {exc}") from exc
        self.sync_cb_split_fields(row, calculated)
        return str(calculated.get("cb_split_warning") or "")

    def cb_calculated_grade_vectors(
        self, row, source_label=None, source_family="source"
    ):
        """Return standard-SF head and CBFL-campaign-SF fines grades."""
        source_label = source_label or self.cb_split_source_label(
            row, source_family
        )
        streams = normalise_grade_streams(
            (row or {}).get("grade_streams")
            or (row or {}).get("GRADE_STREAMS")
        )
        modelled_by_brand = streams.get("modelled_product", {}) or {}
        adjusted_by_brand = streams.get("adjusted_product", {}) or {}
        modelled = modelled_by_brand.get("SF") or {}
        head = adjusted_by_brand.get("SF") or {}
        missing_modelled = [
            analyte for analyte in ANALYTES
            if numeric(modelled.get(analyte)) is None
        ]
        if missing_modelled:
            source_family_key = (
                "amt"
                if str(source_family or "").strip().lower()
                in {"amt", "amt hex", "amt chunk"}
                else "inventory"
            )
            mapping_label = (
                "AMT Hex"
                if source_family_key == "amt"
                else str(source_family or "source").title()
            )
            mappings = mapping_lookup(
                vars(self).get("field_mappings"), source_family_key
            )
            target_fields = [
                f"modelled_product_{analyte}"
                for analyte in missing_modelled
            ]
            unmapped = [
                target for target in target_fields
                if not str(mappings.get(target) or "").strip()
            ]
            if unmapped:
                detail = (
                    "is missing required Map Fields mapping(s): "
                    + ", ".join(unmapped)
                    + f". Add the {mapping_label} mapping(s) in Map Fields."
                )
            else:
                detail = (
                    "has no value in mapped source field(s): "
                    + ", ".join(
                        f"{target} <- {mappings[target]}"
                        for target in target_fields
                    )
                    + ". The mappings exist, but this source row has no "
                    "underlying product-grade data."
                )
            raise ValueError(
                f"{source_label} {detail}"
            )
        missing_adjusted = [
            analyte for analyte in ANALYTES
            if numeric(head.get(analyte)) is None
        ]
        if missing_adjusted:
            raise ValueError(
                f"{source_label} has mapped modelled-product grades, but "
                "adjusted_product[SF] could not be calculated for: "
                + ", ".join(
                    f"adjusted_product_{analyte}"
                    for analyte in missing_adjusted
                )
                + ". Check the standard SF regression reconciliation values."
            )
        special = DataStreamReconciliation.CB_CAMPAIGN_FACTOR
        fines = {
            analyte: numeric(modelled[analyte]) * historical_factor(
                self.historical_recon_factors,
                "SF",
                special,
                analyte,
            )
            for analyte in ANALYTES
        }
        return (
            {analyte: numeric(head[analyte]) for analyte in ANALYTES},
            fines,
        )

    def cb_split_configured_fields(self, calculated):
        """Project calculated lane values into the explicit Data Streams fields."""
        values = dict(calculated or {})
        quantities = normalize_byproduct_quantity_fields(
            vars(self).get("byproduct_quantity_fields")
        )
        grades = normalize_byproduct_grade_fields(
            vars(self).get("byproduct_grade_fields")
        )
        for lane in BYPRODUCT_LANES:
            quantity_target = quantities[lane]
            quantity_basis = "dmt" if quantity_target.endswith("_dmt") else "wmt"
            quantity_value = numeric(
                values.get(f"prod1_{lane}_{quantity_basis}")
            )
            if quantity_value is not None:
                values[quantity_target] = quantity_value
            for analyte in PRODUCT_BUILD_ANALYTES:
                grade_value = numeric(values.get(
                    byproduct_grade_source_field(lane, analyte)
                ))
                if grade_value is not None:
                    values[grades[lane][analyte]] = grade_value
        return values

    def sync_cb_split_fields(self, record, calculated):
        """Publish calculated CB size quantities/grades to canonical fields."""
        record = record if isinstance(record, dict) else {}
        defined = dict(record.get("defined_fields") or {})
        properties = dict(record.get("source_properties") or {})
        field_names = {
            row["name"]
            for row in normalize_field_definitions(
                vars(self).get("field_definitions")
            )
        }
        for key, value in calculated.items():
            if key.startswith(("prod1_", "lump_", "fines_", "cb_")):
                record[key] = value
                record[key.upper()] = value
            if key in field_names and numeric(value) is not None:
                defined[key] = numeric(value)
                properties[key] = numeric(value)
        record["defined_fields"] = defined
        record["source_properties"] = properties

    def apply_cb_split_to_amt_row(self, row):
        """Apply the optional user-calculated CB split to one AMT hex."""
        row = row if isinstance(row, dict) else {}
        state = self.__dict__
        if not self.is_cloudbreak_site():
            return ""
        mode = str(state.get("cb_lump_fines_mode", "derived") or "derived")
        raw_payload = row.get("MODELLED_PROPERTIES_JSON")
        if isinstance(raw_payload, str):
            try:
                payload = json.loads(raw_payload)
            except (TypeError, ValueError):
                payload = {}
        else:
            payload = copy.deepcopy(raw_payload or {})
        values = dict(payload.get("values") or {})
        coverage = dict(payload.get("coverage") or {})
        if mode != "calculated":
            method = "mapped_or_grade_block_derived"
            if numeric(values.get("prod1_lump_wmt")) is None:
                method = "mapped_or_grade_block_derived_unavailable"
            row["CB_SPLIT_METHOD"] = method
            row["CB_SPLIT_WARNING"] = ""
            return ""

        source_label = self.cb_split_source_label(row, "amt")
        head_grades, fines_grades = self.cb_calculated_grade_vectors(
            row, source_label=source_label, source_family="AMT Hex"
        )
        defined = dict(row.get("defined_fields") or {})
        try:
            calculated = self.cb_split_configured_fields(calculate_cb_lump_fines(
                {**values, **defined},
                state.get("cb_lump_percentage", 50.0),
                product_wmt=defined.get(
                    "modelled_product_wmt", row.get("modelled_product_wmt")
                ),
                product_dmt=defined.get(
                    "modelled_product_dmt", row.get("modelled_product_dmt")
                ),
                head_grades=head_grades,
                fines_grades=fines_grades,
            ))
        except ValueError as exc:
            raise ValueError(f"{source_label}: {exc}") from exc
        field_names = {
            definition["name"]
            for definition in normalize_field_definitions(
                vars(self).get("field_definitions")
            )
        }
        for key, value in calculated.items():
            if (
                not key.startswith(("prod1_", "lump_", "fines_", "cb_"))
                and key not in field_names
            ):
                continue
            if isinstance(value, (int, float)) and math.isfinite(float(value)):
                values[key] = float(value)
                if key.startswith("prod1_") and any(
                    key.endswith("_" + assay)
                    for assay in (
                        "fe", "sio2", "al2o3", "mn", "p", "loi_425",
                        "loi_total", "s", "as",
                    )
                ):
                    assay = next(
                        assay for assay in (
                            "loi_total", "loi_425", "al2o3", "sio2",
                            "fe", "mn", "p", "s", "as",
                        ) if key.endswith("_" + assay)
                    )
                    coverage[key] = coverage.get(f"prod1_{assay}", 1.0)
                else:
                    coverage[key] = 1.0
                column = f"MODELLED_{key.upper()}"
                row[column] = float(value)
                row[f"{column}_COVERAGE_PCT"] = coverage[key] * 100.0
        payload["values"] = values
        payload["coverage"] = coverage
        row["MODELLED_PROPERTIES_JSON"] = json.dumps(
            payload, default=str, separators=(",", ":")
        )
        row["CB_SPLIT_METHOD"] = str(calculated.get("cb_split_method") or "")
        row["CB_SPLIT_WARNING"] = str(calculated.get("cb_split_warning") or "")
        self.sync_cb_split_fields(row, calculated)
        return row["CB_SPLIT_WARNING"]

    def apply_cb_split_to_amt_chunk(self, chunk):
        """Apply calculated CB lump/fines after member hexes are aggregated."""
        chunk = chunk if isinstance(chunk, dict) else {}
        if not self.is_cloudbreak_site():
            return ""
        if str(vars(self).get("cb_lump_fines_mode", "derived") or "derived") != "calculated":
            return ""

        payload = copy.deepcopy(chunk.get("modelled_properties") or {})
        values = dict(payload.get("values") or {})
        coverage = dict(payload.get("coverage") or {})
        defined = dict(chunk.get("defined_fields") or {})

        # Chunk aggregation makes canonical modelled_properties authoritative.
        # A chunk rebuilt after loading a project may not yet have its parallel
        # grade_streams projection, even though every required aggregate grade
        # is present.  Repair that projection here before validating the CB
        # split so a complete chunk is not rejected as missing source data.
        streams = normalise_grade_streams(
            chunk.get("grade_streams") or chunk.get("GRADE_STREAMS")
        )
        modelled_by_brand = streams.setdefault("modelled_product", {})
        modelled = dict(modelled_by_brand.get("SF") or {})
        for analyte in ANALYTES:
            # modelled_properties is the freshly aggregated chunk result.
            # defined_fields may still contain a stockpile/hex-era projection
            # after a project load, so it must not override the chunk value.
            aggregate = numeric(values.get(f"modelled_product_{analyte}"))
            if aggregate is None:
                aggregate = numeric(defined.get(f"modelled_product_{analyte}"))
            if aggregate is not None:
                modelled[analyte] = aggregate
        modelled_by_brand["SF"] = modelled

        regression = {
            analyte: historical_factor(
                self.historical_recon_factors,
                "SF",
                "regression",
                analyte,
            )
            for analyte in ANALYTES
        }
        if not (chunk.get("reconciliation") or {}).get("by_brand", {}).get("SF"):
            streams.setdefault("adjusted_product", {})["SF"] = {
                analyte: (
                    numeric(modelled.get(analyte)) * regression[analyte]
                    if numeric(modelled.get(analyte)) is not None else None
                )
                for analyte in ANALYTES
            }
        chunk["grade_streams"] = streams
        chunk["GRADE_STREAMS"] = streams

        source_label = self.cb_split_source_label(chunk, "amt_chunk")
        head_grades, fines_grades = self.cb_calculated_grade_vectors(
            chunk, source_label=source_label, source_family="AMT Chunk"
        )
        # As with the product grades above, the post-aggregation payload is
        # authoritative.  A rebuilt chunk can retain an older mapped value in
        # defined_fields, which must not change the requested percentage split.
        product_wmt = numeric(values.get("modelled_product_wmt"))
        if product_wmt is None:
            product_wmt = numeric(defined.get("modelled_product_wmt"))
        product_dmt = numeric(values.get("modelled_product_dmt"))
        if product_dmt is None:
            product_dmt = numeric(defined.get("modelled_product_dmt"))
        try:
            calculated = self.cb_split_configured_fields(calculate_cb_lump_fines(
                {**chunk, **values, **defined},
                vars(self).get("cb_lump_percentage", 50.0),
                product_wmt=product_wmt,
                product_dmt=product_dmt,
                head_grades=head_grades,
                fines_grades=fines_grades,
            ))
        except ValueError as exc:
            raise ValueError(f"{source_label}: {exc}") from exc

        quantity_fields = normalize_byproduct_quantity_fields(
            vars(self).get("byproduct_quantity_fields")
        )
        grade_fields = normalize_byproduct_grade_fields(
            vars(self).get("byproduct_grade_fields")
        )
        calculated_targets = set(quantity_fields.values())
        calculated_targets.update(
            field
            for lane_fields in grade_fields.values()
            for field in lane_fields.values()
        )
        field_names = {
            definition["name"]
            for definition in normalize_field_definitions(
                vars(self).get("field_definitions")
            )
        }

        def input_coverage(field_name):
            if field_name.endswith("_dmt"):
                return numeric(coverage.get("modelled_product_dmt"))
            if field_name.endswith("_wmt"):
                return numeric(coverage.get("modelled_product_wmt"))
            suffix_map = {"sio2": "si", "al2o3": "al"}
            analyte = next(
                (
                    suffix_map.get(suffix, suffix)
                    for suffix in (
                        "sio2", "al2o3", "fe", "si", "al", "p", "mn"
                    )
                    if field_name.endswith("_" + suffix)
                ),
                None,
            )
            return (
                numeric(coverage.get(f"modelled_product_{analyte}"))
                if analyte else None
            )

        for key, value in calculated.items():
            numeric_value = numeric(value)
            if numeric_value is None:
                continue
            if key.startswith(("prod1_", "lump_", "fines_")) or key in field_names:
                values[key] = numeric_value
            if key in calculated_targets:
                coverage[key] = input_coverage(key)

        payload["values"] = values
        payload["coverage"] = coverage
        chunk["modelled_properties"] = payload
        self.sync_cb_split_fields(chunk, calculated)
        chunk["cb_split_method"] = str(calculated.get("cb_split_method") or "")
        chunk["CB_SPLIT_METHOD"] = chunk["cb_split_method"]
        warning = str(calculated.get("cb_split_warning") or "")
        chunk["cb_split_warning"] = warning
        chunk["CB_SPLIT_WARNING"] = warning

        quality = dict(chunk.get("data_quality") or {})
        mapped_coverage = dict(quality.get("mapped_field_coverage_pct") or {})
        for field_name in calculated_targets:
            fraction = numeric(coverage.get(field_name))
            if fraction is not None:
                mapped_coverage[field_name] = fraction * 100.0
        quality["mapped_field_coverage_pct"] = mapped_coverage
        chunk["data_quality"] = quality
        if warning:
            warnings = list(chunk.get("grade_stream_warnings") or [])
            warnings.append(warning)
            chunk["grade_stream_warnings"] = list(dict.fromkeys(warnings))
        return warning

    def apply_cb_split_to_amt_chunks(self, chunks):
        """Calculate CB by-products for every submitted AMT scheduling chunk."""
        for chunk in chunks or []:
            if isinstance(chunk, dict):
                self.apply_cb_split_to_amt_chunk(chunk)
        return chunks

    def apply_grade_streams_to_inventory(self, *, allow_pending=False):
        # Setup pages precede the Data Streams fetch. Leave their raw fields
        # available without presenting unreconciled values as adjusted grades.
        if allow_pending and self.reconciliation_factors_pending():
            return
        application = self.reconciliation_application()
        source_prefixes = tuple(
            f"{name}:" for name in (self.stockpile_data or {})
        )

        def obsolete_brand_alias_warning(warning):
            marker = ": no history in 30 days; using "
            text = str(warning or "")
            if marker not in text:
                return False
            requested = text.split(marker, 1)[0].rsplit(" / ", 1)[-1].strip().upper()
            source = text.split(marker, 1)[1].rstrip(".").strip().upper()
            return bool(requested and source.endswith(requested))

        self.historical_recon_warnings = [
            warning
            for warning in (self.historical_recon_warnings or [])
            if (
                (not source_prefixes or not str(warning).startswith(source_prefixes))
                and not str(warning).startswith("APS 24HR grade mapping:")
                and not obsolete_brand_alias_warning(warning)
            )
        ]
        self.historical_recon_warnings.extend(
            self.aps_grade_mapping_warnings()
        )
        self.data_stream_source_warnings = {}

        selected_rows = self.included_stockpile_data()
        selected_keys = {
            str(name).strip().upper() for name in selected_rows
        }
        selected_inventory_keys = {
            str(name).strip().upper()
            for name, attributes in selected_rows.items()
            if not bool(
                (attributes or {}).get(
                    "amt", (attributes or {}).get("AMT", False)
                )
            )
        }

        def enrich_row(name, row, apply_calculated_split=False):
            """Build streams while validating CB split only for run sources."""
            row.update(inventory_product_property_aliases(
                row, self.opf_input_choice
            ))
            streams = inventory_grade_streams(
                row,
                self.product_brand_labels_choice,
                self.historical_recon_factors,
                self.opf_input_choice,
                strict_mappings=True,
            )
            streams = self.apply_source_reconciliation(application, row, streams, name, "inventory")
            row["GRADE_STREAMS"] = streams
            row["grade_streams"] = streams
            self.sync_canonical_grade_fields(row, streams)
            warnings = self.inventory_stream_warnings(name, row)
            warnings.extend(f"{name}: {w}" for w in row.get("reconciliation", {}).get("warnings", []))
            if apply_calculated_split:
                cb_warning = self.apply_cb_split_to_inventory_row(
                    row, source_name=name
                )
                if cb_warning:
                    warnings.append(f"{name}: {cb_warning}")
            row["GRADE_STREAM_WARNINGS"] = warnings
            row["grade_stream_warnings"] = warnings
            if warnings and str(name).strip().upper() in selected_keys:
                self.data_stream_source_warnings[name] = warnings

        # The fetched inventory contains every stockpile at the site. Keep its
        # audit streams current, but never let an unselected row block a run.
        for name, row in self.included_AMT_snapshot(self.stockpile_data).items():
            enrich_row(
                name,
                row,
                apply_calculated_split=(
                    str(name).strip().upper() in selected_inventory_keys
                ),
            )

        # Selected rows are independent copies created on Stockpile Inventories
        # submission and are the records passed downstream. Enrich them too.
        for name, row in selected_rows.items():
            is_amt = bool((row or {}).get("amt", (row or {}).get("AMT", False)))
            enrich_row(name, row, apply_calculated_split=not is_amt)

    def aps_grade_mapping_warnings(self):
        """Summarise missing APS fields without flooding Decision Point logs."""
        if not str(getattr(self, "file_path_24hr_choice", "") or "").strip():
            return []
        mappings = normalise_aps_grade_field_mappings(
            getattr(self, "aps_grade_field_mappings", None),
            self.product_brand_labels_choice,
        )
        warnings = []
        for brand in configured_brands(self.product_brand_labels_choice):
            for stream, label in (("rom", "ROM"), ("product", "Product")):
                fields = (mappings.get(stream, {}) or {}).get(brand, {}) or {}
                missing = [
                    analyte for analyte in ANALYTES
                    if not str(fields.get(analyte) or "").strip()
                ]
                if missing:
                    warnings.append(
                        f"APS 24HR grade mapping: {brand} {label} is missing "
                        f"{', '.join(missing)}; APS sources fall back independently per analyte."
                    )
        return warnings

    def inventory_stream_warnings(self, name, row):
        row = row or {}

        def present(*names):
            return any(
                numeric(row.get(candidate)) is not None
                for name_value in names
                for candidate in (name_value, name_value.upper())
            )

        missing_insitu = [
            analyte for analyte in ANALYTES
            if not present(f"grade_{analyte}", f"{analyte}_insitu", f"insitu_{analyte}")
        ]
        messages = []
        if missing_insitu:
            messages.append(
                f"{name}: missing inventory insitu grade for {', '.join(missing_insitu)}; "
                "Modelled and Adjusted ROM fall back independently per analyte."
            )
        slot = internal_product_slot(self.opf_input_choice)
        if slot is None and not is_dry_plant(self.opf_input_choice):
            messages.append(
                f"{name}: OPF product mapping is not confirmed; product streams fall back to Adjusted ROM."
            )
        if slot and not is_dry_plant(self.opf_input_choice):
            missing_product = [
                analyte for analyte in ANALYTES
                if not present(f"{analyte}_{slot}", f"{slot}_{analyte}")
            ]
            if missing_product:
                messages.append(
                    f"{name}: missing inventory {slot.upper()} for {', '.join(missing_product)}; "
                    "product falls back independently to Adjusted ROM."
                )
        return messages

    def handle_data_streams_submit(self):
        if vars(self).get("reconciliation_review") is not None:
            self.capture_recon_factor_table()
            if vars(self).get("_reconciliation_review_signature") != self.reconciliation_review_signature():
                self.prepare_data_streams()
                return
        self.selected_data_stream = self.data_stream_selector.currentData() or DEFAULT_STREAM
        self.crusher_tonnes_stream = self.crusher_tonnes_selector.currentData() or "modelled_rom_wmt"
        self.reclaimer_tonnes_stream = self.reclaimer_tonnes_selector.currentData() or "modelled_rom_wmt"
        self.product_build_tonnes_stream = self.product_build_tonnes_selector.currentData() or "modelled_product_wmt"
        self.data_stream_planning_categories = normalise_planning_categories({
            "rom": self.rom_planning_category_input.text(),
            "product": self.product_planning_category_input.text(),
        })
        try:
            self.capture_cb_lump_fines_settings()
            self.capture_byproduct_build_settings()
        except ValueError as exc:
            QMessageBox.warning(self, "Data Streams", str(exc))
            return
        try:
            self.capture_recon_factor_table()
            self.apply_canonical_field_mappings()
            self.apply_grade_streams_to_inventory()
            self.refresh_AMT_enrichment_if_needed(
                persist=True,
                refresh_map=True,
            )
        except ValueError as exc:
            QMessageBox.warning(self, "Data Streams", str(exc))
            return
        if self.data_stream_pending_build_targets:
            # Stockpile Inventories has already established and persisted the
            # opening source set.  Applying later 2WP targets must not clear
            # and rewrite those opening tables.
            self.register_submitted_site_scenarios(
                self.data_stream_pending_build_targets,
                reset_database=False,
            )
        self.data_stream_reconciliation.save_to_database(
            self.opf_input_choice,
            self.start_time_choice,
            self.historical_recon_factors,
            self.historical_recon_warnings,
        )
        self.save_active_scenario_state()
        self.set_page_enabled(self.data_streams_tab_index, True)
        # The field schema remains editable after Data Streams. It is common
        # to return to the raw sources while auditing recon factors.
        for page_id in (
            self.stockpile_tab_index,
            self.define_fields_tab_index,
            self.map_fields_tab_index,
        ):
            self.set_page_enabled(page_id, True)
        self.set_page_enabled(self.guidance_schedules_tab_index, True)
        if any((self.stockpile_data_AMT_column or {}).values()):
            self.set_page_enabled(self.AMT_stockpile_tab_index, True)
            self.show_page(self.AMT_stockpile_tab_index, force=True)
        else:
            self.hex_sequence_table = []
            self.hex_sequence_table_argument = []
            self.open_database_view(navigate=True)

