    def handle_site_config_submit(self):
        """Submit one explicit Hub / Mine / OPF / Crusher scenario."""
        restoring_project = bool(
            self.is_project_loaded and self.project_load_restore_in_progress
        )
        if restoring_project:
            self.restore_site_configuration_controls()
        else:
            self.capture_site_configuration_controls()
            valid, validation_message = self.validate_site_configuration_constraints()
            if not valid:
                QMessageBox.warning(
                    self,
                    "Site Configuration",
                    validation_message,
                )
                return

        required_values = (
            self.hub_input_choice,
            self.mine_input_choice,
            getattr(self, "opf_input_choice", None),
            self.crusher_input_choice,
            self.time_mode_choice,
            self.start_time_choice,
            self.expit_mode_choice,
            self.blend_mode_choice,
        )
        if not all(required_values):
            QMessageBox.warning(
                self,
                "Missing Information",
                "Please complete Hub, Mine, OPF, Operating Crusher, and run timing.",
            )
            return

        inventory_signature = self.inventory_opening_request_signature()
        if (
            self.is_project_loaded
            and self.opening_request_signatures_match(
                getattr(self, "inventory_data_request_signature", ""),
                inventory_signature,
            )
        ):
            if not self.stockpile_data:
                QMessageBox.warning(
                    self,
                    "Missing Project Data",
                    "The loaded project does not contain stockpile inventory data.",
                )
                return
            self.finish_site_config_submit(self.stockpile_data)
            return

        if restoring_project:
            self.project_load_waiting_for_inventory = True
        self.submit_button.setEnabled(False)
        progress_message = "Fetching stockpile inventories from Snowflake..."
        self.run_background_task(
            progress_message,
            lambda: self.fetch_site_configuration_data(inventory_signature),
            self.finish_site_config_submit,
            self.handle_site_config_error,
        )

    def fetch_stockpile_data(self):
        """Fetch stockpile data from OpeningStockpileInventories."""
        hub_input = self.hub_input_choice
        mine_input = self.mine_input_choice
        return self.opening_stockpile_inventories.call_opening_stockpile_inventories(hub_input, mine_input, self.start_time_choice)

    def inventory_opening_request_signature(self):
        """Identify the Snowflake inputs that determine inventory opening data."""
        start_time = getattr(self, "start_time_choice", None)
        if hasattr(start_time, "toPyDateTime"):
            start_time = start_time.toPyDateTime()
        payload = {
            "cache_version": 1,
            "hub": str(getattr(
                self, "hub_input_choice", ""
            ) or "").strip().upper(),
            "mine": str(getattr(
                self, "mine_input_choice", ""
            ) or "").strip().upper(),
            "opf": str(getattr(
                self, "opf_input_choice", ""
            ) or "").strip().upper(),
            "crusher": str(getattr(
                self, "crusher_input_choice", ""
            ) or "").strip().upper(),
            "start_time": self.AMT_opening_timestamp_key(start_time),
        }
        return json.dumps(payload, sort_keys=True, separators=(",", ":"))

    def fetch_site_configuration_data(self, request_signature=None):
        stockpile_data = self.fetch_stockpile_data()
        return {
            "stockpile_data": stockpile_data,
            "inventory_data_request_signature": (
                request_signature or self.inventory_opening_request_signature()
            ),
            "build_targets": {},
            "target_errors": {},
            "automatic_2wp_targets": self.auto_load_2wp_targets_choice,
        }

    def reset_downstream_inputs_for_new_site_configuration(
        self, preserve_calendar=False
    ):
        """Clear workflow state that is owned by the submitted site context."""
        preserved_calendar_inputs = copy.deepcopy(
            getattr(self, "calendar_inputs", {}) or {}
        ) if preserve_calendar else {}
        preserved_solver_config = copy.deepcopy(
            getattr(self, "solver_config", {}) or {}
        ) if preserve_calendar else {}
        preserved_min_stockpiles = getattr(self, "min_stockpiles", None)
        preserved_max_stockpiles = getattr(self, "max_stockpiles", None)
        preserved_minimum_contribution = getattr(
            self,
            "min_stockpile_contribution_ratio",
            Optimizer.MIN_SELECTED_STOCKPILE_BLEND_RATIO,
        )
        self.stockpile_data_use_column = {}
        self.stockpile_data_AMT_column = {}
        # The table can still contain rows from the previously active site.
        # Leaving them rendered lets capture_scenario_state repopulate the two
        # freshly-cleared selection dictionaries before Guidance Schedules has
        # had a chance to derive the new defaults.
        if hasattr(self, "stockpile_table"):
            self.stockpile_table.blockSignals(True)
            self.stockpile_table.clearContents()
            self.stockpile_table.setRowCount(0)
            self.stockpile_table.blockSignals(False)
        self.updated_stockpile_data = None
        self.updated_stockpile_data_keys = {}.keys()
        self.AMT_stockpile_data = {}
        self.inventory_data_request_signature = ""
        self.AMT_footprint_exclusions = {}
        self.AMT_data_request_signature = ""
        self.AMT_enrichment_signature = ""
        self._available_mapping_fields_cache = {}
        self.AMT_chunk_settings = {}
        self.historical_recon_factors = {}
        self.historical_recon_warnings = []
        self.reconciliation_inputs = {}
        self._reconciliation_application_cache = None
        self.data_stream_source_warnings = {}
        self.data_stream_pending_build_targets = {}
        self.data_stream_target_errors = {}
        self.data_stream_input_cache_signature = ""
        self.data_stream_input_cache_result = {}
        self.data_stream_input_request_inflight = ""
        self.hex_sequence_table = []
        self.hex_sequence_table_argument = []
        self.calendar_inputs = preserved_calendar_inputs
        # The rendered Calendar may still belong to the previous timestamp or
        # scenario. Until setup_calendar rebuilds it, the restored dictionary
        # remains authoritative and must not be overwritten by stale widgets.
        self.calendar_table_refresh_pending = True
        self.solver_config = self.normalized_solver_config(
            preserved_calendar_inputs.get(
                "solver_config", preserved_solver_config
            )
        )
        self.min_stockpiles = (
            preserved_calendar_inputs.get(
                "min_stockpiles", preserved_min_stockpiles
            )
            if preserve_calendar else None
        )
        self.max_stockpiles = (
            preserved_calendar_inputs.get(
                "max_stockpiles", preserved_max_stockpiles
            )
            if preserve_calendar else None
        )
        self.min_stockpile_contribution_ratio = (
            preserved_calendar_inputs.get(
                "min_stockpile_contribution_ratio",
                preserved_minimum_contribution,
            )
            if preserve_calendar
            else Optimizer.MIN_SELECTED_STOCKPILE_BLEND_RATIO
        )
        self.saved_blends_for_schedule = []
        self.stored_blend_sequence_table_for_gantt = []
        self.stored_blend_sequence_table_for_gantt_default = []
        self.default_start_datetime = None
        self.default_end_datetime = None
        self.default_start_datetime_str = None
        self.default_end_datetime_str = None
        self.crusher_rate = None
        self.crusher_rate_input_value = None
        self.crusher_rate_input_values = {}
        self.blend_config_table_inputs = {}
        self.total_AMT_stockpile_balances = {}
        self.restore_table_snapshot(getattr(self, "decision_table", None), None)
        if hasattr(self, "decision_output"):
            self.decision_output.clear()
        if hasattr(self, "decision_status_label"):
            self.decision_status_label.setText(
                "Run the optimiser to review feasible blend options."
            )

    def register_submitted_site_scenarios(
        self, build_targets, reset_database=True
    ):
        selected_crushers = list(self.selected_site_crushers or [])
        if not selected_crushers:
            return

        current_crusher = selected_crushers[0]
        self.crusher_input_choice = current_crusher
        self.product_targets = copy.deepcopy(build_targets.get(current_crusher) or [])
        self.populate_product_build_table()
        self.saved_blends_for_schedule = []
        self.stored_blend_sequence_table_for_gantt = []
        self.stored_blend_sequence_table_for_gantt_default = []
        self.reset_workflow_tabs_for_scenario()
        if reset_database:
            DatabaseManager.clear_all_tables(get_database_path())
            self.seed_active_scenario_database(force=True)
        current_state = self.capture_scenario_state()
        current_state["crusher_input_choice"] = current_crusher
        current_state["selected_site_crushers"] = [current_crusher]
        current_state["opf_input_choice"] = self.opf_input_choice
        current_state["crusher_contribution_ratio_choice"] = (
            self.crusher_contribution_ratio_choice
        )
        current_state["direct_tip_movement_rules"] = copy.deepcopy(
            self.direct_tip_movement_rules
        )
        self.site_scenarios[self.active_scenario_id] = current_state
        self.selected_site_crushers = [current_crusher]
        self.update_site_crusher_options(self.selected_site_crushers)
        self.refresh_scenario_selector()

    def finish_site_config_submit(self, stockpile_data):
        restoring_project = bool(
            self.is_project_loaded
            and self.project_load_restore_in_progress
        )
        self.submit_button.setEnabled(True)
        self.save_button.setEnabled(True)
        build_targets = {}
        target_errors = {}
        automatic_2wp_targets = True
        fresh_site_configuration = (
            isinstance(stockpile_data, dict) and "stockpile_data" in stockpile_data
        )
        refreshed_current_time = bool(
            restoring_project
            and getattr(self, "project_load_refresh_current_time", False)
            and fresh_site_configuration
        )
        previous_scenario = (
            self.site_scenarios.get(self.active_scenario_id, {})
            if isinstance(getattr(self, "site_scenarios", None), dict)
            else {}
        )
        calendar_context = (
            (getattr(self, "calendar_inputs", {}) or {}).get("site_context")
            or previous_scenario
            or {}
        )
        identity_fields = ("hub", "mine", "opf", "crusher")
        current_identity = {
            "hub": self.hub_input_choice,
            "mine": self.mine_input_choice,
            "opf": self.opf_input_choice,
            "crusher": self.crusher_input_choice,
        }
        context_identity = {
            field: (
                calendar_context.get(field)
                or previous_scenario.get(f"{field}_input_choice")
            )
            for field in identity_fields
        }
        same_calendar_context = all(
            str(context_identity[field] or "").strip().upper()
            == str(current_identity[field] or "").strip().upper()
            for field in identity_fields
        ) and PeriodManager.normalize_period_count(
            calendar_context.get(
                "planning_period_count",
                previous_scenario.get(
                    "planning_period_count_choice",
                    self.planning_period_count(),
                ),
            )
        ) == self.planning_period_count()
        preserve_calendar_configuration = bool(
            fresh_site_configuration
            and getattr(self, "calendar_inputs", None)
            and same_calendar_context
        )
        preserved_use_selection = copy.deepcopy(
            getattr(self, "project_load_saved_stockpile_use_column", {}) or {}
        )
        preserved_amt_selection = copy.deepcopy(
            getattr(self, "project_load_saved_stockpile_AMT_column", {}) or {}
        )
        preserved_amt_exclusions = normalize_amt_exclusions(
            vars(self).get("AMT_footprint_exclusions")
        ) if restoring_project or same_calendar_context else {}
        if fresh_site_configuration:
            build_targets = stockpile_data.get("build_targets") or {}
            target_errors = stockpile_data.get("target_errors") or {}
            automatic_2wp_targets = bool(
                stockpile_data.get("automatic_2wp_targets", True)
            )
            inventory_signature = str(
                stockpile_data.get("inventory_data_request_signature")
                or self.inventory_opening_request_signature()
            )
            stockpile_data = stockpile_data.get("stockpile_data") or {}
            self.reset_downstream_inputs_for_new_site_configuration(
                preserve_calendar=preserve_calendar_configuration
            )
            self.AMT_footprint_exclusions = preserved_amt_exclusions
            self.inventory_data_request_signature = inventory_signature
        self.stockpile_data = stockpile_data
        if refreshed_current_time:
            saved_use = {
                str(name).strip().upper(): bool(selected)
                for name, selected in preserved_use_selection.items()
            }
            saved_amt = {
                str(name).strip().upper(): bool(selected)
                for name, selected in preserved_amt_selection.items()
            }
            self.stockpile_data_use_column = {
                name: saved_use.get(str(name).strip().upper(), False)
                for name in self.stockpile_data
            }
            self.stockpile_data_AMT_column = {
                name: (
                    self.stockpile_data_use_column.get(name, False)
                    and saved_amt.get(str(name).strip().upper(), False)
                )
                for name in self.stockpile_data
            }
            self.updated_stockpile_data = None
            self.AMT_stockpile_data = {}
            self.AMT_data_request_signature = ""
            self.AMT_enrichment_signature = ""
            self.AMT_chunk_reconciliation_signature = ""
            self.AMT_chunk_settings = {}
            self.hex_sequence_table = []
            self.hex_sequence_table_argument = []
            self.product_targets = []
            self.saved_blends_for_schedule = []
            self.stored_blend_sequence_table_for_gantt = []
            self.stored_blend_sequence_table_for_gantt_default = []
            self.manual_direct_tip_allocations = {}
            self.manual_steady_states = []
            self.manual_plan_states = {}
            self.populate_product_build_table()
            DatabaseManager.clear_all_tables(get_database_path())
            self.opening_stockpile_inventories.save_to_database(
                self.stockpile_data
            )
        self.refresh_aps_stockpile_brand_map()
        self.apply_aps_brand_guidance_to_stockpile_data()
        # Project restore must hydrate Data Streams before capturing the active
        # scenario. Otherwise the still-default mapping widget overwrites the
        # mappings that were just read from the project file.
        if restoring_project:
            self.populate_aps_grade_mapping_table()
            self.populate_aps_source_property_mapping_table()
            self.load_cb_lump_fines_settings()
            self.load_byproduct_build_settings()
            self.populate_recon_factor_table()
        if self.haul_cycle_file_path_choice:
            self.refresh_haul_cycle_routes(show_errors=True)
        else:
            self.apply_haul_cycle_routes_to_stockpile_data()
        if build_targets and not refreshed_current_time:
            self.register_submitted_site_scenarios(build_targets)
        else:
            self.save_active_scenario_state()
        message = (
            f"Configuration successfully submitted for Hub: {self.hub_input_choice}, "
            f"Mine: {self.mine_input_choice}, OPF: {self.opf_input_choice}, "
            f"Crusher: {self.crusher_input_choice} "
            f"({self.crusher_contribution_ratio_choice * 100:.2f}% contribution).\n\n"
            f"The model now contains {len(self.site_scenarios)} site scenario(s). "
            "Use Active Site Scenario above the tabs to switch inputs and outputs."
        )
        if target_errors:
            failed = ", ".join(sorted(target_errors))
            message += f"\n\n2WP build targets could not be loaded for: {failed}. Manual build entry remains available."
        elif not automatic_2wp_targets:
            message += (
                "\n\nAutomatic 2WP product-build targets were skipped. "
                "Use Product Targets for manual entry or load them there later."
            )
        if not restoring_project:
            QMessageBox.information(self, "BlendMaster", message)

        if restoring_project:
            # A restored project already owns authoritative guidance and
            # stockpile choices, so rebuild its table immediately.  Fresh
            # scenarios defer this until Guidance Schedules has populated the
            # APS brand and nearest-crusher fields used by preselection.
            self.setup_stockpile_table()
        self.populate_define_fields_table()
        self.refresh_map_field_brands()
        self.ensure_field_mapping_migration()
        self.populate_map_fields_table()
        self.load_cb_lump_fines_settings()
        # Data Streams is created once at application start.  A project load
        # replaces the saved by-product state afterwards, so explicitly
        # rehydrate its checkbox and its quantity/grade selectors here.
        self.load_byproduct_build_settings()
        self.refresh_map_available_fields()
        self.populate_recon_factor_table()
        if not restoring_project:
            self.set_page_enabled(self.guidance_schedules_tab_index, True)
            self.set_page_enabled(self.stockpile_tab_index, False)
            self.set_page_enabled(self.define_fields_tab_index, False)
            self.set_page_enabled(self.map_fields_tab_index, False)
            self.set_page_enabled(self.data_streams_tab_index, False)
            self.show_page(self.guidance_schedules_tab_index, force=True)
        else:
            self.set_page_enabled(self.guidance_schedules_tab_index, True)
            self.set_page_enabled(self.stockpile_tab_index, True)
            self.apply_canonical_field_mappings()
            self.apply_grade_streams_to_inventory(allow_pending=True)
        self.validate_form()

        if restoring_project and getattr(
            self, "project_load_waiting_for_inventory", False
        ):
            self.project_load_waiting_for_inventory = False
            if fresh_site_configuration:
                # A new opening snapshot invalidates downstream inputs,
                # including reconciliation factors. Resume setup before
                # Data Streams fetches the factors for this opening context.
                self.project_load_restore_in_progress = False
                self.project_load_continuation_pending = False
                self.reset_workflow_tabs_for_scenario()
                self.set_page_enabled(self.site_config_tab_index, True)
                self.set_page_enabled(self.guidance_schedules_tab_index, True)
                self.set_page_enabled(self.stockpile_tab_index, True)
                self.save_active_scenario_state()
                self.finish_project_load_ui(success=True)
                self.show_page(self.stockpile_tab_index, force=True)
                return

            self.store_stockpile_table()
            if getattr(self, "project_load_waiting_for_AMT", False):
                return
            self.continue_project_load_after_stockpile_setup()

        if getattr(self, "agent_workflow_after_site_config", False):
            self.agent_workflow_after_data_streams = True

    def handle_guidance_schedules_submit(self):
        """Apply optional schedule guidance before inventory selection."""
        if not self.stockpile_data:
            QMessageBox.warning(
                self,
                "Guidance Schedules",
                "Submit Site Configuration before applying guidance schedules.",
            )
            return

        self.capture_guidance_schedule_controls()
        valid, validation_message = (
            self.validate_guidance_schedule_constraints()
        )
        if not valid:
            QMessageBox.warning(
                self,
                "Guidance Schedules",
                validation_message,
            )
            self.validate_form()
            return

        try:
            closing_stocks_path = vars(self).get(
                "two_wp_closing_stocks_path_choice", ""
            )
            self.two_wp_closing_stock_balances = (
                ClosingROMStocksCompliance.read_workbook(
                    closing_stocks_path
                )
                if closing_stocks_path
                else pd.DataFrame(
                    columns=ClosingROMStocksCompliance.NORMALIZED_COLUMNS
                )
            )
        except (OSError, ValueError, ImportError) as error:
            QMessageBox.warning(
                self, "Guidance Schedules", str(error)
            )
            return
        DatabaseManager().write_two_wp_closing_rom_stocks(
            self.two_wp_closing_stock_balances
        )

        self.refresh_aps_stockpile_brand_map()
        self.apply_aps_brand_guidance_to_stockpile_data()
        if self.haul_cycle_file_path_choice:
            if not self.refresh_haul_cycle_routes(show_errors=True):
                self.validate_form()
                return
        else:
            self.haul_cycle_routes = {}
            self.destination_haul_routes = {}
            self.apply_haul_cycle_routes_to_stockpile_data()

        # Changing a planned tipping-point on Guidance can cause the live table
        # refresh above to seed an all-false default before 2WP brands have been
        # applied.  Guidance submission is the authoritative point at which
        # both inputs are available, so discard those provisional checkbox
        # values and derive the defaults again.  Any manual edits happen on the
        # Stockpile Inventories step after this point.
        self.stockpile_data_use_column = {}
        self.stockpile_data_AMT_column = {}

        # Rebuild only after guidance has been applied.  With no prior user
        # choices this derives the default Use selection from both 2WP brand
        # guidance and the nearest planned tipping-point crusher.
        self.setup_stockpile_table()
        self.save_active_scenario_state()
        self.set_page_enabled(self.stockpile_tab_index, True)
        self.show_page(self.stockpile_tab_index, force=True)
        self.validate_form()

    def handle_site_config_error(self, error_message):
        self.submit_button.setEnabled(True)
        if getattr(self, "project_load_waiting_for_inventory", False):
            self.project_load_waiting_for_inventory = False
            self.project_load_restore_in_progress = False
            self.finish_project_load_ui(success=False)
        if getattr(self, "agent_workflow_after_site_config", False):
            self.agent_workflow_after_site_config = False
            self.stop_agent_workflow_apply(f"Agent workflow stopped on Site Configuration fetch: {error_message}")
        self.show_error_popup(error_message)

