    def apply_agent_selected_stockpiles(self, value):
        if not hasattr(self, "stockpile_table"):
            return False
        use_names = []
        amt_names = None
        if isinstance(value, dict):
            use_names = value.get("use") or value.get("selected") or value.get("stockpiles") or []
            amt_names = value.get("amt")
        elif isinstance(value, (list, tuple, set)):
            use_names = value
        else:
            use_names = [value]

        use_set = {str(name).strip().upper() for name in use_names if str(name).strip()}
        amt_set = {str(name).strip().upper() for name in (amt_names or []) if str(name).strip()} if amt_names is not None else None
        if not use_set and amt_set:
            use_set = set(amt_set)
        if not use_set:
            return False

        matched_any = False
        for row in range(self.stockpile_table.rowCount()):
            stockpile_item = self.stockpile_table.item(row, 2)
            if not stockpile_item:
                continue
            stockpile_name = stockpile_item.text().strip()
            stockpile_key = stockpile_name.upper()
            use_checked = stockpile_key in use_set
            matched_any = matched_any or use_checked or (amt_set is not None and stockpile_key in amt_set)
            self.set_stockpile_checkbox(row, 0, use_checked)
            self.stockpile_data_use_column[stockpile_name] = use_checked
            if amt_set is not None:
                amt_checked = stockpile_key in amt_set
                self.set_stockpile_checkbox(row, 1, amt_checked)
                self.stockpile_data_AMT_column[stockpile_name] = amt_checked
        return matched_any

    def set_stockpile_checkbox(self, row, column, checked):
        checkbox_widget = self.stockpile_table.cellWidget(row, column)
        if not checkbox_widget or not checkbox_widget.layout() or checkbox_widget.layout().count() == 0:
            return
        checkbox = checkbox_widget.layout().itemAt(0).widget()
        if isinstance(checkbox, QCheckBox):
            checkbox.setChecked(bool(checked))

    def apply_agent_calendar_target(self, target, value):
        parsed = self.parse_agent_calendar_target(target)
        if not parsed or not hasattr(self, "main_table"):
            return False
        row_key, period = parsed
        row_idx = self.find_calendar_row_by_key(row_key)
        col_idx = self.find_calendar_column_by_period(period)
        if row_idx is None or col_idx is None:
            return False

        widget = self.main_table.cellWidget(row_idx, col_idx)
        if isinstance(widget, QComboBox):
            text = str(value)
            if widget.findText(text) == -1:
                widget.addItem(text)
            widget.setCurrentText(text)
            return True

        item = self.main_table.item(row_idx, col_idx)
        if item is None:
            item = QTableWidgetItem()
            item.setTextAlignment(Qt.AlignCenter)
            self.main_table.setItem(row_idx, col_idx, item)
        item.setText("" if value is None else str(value))
        return True

    def apply_agent_amt_chunking_target(self, target, value):
        parts = str(target).split(".")
        if len(parts) < 3 or not hasattr(self, "AMT_stockpile_table"):
            return False
        stockpile, field = parts[1], parts[2]
        caption = {
            "average_reclaim_rate_tph": "Average Reclaim Rate (t/h)",
            "chunk_reclaim_hours": "Target Hours per Chunk",
        }.get(field)
        field_column = (
            self.AMT_column_index(caption) if caption is not None else None
        )
        if field_column is None:
            return False
        for row in range(self.AMT_stockpile_table.rowCount()):
            stockpile_item = self.AMT_stockpile_table.item(row, 0)
            if not stockpile_item or stockpile_item.text().strip().upper() != stockpile.upper():
                continue
            item = self.AMT_stockpile_table.item(row, field_column)
            if item is None:
                item = QTableWidgetItem()
                item.setTextAlignment(Qt.AlignCenter)
                self.AMT_stockpile_table.setItem(row, field_column, item)
            item.setText("" if value is None else str(value))
            self.AMT_chunk_settings[stockpile_item.text()] = (
                self.update_AMT_chunk_plan_cells(row)
            )
            return True
        return False
    
    def stockpile_inventory_headers(self):
        headers = [
            "Use",
            "AMT",
            "Stockpile Name",
            "2WP Brand",
            "Nearest Crusher",
            "Build",
            "Inventory Timestamp",
            "Balance (WMT)",
            "Grade Fe (%)",
            "Grade Si (%)",
            "Grade Al (%)",
            "Grade P (%)",
            "Grade Mn (%)",
        ]
        if self.is_total_feed_operating_crusher():
            headers.append("Max Reclaim Rate (t/h)")
        headers.append("Reclaim Threshold (WMT)")
        return headers

    def stockpile_table_column_index(self, caption):
        for column in range(self.stockpile_table.columnCount()):
            header_item = self.stockpile_table.horizontalHeaderItem(column)
            if header_item and header_item.text() == caption:
                return column
        return None

    @staticmethod
    def normalized_crusher_display_name(value):
        text = str(value or "").strip().upper()
        if "/" in text:
            text = text.rsplit("/", 1)[-1]
        return text

    def default_stockpile_use_for_active_crusher(self, stockpile_data):
        """Select stockpiles matching the planned crusher and brand guidance."""
        mapped_nodes = {
            self.normalized_crusher_display_name(value)
            for value in self.current_haul_cycle_crusher_node()
            if self.normalized_crusher_display_name(value)
        }
        if not mapped_nodes:
            return {
                stockpile_name: False
                for stockpile_name in (stockpile_data or {})
            }
        return {
            stockpile_name: (
                self.normalized_crusher_display_name(
                    attributes.get(
                        "nearest_crusher",
                        attributes.get("NEAREST_CRUSHER", ""),
                    )
                )
                in mapped_nodes
                and bool(
                    attributes.get("aps_brand")
                    or attributes.get("APS_BRAND")
                    or attributes.get("aps_brand_proportions")
                    or attributes.get("APS_BRAND_PROPORTIONS")
                    or attributes.get("aps_brand_summary")
                    or attributes.get("APS_BRAND_SUMMARY")
                )
            )
            for stockpile_name, attributes in (stockpile_data or {}).items()
        }

    def apply_default_stockpile_preselection(self, stockpile_data):
        """Seed both inventory checkbox columns once from schedule guidance."""
        if self.stockpile_data_use_column or self.stockpile_data_AMT_column:
            return None
        defaults = self.default_stockpile_use_for_active_crusher(
            stockpile_data
        )
        if defaults is None:
            return None
        self.stockpile_data_use_column.update(defaults)
        # AMT is the default representation for every guided match.  Its Use
        # checkbox must be selected as well, hence the identical dictionaries.
        self.stockpile_data_AMT_column.update(defaults)
        return defaults

    def setup_stockpile_table(self):
        """Setup for the stockpile table in the new Stockpiles tab with live conditional formatting."""
        sort_header = self.stockpile_table.horizontalHeader()
        previous_sorting_enabled = self.stockpile_table.isSortingEnabled()
        previous_sort_column = sort_header.sortIndicatorSection()
        previous_sort_order = sort_header.sortIndicatorOrder()
        # Sorting while adding rows causes Qt to move partially populated rows.
        # Disable it for construction, then restore interactive header sorting.
        self.stockpile_table.setSortingEnabled(False)
        headers = self.stockpile_inventory_headers()
        self.stockpile_table.setColumnCount(len(headers))
        self.stockpile_table.setHorizontalHeaderLabels(headers)
        self.stockpile_table.verticalHeader().setVisible(False)
        sort_header.setSectionsClickable(True)
        sort_header.setSortIndicatorShown(True)

        # Bold headers
        header_font = self.stockpile_table.horizontalHeader().font()
        header_font.setBold(True)
        self.stockpile_table.horizontalHeader().setFont(header_font)

        # Choose data source
        data_source = self.stockpile_data
        self.apply_aps_brand_guidance_to_stockpile_data()

        # Set Table Dimensions
        self.stockpile_table.setRowCount(len(self.stockpile_data))

        default_use_by_stockpile = None
        has_saved_selection = bool(
            self.stockpile_data_use_column
            or self.stockpile_data_AMT_column
        )
        if not has_saved_selection:
            default_use_by_stockpile = (
                self.apply_default_stockpile_preselection(data_source)
            )

        # Populate Stockpile Data
        for row_idx, (stockpile_name, attributes) in enumerate(data_source.items()):
           
            # "Use" Column (Checkbox)
            use_checkbox = QCheckBox()

            AMT_checkbox = QCheckBox()

            
            if has_saved_selection or default_use_by_stockpile is not None:
                # Set the checkbox state based on the value in self.stockpile_data_use_column
                use_checkbox.setChecked(self.stockpile_data_use_column.get(stockpile_name, False))
                AMT_checkbox.setChecked(self.stockpile_data_AMT_column.get(stockpile_name, False))  # Default to checked if not found

            else:
                use_checkbox.setChecked(
                    default_use_by_stockpile.get(stockpile_name, True)
                    if default_use_by_stockpile is not None
                    else True
                )
                AMT_checkbox.setChecked(False)

            # AMT is a representation of a selected stockpile, not a second
            # independent source.  Keep the two controls consistent so an AMT
            # selection cannot be silently ignored because Use remained clear.
            if AMT_checkbox.isChecked():
                use_checkbox.setChecked(True)
            AMT_checkbox.toggled.connect(
                lambda checked, use=use_checkbox: (
                    use.setChecked(True) if checked else None
                )
            )
            use_checkbox.toggled.connect(
                lambda checked, amt=AMT_checkbox: (
                    amt.setChecked(False) if not checked else None
                )
            )

            # Center the checkbox using a QWidget and layout
            checkbox_widget = QWidget()
            layout = QHBoxLayout(checkbox_widget)
            layout.addWidget(use_checkbox)
            layout.setAlignment(Qt.AlignCenter)  # Center the checkbox
            layout.setContentsMargins(0, 0, 0, 0)  # Remove any extra padding
            self.stockpile_table.setCellWidget(row_idx, 0, checkbox_widget)

            # Center the checkbox using a QWidget and layout (AMT)
            AMT_checkbox_widget = QWidget()
            AMT_layout = QHBoxLayout(AMT_checkbox_widget)
            AMT_layout.addWidget(AMT_checkbox)
            AMT_layout.setAlignment(Qt.AlignCenter)  # Center the checkbox
            AMT_layout.setContentsMargins(0, 0, 0, 0)  # Remove any extra padding
            self.stockpile_table.setCellWidget(row_idx, 1, AMT_checkbox_widget)

            # Stockpile Name (Center-align)
            stockpile_item = QTableWidgetItem(str(stockpile_name))
            stockpile_item.setFlags(Qt.ItemIsEnabled)  # Non-editable
            stockpile_item.setTextAlignment(Qt.AlignCenter)  # Center-align the stockpile name
            self.stockpile_table.setItem(row_idx, 2, stockpile_item)

            brand_item = QTableWidgetItem(str(attributes.get("aps_brand_summary", "")))
            brand_item.setFlags(Qt.ItemIsEnabled)
            brand_item.setTextAlignment(Qt.AlignCenter)
            self.stockpile_table.setItem(row_idx, 3, brand_item)

            nearest_crusher = str(
                attributes.get(
                    "nearest_crusher",
                    attributes.get("NEAREST_CRUSHER", ""),
                )
                or ""
            )
            nearest_crusher_item = QTableWidgetItem(nearest_crusher)
            nearest_crusher_item.setFlags(Qt.ItemIsEnabled)
            nearest_crusher_item.setTextAlignment(Qt.AlignCenter)
            cycle_minutes = attributes.get(
                "rehandle_cycle_time_minutes",
                attributes.get("REHANDLE_CYCLE_TIME_MINUTES"),
            )
            if cycle_minutes not in (None, ""):
                try:
                    cycle_tooltip = (
                        f"Shortest selected haul cycle: "
                        f"{float(cycle_minutes):g} min"
                    )
                except (TypeError, ValueError):
                    cycle_tooltip = "Shortest selected haul cycle unavailable"
                nearest_crusher_item.setToolTip(cycle_tooltip)
            self.stockpile_table.setItem(
                row_idx,
                headers.index("Nearest Crusher"),
                nearest_crusher_item,
            )

            # Attributes (Balance and Grades, Center-aligned)
            keys = [
                "BUILD", "TRANSACTION_DATETIME", "BALANCE", "GRADE_FE",
                "GRADE_SI", "GRADE_AL", "GRADE_P", "GRADE_MN",
            ]
       
            for col_idx, key in enumerate(
                keys,
                start=headers.index("Build"),
            ):

                value = attributes.get(key, attributes.get(key.lower()))
                if value is None:
                    # Older project snapshots do not have every field added by
                    # later inventory queries.  Keep them loadable and render a
                    # neutral value instead of opening one modal per stockpile.
                    value = "" if key in {"BUILD", "TRANSACTION_DATETIME"} else 0

                if key == "BALANCE" or key == 'balance':
                    # Round balance and apply conditional formatting
                    value = float(value) if value else 0.0
                    balance_item = NumericSortTableWidgetItem(f"{value:,.0f}")
                    balance_item.setData(Qt.UserRole, value)
                    balance_item.setFlags(Qt.ItemIsEnabled)  # Non-editable
                    balance_item.setTextAlignment(Qt.AlignCenter)  # Center-align value
                    if value < 0:
                        balance_item.setForeground(QColor("red"))
                        font = balance_item.font()
                        font.setBold(True)
                        balance_item.setFont(font)
                    self.stockpile_table.setItem(row_idx, col_idx, balance_item)

                elif key == "BUILD" or key == 'build':
                    build_item = QTableWidgetItem(value)
                    build_item.setFlags(Qt.ItemIsEnabled)  # Non-editable
                    build_item.setTextAlignment(Qt.AlignCenter)  # Center-align value
                    self.stockpile_table.setItem(row_idx, col_idx, build_item)

                elif key == "TRANSACTION_DATETIME" or key == "transaction_datetime":
                    timestamp_item = QTableWidgetItem(str(value or ""))
                    timestamp_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                    timestamp_item.setTextAlignment(Qt.AlignCenter)
                    self.stockpile_table.setItem(row_idx, col_idx, timestamp_item)
                
                else:
                    # Round grade values to 2 decimal points
                    value = round(float(value), 2) if value else 0
                    grade_item = NumericSortTableWidgetItem(f"{value:.2f}")
                    grade_item.setData(Qt.UserRole, value)
                    grade_item.setFlags(Qt.ItemIsEnabled)  # Non-editable
                    grade_item.setTextAlignment(Qt.AlignCenter)  # Center-align value
                    self.stockpile_table.setItem(row_idx, col_idx, grade_item)

            if self.is_total_feed_operating_crusher():
                max_reclaim_rate = attributes.get(
                    "max_reclaim_rate",
                    attributes.get("MAX_RECLAIM_RATE", 1000),
                )
                try:
                    max_reclaim_rate = float(max_reclaim_rate)
                except (TypeError, ValueError):
                    max_reclaim_rate = 1000.0
                max_rate_item = NumericSortTableWidgetItem(f"{max_reclaim_rate:g}")
                max_rate_item.setData(Qt.UserRole, max_reclaim_rate)
                max_rate_item.setTextAlignment(Qt.AlignCenter)
                self.stockpile_table.setItem(
                    row_idx,
                    headers.index("Max Reclaim Rate (t/h)"),
                    max_rate_item,
                )

            # Reclaim Threshold (Editable, Center-aligned)
            reclaim_value = attributes.get("reclaim_threshold", 0)
            reclaim_value = float(reclaim_value)
            reclaim_item = NumericSortTableWidgetItem(f"{reclaim_value:,.0f}")
            reclaim_item.setData(Qt.UserRole, reclaim_value)
            reclaim_item.setTextAlignment(Qt.AlignCenter)
            self.stockpile_table.setItem(
                row_idx,
                headers.index("Reclaim Threshold (WMT)"),
                reclaim_item,
            )

        # Resize Columns
        for column, header in enumerate(headers):
            resize_mode = (
                QHeaderView.Stretch
                if header.startswith("Grade ")
                else QHeaderView.ResizeToContents
            )
            self.stockpile_table.horizontalHeader().setSectionResizeMode(
                column, resize_mode
            )

        self.stockpile_table.setSortingEnabled(True)
        if previous_sorting_enabled and 0 <= previous_sort_column < len(headers):
            self.stockpile_table.sortItems(previous_sort_column, previous_sort_order)

        if self.setup_stockpile_table_first_call:
            # Connect cellChanged signal to a slot for live formatting
            self.stockpile_table.cellChanged.connect(self.handle_cell_change)

            # Add Submit Button at the Bottom
            submit_button = QPushButton("Submit")
            submit_button.clicked.connect(self.store_stockpile_table)

            # Align button to the bottom-left using layout
            button_layout = QHBoxLayout()
            
            # Don't add the button if returning from the calendar
            if self.submit_calendar_first_call:
                select_all_use_button = QPushButton("Select All Stockpiles")
                select_all_use_button.clicked.connect(lambda: self.set_all_stockpile_checkboxes(0, True))

                clear_use_button = QPushButton("Clear All Stockpiles")
                clear_use_button.clicked.connect(lambda: self.set_all_stockpile_checkboxes(0, False))

                select_all_AMT_button = QPushButton("Select All Stockpiles as AMT")
                select_all_AMT_button.clicked.connect(lambda: self.set_all_stockpile_checkboxes(1, True))

                clear_AMT_button = QPushButton("Clear All Stockpiles as AMT")
                clear_AMT_button.clicked.connect(lambda: self.set_all_stockpile_checkboxes(1, False))

                button_layout.addWidget(select_all_use_button)
                button_layout.addWidget(clear_use_button)
                button_layout.addWidget(select_all_AMT_button)
                button_layout.addWidget(clear_AMT_button)
                button_layout.addWidget(submit_button)  
                button_layout.addStretch()  # Push the button to the left

            self.stockpile_tab_layout.addLayout(button_layout)
            
            self.setup_stockpile_table_first_call = False

    def set_all_stockpile_checkboxes(self, column, checked):
        """Set all checkbox widgets in a Stockpile Inventories checkbox column."""
        state_by_column = {
            0: self.stockpile_data_use_column,
            1: self.stockpile_data_AMT_column
        }

        for row in range(self.stockpile_table.rowCount()):
            checkbox_widget = self.stockpile_table.cellWidget(row, column)
            stockpile_item = self.stockpile_table.item(row, 2)

            if not checkbox_widget or not stockpile_item:
                continue

            checkbox = checkbox_widget.layout().itemAt(0).widget()
            checkbox.setChecked(checked)
            state_by_column[column][stockpile_item.text()] = checked

    def handle_cell_change(self, row, column):
        """Handle validation formatting for editable inventory properties."""
        headers = self.stockpile_inventory_headers()

        if (
            "Max Reclaim Rate (t/h)" in headers
            and column == headers.index("Max Reclaim Rate (t/h)")
        ):
            rate_item = self.stockpile_table.item(row, column)
            if rate_item is None:
                return
            try:
                rate_value = float(rate_item.text())
                valid_rate = rate_value > 0
            except (AttributeError, TypeError, ValueError):
                valid_rate = False
            else:
                rate_item.setData(Qt.UserRole, rate_value)
            rate_item.setForeground(QColor("green" if valid_rate else "red"))
            return

        if column == headers.index("Reclaim Threshold (WMT)"):  # Check if the changed cell is in the Reclaim Threshold column
            reclaim_item = self.stockpile_table.item(row, column)
            balance_item = self.stockpile_table.item(row, headers.index("Balance (WMT)"))

            if reclaim_item and balance_item:
                try:
                    reclaim_value = self.parse_formatted_number(
                        reclaim_item.text()
                    )
                    balance_value = self.parse_formatted_number(
                        balance_item.text()
                    )
                    if reclaim_value is None or balance_value is None:
                        raise ValueError("Invalid formatted tonnage")

                    reclaim_item.setData(Qt.UserRole, reclaim_value)
                    # Apply conditional formatting
                    if reclaim_value <= balance_value:
                        reclaim_item.setForeground(QColor("green"))
                    else:
                        reclaim_item.setForeground(QColor("red"))
                except ValueError:
                    # Ignore invalid inputs
                    reclaim_item.setForeground(QColor("black"))

    def store_stockpile_table(self):
        """Store stockpile details entered by the user, filtering by the 'Use' column."""
        
        updated_stockpile_data = {}
        max_rate_column = self.stockpile_table_column_index(
            "Max Reclaim Rate (t/h)"
        )
        reclaim_threshold_column = self.stockpile_table_column_index(
            "Reclaim Threshold (WMT)"
        )

        if max_rate_column is not None:
            for row in range(self.stockpile_table.rowCount()):
                stockpile_item = self.stockpile_table.item(row, 2)
                max_rate_item = self.stockpile_table.item(row, max_rate_column)
                stockpile_name = stockpile_item.text() if stockpile_item else ""
                try:
                    max_reclaim_rate = float(max_rate_item.text())
                except (AttributeError, TypeError, ValueError):
                    max_reclaim_rate = 0.0
                if max_reclaim_rate <= 0:
                    QMessageBox.warning(
                        self,
                        "Invalid Input",
                        f"Max Reclaim Rate must be greater than 0 t/h for "
                        f"{stockpile_name or 'each stockpile'}.",
                    )
                    return
                if stockpile_name in self.stockpile_data:
                    self.stockpile_data[stockpile_name][
                        "max_reclaim_rate"
                    ] = max_reclaim_rate

        for row in range(self.stockpile_table.rowCount()):
            # Check if "Use" column checkbox is checked
            checkbox_widget = self.stockpile_table.cellWidget(row, 0)  # Get the widget in the "Use" column
            AMT_checkbox_widget = self.stockpile_table.cellWidget(row, 1)  # Get the widget in the "AMT" column

            if checkbox_widget:
                checkbox = checkbox_widget.layout().itemAt(0).widget()  # Extract the QCheckBox
                
                if checkbox.isChecked():
                    # Get the stockpile name from the relevant column (assuming column 2 for name)
                    stockpile_name = self.stockpile_table.item(row, 2).text()
                    # Store the stockpile name and its "Use" status (True for checked, False otherwise)
                    self.stockpile_data_use_column[stockpile_name] = True
                    
                    if AMT_checkbox_widget:
                        AMT_checkbox = AMT_checkbox_widget.layout().itemAt(0).widget()  # Extract the AMT QCheckBox

                        if AMT_checkbox.isChecked():
                            # Store the stockpile name and its "AMT" status (True for checked, False otherwise)
                            self.stockpile_data_AMT_column[stockpile_name] = True

                        else:
                            self.stockpile_data_AMT_column[stockpile_name] = False

                    # Retrieve Reclaim Threshold
                    reclaim_item = self.stockpile_table.item(
                        row, reclaim_threshold_column
                    )
                    reclaim_threshold = (
                        self.parse_formatted_number(reclaim_item.text(), 0.0)
                        if reclaim_item else 0.0
                    )

                    # Update stockpile data
                    updated_stockpile_data[stockpile_name] = self.stockpile_data.get(stockpile_name, {})
                    updated_stockpile_data[stockpile_name]["reclaim_threshold"] = reclaim_threshold
                    if max_rate_column is not None:
                        updated_stockpile_data[stockpile_name][
                            "max_reclaim_rate"
                        ] = float(
                            self.stockpile_table.item(
                                row, max_rate_column
                            ).text()
                        )
                    updated_stockpile_data[stockpile_name]["AMT"] = self.stockpile_data_AMT_column[stockpile_name]

                else:
                    # Optional: Store unchecked stockpiles
                    stockpile_name = self.stockpile_table.item(row, 2).text()
                    self.stockpile_data_use_column[stockpile_name] = False
                    # "Use" owns source participation.  The checkbox signal
                    # clears AMT visually, but keep the persisted selection in
                    # sync as well so this footprint cannot reappear later.
                    self.stockpile_data_AMT_column[stockpile_name] = False

                
        # Update stockpile_data with filtered data
        self.updated_stockpile_data = updated_stockpile_data
        self.updated_stockpile_data_keys = updated_stockpile_data.keys()

        self.updated_stockpile_data = {
            key.upper(): {
                nested_key.lower(): (nested_value.lower() if nested_key.lower() == "name" and isinstance(nested_value, str) else nested_value)
                for nested_key, nested_value in value.items()
            }
            for key, value in self.updated_stockpile_data.items()
        }
        selected_amt_footprints = {
            str(stockpile_name).strip().upper()
            for stockpile_name, attributes in self.updated_stockpile_data.items()
            if isinstance(attributes, dict) and attributes.get("amt", False)
        }
        self.prune_unselected_amt_state(selected_amt_footprints)

        # Route completeness belongs to Stockpile Inventories: this is where
        # the selected stockpile footprint is defined. Do not re-raise this
        # setup warning when a user only resubmits Solver Configuration or
        # Decision Levers after an optimisation run.
        if (
            hasattr(self, "rehandle_cycle_time_penalty_checkbox")
            and self.rehandle_cycle_time_penalty_checkbox.isChecked()
        ):
            missing_routes = [
                stockpile
                for stockpile, attributes in self.updated_stockpile_data.items()
                if not attributes.get("rehandle_cycle_time_minutes")
            ]
            if missing_routes:
                QMessageBox.warning(
                    self,
                    "Missing Haul Cycles",
                    "No selected-crusher haul cycle was found for: "
                    + ", ".join(sorted(missing_routes)),
                )
                return

        if self.updated_stockpile_data:
            # Guidance is complete and the selected opening source set is now
            # authoritative.  Reset stale downstream results and persist the
            # inventory once here; Data Streams only adds reconciliation and
            # must not rewrite this table.
            if not getattr(self, "project_load_restore_in_progress", False):
                DatabaseManager.clear_all_tables(get_database_path())
                self.opening_stockpile_inventories.save_to_database(
                    self.included_AMT_snapshot(self.stockpile_data)
                )
            self.save_active_scenario_state()
            self.setup_calendar()
            # Fetch AMT raw fields now so they are available on Map Fields;
            # chunk generation remains after Data Streams has applied the
            # selected mappings and historical reconciliation.
            self.setup_AMT_stockpile_table()
            self.populate_define_fields_table()
            self.set_page_enabled(self.define_fields_tab_index, True)
            self.show_page(self.define_fields_tab_index, force=True)
        else:
            QMessageBox.information(self, "BlendMaster", "No stockpiles selected!\nPlease select stockpiles to proceed.")

    def prune_unselected_amt_state(self, selected_footprints):
        """Remove generated AMT state for footprints no longer selected."""
        selected = {
            str(footprint).strip().upper()
            for footprint in (selected_footprints or set())
            if str(footprint).strip()
        }
        self.AMT_footprint_exclusions = {
            name: record for name, record in normalize_amt_exclusions(vars(self).get("AMT_footprint_exclusions")).items()
            if name in selected
        }
        selected -= self.excluded_amt_footprints()

        def record_footprint(record):
            if not isinstance(record, dict):
                return ""
            return str(
                record.get("footprint")
                or record.get("FOOTPRINT")
                or record.get("parent_stockpile")
                or record.get("PARENT_STOCKPILE")
                or ""
            ).strip().upper()

        def retained_records(records):
            return [
                record for record in (records or [])
                if record_footprint(record) in selected
            ]

        self.hex_sequence_table = retained_records(
            getattr(self, "hex_sequence_table", [])
        )
        self.hex_sequence_table_argument = retained_records(
            getattr(self, "hex_sequence_table_argument", [])
        )
        self.AMT_chunk_settings = {
            key: value
            for key, value in (
                getattr(self, "AMT_chunk_settings", {}) or {}
            ).items()
            if str(key).strip().upper() in selected
        }
        self.AMT_stockpile_data = {
            key: value
            for key, value in (
                getattr(self, "AMT_stockpile_data", {}) or {}
            ).items()
            if str(key).strip().upper() in selected
        }

        draw_amt = vars(self).get("draw_AMT_map")
        if draw_amt is not None:
            draw_amt.selected_points = copy.deepcopy(
                self.hex_sequence_table
            )
            draw_amt.update_chunk_settings(
                copy.deepcopy(self.AMT_chunk_settings)
            )
            if hasattr(draw_amt, "clean_up_hex_sequence_table"):
                draw_amt.clean_up_hex_sequence_table()
            if hasattr(draw_amt, "update_sequence_counter"):
                draw_amt.update_sequence_counter()

        self.total_AMT_stockpile_balances = {}
        self.database_view_rows = []
        self.database_view_snapshot_signature = None
        self.database_view_refresh_pending = True
        self.AMT_chunk_reconciliation_signature = ""

    def set_default_manual_schedule_periods(self):
        if self.default_start_datetime and self.default_end_datetime:
            return

        periods = PeriodManager(self.planning_period_count())
        periods.calculate_periods(self.start_time_choice or datetime.now())
        self.set_start_and_end_datetime(periods)

    def activate_manual_setup_tab(self):
        self.set_default_manual_schedule_periods()
        self.setup_blends_tab()
        self.set_page_enabled(self.blend_config_tab_index, True)

    def fetch_optimised_blend_report(self, plan_id=None):
        plan_id = plan_id or (
            getattr(self, "manual_plan_selector", None).currentText()
            if getattr(self, "manual_plan_selector", None) is not None
            else self.selected_optimisation_plan_id()
        )
        plan_id = str(plan_id or "Primary")
        connection = sqlite3.connect(get_database_path())
        try:
            table_exists = connection.execute(
                """
                SELECT 1 FROM sqlite_master
                WHERE type = 'table'
                  AND name = 'optimisation_plan_blend_report'
                """
            ).fetchone()
            if table_exists:
                columns = [
                    row[1]
                    for row in connection.execute(
                        "PRAGMA table_info(optimisation_plan_blend_report)"
                    ).fetchall()
                ]
                if "plan_id" in columns:
                    order_columns = [
                        column
                        for column in ("steady_state_number", "source")
                        if column in columns
                    ]
                    order_clause = (
                        " ORDER BY " + ", ".join(order_columns)
                        if order_columns
                        else ""
                    )
                    report = pd.read_sql(
                        "SELECT * FROM optimisation_plan_blend_report "
                        "WHERE plan_id = ?" + order_clause,
                        connection,
                        params=(plan_id,),
                    ).drop(columns=["plan_id", "plan_rank"], errors="ignore")
                    if not report.empty or plan_id != "Primary":
                        return report
            if plan_id != "Primary":
                return pd.DataFrame()
            return pd.read_sql(
                "SELECT * FROM optimised_blend_report",
                connection,
            )
        except (sqlite3.Error, pd.errors.DatabaseError):
            return pd.DataFrame()
        finally:
            connection.close()

    MANUAL_PLAN_STATE_FIELDS = (
        "blend_config_table_inputs",
        "saved_blends_for_schedule",
        "stored_blend_sequence_table_for_gantt",
        "stored_blend_sequence_table_for_gantt_default",
        "manual_direct_tip_allocations",
        "manual_steady_states",
        "manual_blend_report",
        "manual_physical_balance_history",
        "crusher_rate",
        "crusher_rate_input_value",
        "crusher_rate_input_values",
    )

    def capture_active_manual_plan_state(self):
        if not hasattr(self, "manual_plan_states"):
            self.manual_plan_states = {}
        plan_id = str(
            getattr(self, "active_manual_plan_id", "Primary")
            or "Primary"
        )
        self.manual_plan_states[plan_id] = {
            field: copy.deepcopy(getattr(self, field, None))
            for field in self.MANUAL_PLAN_STATE_FIELDS
        }

    def handle_manual_plan_selection(self):
        selector = getattr(self, "manual_plan_selector", None)
        if selector is None or not selector.currentText().strip():
            return
        previous_plan = str(
            getattr(self, "active_manual_plan_id", "Primary")
            or "Primary"
        )
        selected_plan = selector.currentText().strip()
        if previous_plan == selected_plan:
            return
        self.capture_active_manual_plan_state()
        self.active_manual_plan_id = selected_plan
        saved = copy.deepcopy(
            (getattr(self, "manual_plan_states", {}) or {}).get(
                selected_plan
            )
        )
        if saved:
            for field in self.MANUAL_PLAN_STATE_FIELDS:
                setattr(self, field, saved.get(field))
        else:
            self.reset_manual_blending_plan_state()
        if hasattr(self, "blend_config_table"):
            self.populate_blend_config_table()
            self.populate_blend_config_weights_and_ids()
            self.update_blend_results()
        if hasattr(self, "blend_sequence_table"):
            self.populate_blend_sequence_table_if_project_is_loaded()

    def active_manual_plan_rank(self):
        plan_id = str(
            getattr(self, "active_manual_plan_id", "Primary")
        )
        if plan_id == "Primary":
            return 0
        try:
            return int(plan_id.rsplit(" ", 1)[-1])
        except (TypeError, ValueError):
            return 0

    def write_active_manual_plan_reports(self, report):
        manager = DatabaseManager()
        manager.write_manual_blend_report_to_database(report)
        manager.write_optimisation_plan_result(
            "manual",
            report,
            getattr(self, "active_manual_plan_id", "Primary"),
            self.active_manual_plan_rank(),
        )
        self.write_manual_material_destination_plan(report)
        self.capture_active_manual_plan_state()

    def write_manual_closing_rom_stocks_compliance(self, report):
        targets = ClosingROMStocksCompliance.normalize_target_rows(
            getattr(self, "two_wp_closing_stock_balances", None)
        )
        history = getattr(self, "manual_physical_balance_history", []) or []
        if targets.empty or not history:
            return
        periods = PeriodManager(self.planning_period_count())
        periods.calculate_periods(
            getattr(self, "start_time_choice", None) or datetime.now()
        )
        base_plan_id = str(
            getattr(self, "active_manual_plan_id", "Primary") or "Primary"
        )
        plan_id = f"Manual - {base_plan_id}"
        compliance = ClosingROMStocksCompliance.build_report(
            plan_id=plan_id,
            plan_type="manual",
            periods=periods.get_periods(),
            physical_balance_history=history,
            target_rows=targets,
            used_stockpiles=Run._closing_compliance_stockpiles(
                self.active_site_context(), report, None
            ),
        )
        DatabaseManager().write_closing_rom_stocks_compliance(
            compliance, plan_id, "manual"
        )

    def reset_manual_blending_plan_state(self):
        self.blend_config_table_inputs = {}
        self.blend_data_from_config_table_inputs = {}
        self.saved_blends_for_schedule = []
        self.stored_blend_sequence_table_for_gantt = []
        self.stored_blend_sequence_table_for_gantt_default = []
        self.manual_direct_tip_allocations = {}
        self.manual_steady_states = []
        self.manual_blend_report = pd.DataFrame(
            columns=ManualBlendPlanner.REPORT_COLUMNS
        )
        self.manual_physical_balance_history = []
        self.manual_gantt_legend_and_tooltip = []

    def clear_manual_blending_plan(self):
        has_manual_data = bool(
            getattr(self, "saved_blends_for_schedule", [])
            or getattr(
                self, "stored_blend_sequence_table_for_gantt", []
            )
            or getattr(self, "manual_direct_tip_allocations", {})
            or (
                isinstance(
                    getattr(self, "manual_blend_report", None),
                    pd.DataFrame,
                )
                and not self.manual_blend_report.empty
            )
        )
        if has_manual_data:
            reply = QMessageBox.question(
                self,
                "Clear Manual Blending Session?",
                "Clear Setup Blends, Blend Sequence, direct-tip "
                "selections, manual steady states, and the manual report?\n\n"
                "Stockpile Inventories, Calendar settings, guidance "
                "schedules, and optimized results will be retained.",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if reply != QMessageBox.Yes:
                return False

        self.reset_manual_blending_plan_state()
        self.set_manual_crusher_rate_inputs(
            self.calendar_crusher_rate_values()
        )
        self.write_active_manual_plan_reports(
            self.manual_blend_report
        )

        if hasattr(self, "blend_config_table"):
            self._manual_blend_reset_in_progress = True
            was_blocked = self.blend_config_table.blockSignals(True)
            try:
                self.populate_blend_config_table()
                self.populate_blend_config_weights_and_ids()
                self.update_blend_results()
            finally:
                self.blend_config_table.blockSignals(was_blocked)
                self._manual_blend_reset_in_progress = False
            # The UI calculation builds empty placeholder entries for the
            # default Blend IDs. They are not configured manual blends.
            self.blend_config_table_inputs = {}
            self.blend_data_from_config_table_inputs = {}

        if hasattr(self, "blend_results_table_view"):
            self.blend_results_table_view.clearContents()
            self.blend_results_table_view.setRowCount(0)
            self.blend_results_table_view.setColumnCount(0)
        if hasattr(self, "blend_sequence_table"):
            self.blend_sequence_table.clearContents()
            self.blend_sequence_table.setRowCount(0)
        if hasattr(self, "manual_steady_state_button"):
            self.manual_steady_state_button.setEnabled(False)

        manual_chart = getattr(
            self, "draw_manual_gantt_chart", None
        )
        if manual_chart is not None:
            manual_chart.update_data([], [])
        if hasattr(self, "manual_gantt_view"):
            self.load_manual_gantt_chart()
            QTimer.singleShot(250, self.manual_gantt_view.reload)
        if hasattr(self, "draw_grade_profile_chart"):
            self.draw_grade_profile_chart.update_data(pd.DataFrame())

        self.set_page_enabled(self.blend_sequence_tab_index, False)
        self.set_page_enabled(self.grade_profile_tab_index, False)
        self.refresh_sqlite_reports()
        self.save_active_scenario_state()
        self.show_page(self.blend_config_tab_index)
        QMessageBox.information(
            self,
            "BlendMaster",
            "The manual blending session has been cleared. "
            "Setup Blends is ready for a fresh manual plan.",
        )
        return True

    def prepopulate_manual_from_optimised_result(
        self, automatic=False
    ):
        has_manual_plan = bool(
            getattr(
                self, "stored_blend_sequence_table_for_gantt", []
            )
            or getattr(self, "manual_direct_tip_allocations", {})
            or getattr(self, "saved_blends_for_schedule", [])
            or getattr(self, "blend_config_table_inputs", {})
        )
        if automatic and has_manual_plan:
            return False
        if not automatic and has_manual_plan:
            reply = QMessageBox.question(
                self,
                "Replace Manual Blend Plan?",
                "This will replace the current Setup Blends, Blend Sequence, "
                "and manual direct-tip selections with the latest optimized "
                "result. Continue?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if reply != QMessageBox.Yes:
                return False

        optimised_report = self.fetch_optimised_blend_report(
            getattr(self, "active_manual_plan_id", "Primary")
        )
        if optimised_report.empty:
            if not automatic:
                QMessageBox.information(
                    self,
                    "Prepopulate Manual Blending",
                    "Run the optimiser first. No optimized blend result is "
                    "available for this site scenario.",
                )
            return False

        previous_manual_state = {
            field: copy.deepcopy(getattr(self, field, None))
            for field in (
                "blend_config_table_inputs",
                "saved_blends_for_schedule",
                "stored_blend_sequence_table_for_gantt",
                "stored_blend_sequence_table_for_gantt_default",
                "manual_direct_tip_allocations",
                "manual_steady_states",
                "manual_blend_report",
                "crusher_rate",
                "crusher_rate_input_value",
                "crusher_rate_input_values",
            )
        }
        try:
            transfer = OptimisedToManualPlan(
                optimised_report,
                getattr(self, "updated_stockpile_data", {}),
            ).build()

            self.blend_config_table_inputs = copy.deepcopy(
                transfer["blend_config_table_inputs"]
            )
            transferred_rates = self.calendar_crusher_rate_values()
            transferred_rates.update({
                period: rate
                for period, rate in (
                    transfer.get("period_crusher_rates", {}) or {}
                ).items()
                if float(rate or 0) > 0
            })
            self.set_manual_crusher_rate_inputs(transferred_rates)
            self.saved_blends_for_schedule = copy.deepcopy(
                transfer["blend_definitions"]
            )
            imported_sequence = copy.deepcopy(
                transfer["sequence_rows"]
            )
            self.stored_blend_sequence_table_for_gantt = (
                imported_sequence
            )
            self.stored_blend_sequence_table_for_gantt_default = []
            self.manual_gantt_legend_and_tooltip = (
                self.saved_blends_for_schedule
            )

            planner = self.create_manual_blend_planner()
            states = planner.build_steady_states()
            allocations = OptimisedToManualPlan.direct_tip_allocations(
                states, transfer["direct_tip_rows"]
            )
            report = planner.build_report(states, allocations)
        except Exception as error:
            for field, value in previous_manual_state.items():
                setattr(self, field, value)
            if automatic:
                print(
                    "Manual prepopulation from optimized result was not "
                    f"completed: {error}"
                )
            else:
                QMessageBox.warning(
                    self,
                    "Prepopulate Manual Blending",
                    str(error),
                )
            return False

        self.manual_direct_tip_allocations = allocations
        self.manual_steady_states = states
        self.manual_blend_report = report
        self.manual_physical_balance_history = copy.deepcopy(
            getattr(planner, "physical_balance_history", [])
        )
        self.update_manual_gantt_blend_summaries(report)
        self.write_active_manual_plan_reports(report)
        self.write_manual_closing_rom_stocks_compliance(report)

        # Rebuild Setup Blends so every optimized source-to-ratio pattern is
        # visible, including plans containing more than five Blend IDs.
        if hasattr(self, "blend_config_table"):
            previous_project_loaded = self.is_project_loaded
            self.is_project_loaded = True
            try:
                self.populate_blend_config_table()
                self.populate_blend_config_weights_and_ids()
                self.update_blend_results()
            finally:
                self.is_project_loaded = previous_project_loaded

        previous_project_loaded = self.is_project_loaded
        self.is_project_loaded = True
        try:
            self.setup_sequence_tab()
            self.populate_blend_sequence_table_if_project_is_loaded()
            self.apply_manual_gantt_rows_to_table(imported_sequence)
        finally:
            self.is_project_loaded = previous_project_loaded

        # Table hydration contains user-facing columns only. Restore the
        # optimized-state metadata used to preserve exact decision boundaries
        # and per-state crusher rates.
        self.stored_blend_sequence_table_for_gantt = imported_sequence
        self.manual_gantt_legend_and_tooltip = (
            self.saved_blends_for_schedule
        )
        self.start_or_update_dash_manual_chart_thread()
        self.load_manual_gantt_chart()
        QTimer.singleShot(250, self.manual_gantt_view.reload)
        self.set_page_enabled(self.blend_sequence_tab_index, True)
        self.set_page_enabled(self.grade_profile_tab_index, True)
        self.refresh_sqlite_reports()
        self.save_active_scenario_state()

        if not automatic:
            QMessageBox.information(
                self,
                "BlendMaster",
                f"Manual blending was prepopulated from "
                f"{transfer['steady_state_count']} optimized steady "
                f"state(s) using {transfer['blend_count']} manual blend "
                f"definition(s).\n\n"
                f"Transferred selected direct tip: "
                f"{transfer['direct_tip_tonnes']:,.0f} t.",
            )
            self.show_page(self.blend_sequence_tab_index)
        return True

    def navigate_to_solver_configuration(self):
        self.load_solver_config_inputs()
        self.set_page_enabled(self.solver_config_tab_index, True)
        self.set_page_enabled(self.decision_levers_tab_index, True)
        self.show_page(self.solver_config_tab_index)

    def handle_solver_configuration_submit(self):
        if not self.store_solver_config_inputs():
            return
        self.save_active_scenario_state()
        self.navigate_to_product_targets()

    def parse_float_from_table_item(self, item, default=0.0):
        if not item or not item.text().strip():
            return default
        return self.parse_formatted_number(item.text(), default)

    @staticmethod
    def parse_formatted_number(value, default=None):
        """Parse a displayed number without letting grouping commas affect data."""
        try:
            return float(str(value).strip().replace(",", ""))
        except (TypeError, ValueError):
            return default

    def get_AMT_chunk_setting(self, stockpile_name):
        setting = copy.deepcopy(
            (self.AMT_chunk_settings or {}).get(stockpile_name) or {}
        )
        rate = numeric(setting.get("average_reclaim_rate"))
        hours = numeric(setting.get("chunk_reclaim_hours"))
        # Migrate the exact former 1,000 t/h x 1 h default while retaining
        # genuinely configured legacy values.
        legacy_default = (
            "chunk_count" not in setting
            and rate == 1000.0
            and hours == 1.0
            and numeric(setting.get("chunk_size")) == 1000.0
        )
        if rate is None or legacy_default:
            rate = DEFAULT_AMT_RECLAIM_RATE_TPH
        if hours is None or legacy_default:
            hours = DEFAULT_AMT_TARGET_CHUNK_HOURS
        setting["average_reclaim_rate"] = rate
        setting["chunk_reclaim_hours"] = hours
        return setting

    def calculate_AMT_chunk_plan(
        self, amt_total_wmt, average_reclaim_rate, chunk_reclaim_hours
    ):
        return calculate_amt_chunk_plan(
            amt_total_wmt,
            average_reclaim_rate,
            chunk_reclaim_hours,
        )

    def AMT_column_index(self, caption):
        return self.amt_stockpile_headers().index(caption)

    @staticmethod
    def AMT_row_numeric_value(row, *keys):
        row = row or {}
        for key in keys:
            value = numeric(row.get(key))
            if value is not None:
                return value
        return None

    def AMT_footprint_totals(self, stockpile_name, attributes=None):
        rows = (self.AMT_stockpile_data or {}).get(stockpile_name, []) or []
        amt_total_wmt = sum(
            max(
                self.AMT_row_numeric_value(
                    row, "FINAL_WMT", "final_wmt", "BALANCE", "balance"
                )
                or 0.0,
                0.0,
            )
            for row in rows
        )

        provenance = rows[0] if rows else {}
        matched_name = str(
            provenance.get("AMT_INVENTORY_STOCKPILE")
            or provenance.get("INTERNAL_RECON_INVENTORY_STOCKPILE")
            or provenance.get("internal_recon_inventory_stockpile")
            or stockpile_name
        ).strip()
        inventory_row = None
        normalized_match = matched_name.upper()
        for source in (
            getattr(self, "stockpile_data", {}) or {},
            getattr(self, "updated_stockpile_data", {}) or {},
        ):
            for name, candidate in source.items():
                if str(name).strip().upper() == normalized_match:
                    inventory_row = candidate or {}
                    break
            if inventory_row is not None:
                break
        if inventory_row is None:
            inventory_row = attributes or {}
        inventory_total_wmt = self.AMT_row_numeric_value(
            inventory_row, "BALANCE", "balance", "FINAL_WMT", "final_wmt"
        )
        return amt_total_wmt, inventory_total_wmt

    def AMT_raw_signed_footprint_total(self, stockpile_name):
        rows = (self.AMT_stockpile_data or {}).get(stockpile_name, []) or []
        return raw_amt_hex_total(rows) if rows else 0.0

    def update_AMT_chunk_plan_cells(self, row):
        headers = self.amt_stockpile_headers()
        rate_column = headers.index("Average Reclaim Rate (t/h)")
        hours_column = headers.index("Target Hours per Chunk")
        raw_total_column = headers.index("Raw Signed AMT WMT")
        amt_total_column = headers.index("AMT Total WMT")
        inventory_total_column = headers.index("Inventory Stockpile Total WMT")
        count_column = headers.index("Calculated Number of Chunks")
        size_column = headers.index("Calculated Chunk Size (WMT)")

        average_reclaim_rate = self.parse_float_from_table_item(
            self.AMT_stockpile_table.item(row, rate_column),
            DEFAULT_AMT_RECLAIM_RATE_TPH,
        )
        chunk_reclaim_hours = self.parse_float_from_table_item(
            self.AMT_stockpile_table.item(row, hours_column),
            DEFAULT_AMT_TARGET_CHUNK_HOURS,
        )
        raw_signed_amt_wmt = self.parse_float_from_table_item(
            self.AMT_stockpile_table.item(row, raw_total_column), 0.0
        )
        amt_total_wmt = self.parse_float_from_table_item(
            self.AMT_stockpile_table.item(row, amt_total_column), 0.0
        )
        inventory_total_wmt = self.parse_float_from_table_item(
            self.AMT_stockpile_table.item(row, inventory_total_column), None
        )
        plan = self.calculate_AMT_chunk_plan(
            amt_total_wmt, average_reclaim_rate, chunk_reclaim_hours
        )

        self.AMT_stockpile_table.blockSignals(True)
        for column, display in (
            (count_column, str(plan["chunk_count"])),
            (size_column, f'{plan["chunk_size"]:,.0f}'),
        ):
            item = QTableWidgetItem(display)
            item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
            item.setTextAlignment(Qt.AlignCenter)
            self.AMT_stockpile_table.setItem(row, column, item)
        self.AMT_stockpile_table.blockSignals(False)

        return {
            "average_reclaim_rate": average_reclaim_rate,
            "chunk_reclaim_hours": chunk_reclaim_hours,
            "chunk_count": plan["chunk_count"],
            "chunk_size": plan["chunk_size"],
            "target_chunk_wmt": plan["target_chunk_wmt"],
            "resulting_chunk_hours": plan["resulting_chunk_hours"],
            "raw_signed_amt_wmt": raw_signed_amt_wmt,
            "amt_total_wmt": amt_total_wmt,
            "inventory_total_wmt": inventory_total_wmt,
        }

    def handle_AMT_chunk_cell_change(self, row, column):
        if column == self.AMT_column_index("Include footprint"):
            self.handle_AMT_footprint_inclusion_change(row, column)
            return
        editable_columns = {
            self.AMT_column_index("Average Reclaim Rate (t/h)"),
            self.AMT_column_index("Target Hours per Chunk"),
        }
        if column not in editable_columns:
            return

        stockpile_item = self.AMT_stockpile_table.item(row, 0)
        if not stockpile_item:
            return

        stockpile_name = stockpile_item.text()
        self.AMT_chunk_settings[stockpile_name] = (
            self.update_AMT_chunk_plan_cells(row)
        )

        if hasattr(self, "draw_AMT_map"):
            self.draw_AMT_map.update_chunk_settings(copy.deepcopy(self.AMT_chunk_settings))

    def store_AMT_chunk_settings(self):
        settings = {}
        rate_column = self.AMT_column_index("Average Reclaim Rate (t/h)")
        hours_column = self.AMT_column_index("Target Hours per Chunk")
        for row in range(self.AMT_stockpile_table.rowCount()):
            stockpile_item = self.AMT_stockpile_table.item(row, 0)
            if not stockpile_item:
                continue

            stockpile_name = stockpile_item.text()
            if str(stockpile_name).strip().upper() in self.excluded_amt_footprints():
                continue
            average_reclaim_rate = self.parse_float_from_table_item(
                self.AMT_stockpile_table.item(row, rate_column),
                DEFAULT_AMT_RECLAIM_RATE_TPH,
            )
            chunk_reclaim_hours = self.parse_float_from_table_item(
                self.AMT_stockpile_table.item(row, hours_column),
                DEFAULT_AMT_TARGET_CHUNK_HOURS,
            )

            if average_reclaim_rate <= 0 or chunk_reclaim_hours <= 0:
                QMessageBox.warning(
                    self,
                    "BlendMaster",
                    f"Average Reclaim Rate and Target Hours per Chunk must be positive for {stockpile_name}."
                )
                return False

            settings[stockpile_name] = self.update_AMT_chunk_plan_cells(row)

        self.AMT_chunk_settings = settings

        if hasattr(self, "draw_AMT_map"):
            self.draw_AMT_map.update_chunk_settings(copy.deepcopy(self.AMT_chunk_settings))

        return True

    def amt_stockpile_headers(self):
        headers = [
            "AMT Stockpiles",
            "Include footprint",
            "Raw Signed AMT WMT",
            "AMT Total WMT",
            "Inventory Stockpile Total WMT",
            "Average Reclaim Rate (t/h)",
            "Target Hours per Chunk",
            "Calculated Number of Chunks",
            "Calculated Chunk Size (WMT)",
            "Grade-block Lineage",
            "Modelled Product Coverage",
            "Inventory Match",
            "Matched Inventory Stockpile",
            "Matched Inventory Build",
            "Matched Inventory Time",
            "Modelled ROM Grades",
        ]
        for brand in configured_brands(self.product_brand_labels_choice):
            headers.extend([
                f"Adjusted ROM Grades ({brand})",
                f"Modelled Product Grades ({brand})",
                f"Adjusted Product Grades ({brand})",
            ])
        return headers

