    @staticmethod
    def AMT_opening_timestamp_key(value):
        """Return a stable cache key for a scenario opening timestamp."""
        if hasattr(value, "toPyDateTime"):
            value = value.toPyDateTime()
        if isinstance(value, pd.Timestamp):
            value = value.to_pydatetime()
        if isinstance(value, datetime):
            # The Site Configuration control and saved project state retain
            # whole seconds.  A Now-mode start was previously allowed to keep
            # incidental Python microseconds in the cache signature, so an
            # otherwise unchanged loaded project appeared to have a different
            # timestamp and unnecessarily refetched inventory and AMT data.
            return value.replace(microsecond=0).isoformat(timespec="seconds")
        return str(value or "").strip()

    @classmethod
    def opening_request_signatures_match(cls, cached_signature, request_signature):
        """Compare opening-data signatures while migrating sub-second keys."""
        cached_text = str(cached_signature or "")
        request_text = str(request_signature or "")
        if cached_text == request_text:
            return bool(request_text)
        if not cached_text or not request_text:
            return False

        def normalized_payload(raw_signature):
            try:
                payload = json.loads(raw_signature)
            except (TypeError, ValueError, json.JSONDecodeError):
                return None
            if not isinstance(payload, dict):
                return None
            payload = copy.deepcopy(payload)
            start_time = payload.get("start_time")
            if start_time:
                try:
                    parsed = pd.Timestamp(start_time)
                except (TypeError, ValueError):
                    parsed = None
                if parsed is not None and not pd.isna(parsed):
                    payload["start_time"] = cls.AMT_opening_timestamp_key(parsed)
            return payload

        cached_payload = normalized_payload(cached_text)
        request_payload = normalized_payload(request_text)
        return (
            cached_payload is not None
            and request_payload is not None
            and cached_payload == request_payload
        )

    @classmethod
    def opening_request_signature_changes(cls, cached_signature, request_signature):
        """Describe material cache-key changes for console diagnostics."""
        try:
            cached = json.loads(str(cached_signature or ""))
            requested = json.loads(str(request_signature or ""))
        except (TypeError, ValueError, json.JSONDecodeError):
            return ["the saved cache key is unavailable or unreadable"]
        if not isinstance(cached, dict) or not isinstance(requested, dict):
            return ["the saved cache key has an unsupported format"]

        changes = []
        for field in ("cache_version", "hub", "mine", "opf", "crusher"):
            if cached.get(field) != requested.get(field):
                changes.append(field)

        cached_time = cls.AMT_opening_timestamp_key(cached.get("start_time"))
        requested_time = cls.AMT_opening_timestamp_key(requested.get("start_time"))
        try:
            cached_time = cls.AMT_opening_timestamp_key(pd.Timestamp(cached_time))
            requested_time = cls.AMT_opening_timestamp_key(pd.Timestamp(requested_time))
        except (TypeError, ValueError):
            pass
        if cached_time != requested_time:
            changes.append(f"timestamp ({cached_time} -> {requested_time})")
        if cached.get("selections") != requested.get("selections"):
            changes.append("selected footprint/build set")
        return changes or ["an unrecognised cache-key field"]

    def AMT_opening_request_signature(self, data_source):
        """Identify the Snowflake inputs that determine an AMT snapshot."""
        selections = []
        for stockpile_name, attributes in sorted(
            self.included_AMT_snapshot(data_source).items(), key=lambda item: str(item[0]).upper()
        ):
            attributes = attributes or {}
            selections.append({
                "footprint": str(stockpile_name or "").strip().upper(),
                "build": str(attributes.get("build") or "").strip().upper(),
            })
        payload = {
            "cache_version": AMT_OPENING_CACHE_VERSION,
            "hub": str(getattr(self, "hub_input_choice", None) or "").strip().upper(),
            "mine": str(getattr(self, "mine_input_choice", None) or "").strip().upper(),
            "opf": str(getattr(self, "opf_input_choice", None) or "").strip().upper(),
            "start_time": self.AMT_opening_timestamp_key(
                getattr(self, "start_time_choice", None)
            ),
            "selections": selections,
            "excluded_footprints": sorted(self.excluded_amt_footprints()),
        }
        return json.dumps(payload, sort_keys=True, separators=(",", ":"))

    def AMT_cached_snapshot_is_reusable(
        self, cached_signature, request_signature
    ):
        """Return whether an AMT opening snapshot can satisfy this request."""
        if self.opening_request_signatures_match(
            cached_signature, request_signature
        ):
            return True, "exact"

        try:
            cached = json.loads(str(cached_signature or ""))
            requested = json.loads(str(request_signature or ""))
        except (TypeError, ValueError, json.JSONDecodeError):
            return False, ""
        if not isinstance(cached, dict) or not isinstance(requested, dict):
            return False, ""

        def selection_pairs(payload):
            selections = payload.pop("selections", None)
            if not isinstance(selections, list):
                return None
            pairs = set()
            for selection in selections:
                if not isinstance(selection, dict):
                    return None
                pairs.add((
                    str(selection.get("footprint") or "").strip().upper(),
                    str(selection.get("build") or "").strip().upper(),
                ))
            return pairs

        cached = copy.deepcopy(cached)
        requested = copy.deepcopy(requested)
        # Effective selections govern warehouse reuse; exclusions still identify callbacks.
        cached.pop("excluded_footprints", None)
        requested.pop("excluded_footprints", None)
        cached_selections = selection_pairs(cached)
        requested_selections = selection_pairs(requested)
        if cached_selections is None or requested_selections is None:
            return False, ""
        selection_subset = requested_selections.issubset(cached_selections)

        cached_time = self.AMT_opening_timestamp_key(cached.get("start_time"))
        requested_time = self.AMT_opening_timestamp_key(
            requested.get("start_time")
        )
        try:
            cached_time = self.AMT_opening_timestamp_key(pd.Timestamp(cached_time))
            requested_time = self.AMT_opening_timestamp_key(
                pd.Timestamp(requested_time)
            )
        except (TypeError, ValueError):
            pass
        cached["start_time"] = cached_time
        requested["start_time"] = requested_time

        if cached == requested and selection_subset:
            return True, "selection subset"
        if int(getattr(self, "time_mode_choice", 1) or 1) != 1:
            return False, ""
        tolerance = max(0, int(getattr(
            self, "AMT_refresh_tolerance_minutes", 30
        ) or 0))
        if tolerance <= 0:
            return False, ""
        refreshed_at = getattr(self, "AMT_last_refresh_datetime", None)
        try:
            refreshed_at = pd.Timestamp(refreshed_at).to_pydatetime()
        except (TypeError, ValueError):
            return False, ""
        if refreshed_at.tzinfo is not None:
            refreshed_at = refreshed_at.replace(tzinfo=None)
        age_minutes = max(
            0.0, (datetime.now() - refreshed_at).total_seconds() / 60.0
        )
        if age_minutes > tolerance:
            return False, ""
        cached.pop("start_time", None)
        requested.pop("start_time", None)
        if cached != requested or not selection_subset:
            return False, ""
        try:
            scenario_shift_minutes = abs(
                (pd.Timestamp(requested_time) - pd.Timestamp(cached_time))
                .total_seconds()
            ) / 60.0
        except (TypeError, ValueError):
            return False, ""
        if scenario_shift_minutes > tolerance:
            return False, ""
        subset_label = (
            " selection subset" if requested_selections != cached_selections else ""
        )
        return True, f"fresh{subset_label} ({age_minutes:.1f} min old)"

    @staticmethod
    def AMT_snapshot_for_selected_footprints(snapshot, data_source):
        """Filter a cached AMT snapshot to the currently selected footprints."""
        selected = {
            str(footprint or "").strip().upper()
            for footprint in (data_source or {})
        }
        return {
            footprint: rows
            for footprint, rows in (snapshot or {}).items()
            if str(footprint or "").strip().upper() in selected
        }

    def AMT_enrichment_request_signature(self):
        """Identify inputs that change mapped or reconciled AMT hex values."""
        # Read instance state directly. Besides avoiding unnecessary Qt
        # property lookups, this keeps the signature helper usable in the
        # lightweight non-window objects used by reconciliation tests.
        state = vars(self)
        payload = {
            "reconciliation": reconciliation_fingerprint({
                "tonnage_recon_version": AMT_TONNAGE_RECON_VERSION,
                "excluded_footprints": sorted(self.excluded_amt_footprints()),
                "algorithm_version": RECONCILIATION_ALGORITHM_VERSION,
                "settings": state.get("reconciliation_settings"),
                "inputs": state.get("reconciliation_inputs"),
                "scenario_start": state.get("start_time_choice"),
            }),
            "opening_snapshot": str(
                state.get("AMT_data_request_signature", "") or ""
            ),
            "field_definitions": normalize_field_definitions(
                state.get("field_definitions")
            ),
            "field_mappings": normalize_field_mappings(
                state.get("field_mappings")
            ),
            "historical_recon_factors": state.get(
                "historical_recon_factors", {}
            ) or {},
            "opf": str(state.get("opf_input_choice", "") or ""),
            "brands": configured_brands(
                state.get("product_brand_labels_choice", "")
            ),
            "cb_lump_fines_mode": str(
                state.get("cb_lump_fines_mode", "derived") or "derived"
            ),
            "cb_lump_percentage": numeric(
                state.get("cb_lump_percentage", 50.0)
            ),
            "byproducts_enabled": bool(
                state.get("byproducts_enabled", False)
            ),
            "byproduct_quantity_fields": normalize_byproduct_quantity_fields(
                state.get("byproduct_quantity_fields")
            ),
            "byproduct_grade_fields": normalize_byproduct_grade_fields(
                state.get("byproduct_grade_fields")
            ),
        }
        return json.dumps(payload, sort_keys=True, default=str, separators=(",", ":"))

    def selected_AMT_data_source(self):
        return {
            name: values
            for name, values in self.included_stockpile_data().items()
            if values.get("amt", False)
        }

    def refresh_AMT_enrichment_if_needed(
        self, data_source=None, force=False, persist=True, refresh_map=True,
        allow_pending=False
    ):
        """Rebuild and persist AMT hex fields only when their inputs changed."""
        self.prune_excluded_AMT_state()
        if not getattr(self, "AMT_stockpile_data", None):
            self.AMT_enrichment_signature = ""
            self.AMT_chunk_reconciliation_signature = ""
            return False
        if allow_pending and self.reconciliation_factors_pending():
            # Inventory submission fetches raw AMT fields for Map Fields before
            # Data Streams has loaded reconciliation. Persist that raw snapshot
            # but leave enrichment pending so submission calculates it later.
            self.AMT_enrichment_signature = ""
            self.AMT_chunk_reconciliation_signature = ""
            if persist:
                self.opening_stockpile_inventories.save_AMT_to_database(
                    self.AMT_stockpile_data
                )
            if refresh_map:
                self.refresh_AMT_map_data_from_database()
            return False
        signature = self.AMT_enrichment_request_signature()
        if (
            not force
            and str(getattr(self, "AMT_enrichment_signature", "") or "")
            == signature
        ):
            return False
        self.AMT_stockpile_data = self.enrich_AMT_grade_streams(
            data_source if data_source is not None else self.selected_AMT_data_source(),
            self.AMT_stockpile_data,
        )
        self.prune_zeroed_amt_chunks()
        self.AMT_enrichment_signature = signature
        self.AMT_chunk_reconciliation_signature = ""
        if persist:
            self.opening_stockpile_inventories.save_AMT_to_database(
                self.AMT_stockpile_data
            )
        if refresh_map:
            self.refresh_AMT_map_data_from_database()
        return True

    def set_AMT_cache_status(self, message, warning=False):
        label = getattr(self, "AMT_cache_status_label", None)
        if label is None:
            return
        label.setText(str(message or ""))
        label.setStyleSheet(
            "color: #92400e;" if warning else "color: #607080;"
        )

    def refresh_AMT_data_from_snowflake(self, _checked=False):
        selected_rows = getattr(self, "updated_stockpile_data", None) or {}
        if not any(
            isinstance(attributes, dict) and attributes.get("amt", False)
            for attributes in selected_rows.values()
        ):
            QMessageBox.information(
                self,
                "BlendMaster",
                "No AMT stockpiles are selected for refresh.",
            )
            return
        self.setup_AMT_stockpile_table(force_refresh=True)

    def setup_AMT_stockpile_table(self, force_refresh=False):
        """Setup for the stockpile table in the new Stockpiles tab with live conditional formatting."""

        # The project-load path may complete synchronously from saved AMT
        # rows.  Build the host panel before either that restore or an async
        # Snowflake fetch so an interrupted load cannot leave the tab blank.
        self.ensure_AMT_map_panel(connect_table=False)
        if hasattr(self, "AMT_refresh_tolerance_input"):
            self.AMT_refresh_tolerance_minutes = int(
                self.AMT_refresh_tolerance_input.value()
            )

        headers = self.amt_stockpile_headers()
        self.AMT_stockpile_table.setColumnCount(len(headers))
        self.AMT_stockpile_table.setHorizontalHeaderLabels(headers)
        self.AMT_stockpile_table.verticalHeader().setVisible(False)

        # Bold headers
        header_font = self.AMT_stockpile_table.horizontalHeader().font()
        header_font.setBold(True)
        self.AMT_stockpile_table.horizontalHeader().setFont(header_font)

        # Keep participation controls usable even if the first warehouse read
        # fails. These rows require only the selected inventory names.
        if self.AMT_stockpile_table.rowCount() == 0:
            selected = {n: r for n, r in (vars(self).get("updated_stockpile_data") or {}).items() if r.get("amt", False)}
            self.AMT_stockpile_table.blockSignals(True)
            self.AMT_stockpile_table.setRowCount(len(selected))
            for index, name in enumerate(selected):
                name_item = QTableWidgetItem(name)
                name_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                self.AMT_stockpile_table.setItem(index, 0, name_item)
                item = QTableWidgetItem()
                item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsUserCheckable)
                item.setCheckState(Qt.Unchecked if str(name).strip().upper() in self.excluded_amt_footprints() else Qt.Checked)
                self.AMT_stockpile_table.setItem(index, headers.index("Include footprint"), item)
            self.AMT_stockpile_table.blockSignals(False)
            self.ensure_AMT_map_panel()

        # Choose data source
        self.prune_excluded_AMT_state()
        data_source = self.selected_AMT_data_source()
        builds = [value["build"] for value in data_source.values()]
        request_signature = self.AMT_opening_request_signature(data_source)

        if data_source:
            if (
                getattr(self, "project_load_restore_in_progress", False)
                and self.restore_loaded_AMT_data_to_database(data_source)
            ):
                self.AMT_data_request_signature = request_signature
                self.set_AMT_cache_status(
                    "Restored the saved AMT opening snapshot; Snowflake was not queried."
                )
                self.finish_AMT_stockpile_table(
                    data_source,
                    getattr(self, "AMT_stockpile_data", {}),
                    reuse_prepared=True,
                    refresh_prepared_map=True,
                )
                return

            cached_signature = str(
                getattr(self, "AMT_data_request_signature", "") or ""
            )
            signature_matches = self.opening_request_signatures_match(
                cached_signature, request_signature
            )
            cache_reusable, reuse_reason = self.AMT_cached_snapshot_is_reusable(
                cached_signature, request_signature
            )
            compatibility_issue = self.AMT_data_compatibility_issue(data_source)
            if (
                not force_refresh
                and cache_reusable
                and not compatibility_issue
            ):
                selection_subset_reuse = "selection subset" in reuse_reason
                cached_AMT_data = getattr(self, "AMT_stockpile_data", {})
                if selection_subset_reuse:
                    cached_AMT_data = self.AMT_snapshot_for_selected_footprints(
                        cached_AMT_data, data_source
                    )
                    self.AMT_stockpile_data = cached_AMT_data
                    self.AMT_data_request_signature = request_signature
                    # Removing a footprint does not alter the already-enriched
                    # rows retained for the other footprints. Record the new
                    # active request without rerunning grade derivation, and
                    # force only the cheap chunk-selection reconciliation.
                    self.AMT_enrichment_signature = (
                        self.AMT_enrichment_request_signature()
                    )
                    self.AMT_chunk_reconciliation_signature = ""
                    self.opening_stockpile_inventories.save_AMT_to_database(
                        cached_AMT_data
                    )
                    cache_message = (
                        "Reused the cached AMT opening snapshot and removed "
                        "deselected footprints; Snowflake was not queried."
                    )
                elif reuse_reason == "exact":
                    cache_message = (
                        "Reused the cached AMT opening snapshot because the "
                        "site, timestamp and selected builds are unchanged."
                    )
                else:
                    cache_message = (
                        "Reused the cached AMT opening snapshot within the "
                        f"configured refresh tolerance ({reuse_reason})."
                    )
                self.set_AMT_cache_status(cache_message)
                self.finish_AMT_stockpile_table(
                    data_source,
                    cached_AMT_data,
                    reuse_prepared=True,
                    refresh_prepared_map=selection_subset_reuse,
                )
                return

            if getattr(self, "project_load_restore_in_progress", False):
                self.project_load_waiting_for_AMT = True

            if force_refresh:
                cache_miss_reason = "a manual refresh was requested"
                cache_status = "Refreshing the AMT opening snapshot from Snowflake..."
            elif not signature_matches:
                changed_inputs = ", ".join(
                    self.opening_request_signature_changes(
                        cached_signature, request_signature
                    )
                )
                cache_miss_reason = (
                    f"the AMT request changed: {changed_inputs}"
                )
                cache_status = (
                    "Fetching the AMT opening snapshot from Snowflake because the "
                    f"request changed ({changed_inputs})..."
                )
            else:
                cache_miss_reason = compatibility_issue or (
                    "the cached AMT snapshot is incompatible"
                )
                cache_status = (
                    "Fetching the AMT opening snapshot from Snowflake because "
                    f"{cache_miss_reason}..."
                )
            print(f"AMT cache miss: {cache_miss_reason}.")
            self.set_AMT_cache_status(cache_status, warning=True)

            request_start = self.start_time_choice
            self.run_background_task(
                "Fetching AMT stockpile data from Snowflake...",
                lambda: self.opening_stockpile_inventories.call_opening_AMT_stockpile_inventories(
                    builds,
                    request_start,
                ),
                lambda AMT_stockpile_data: self.finish_AMT_stockpile_table_from_fetch(
                    data_source, AMT_stockpile_data, request_signature
                ),
                self.handle_AMT_stockpile_fetch_error,
            )
            return

        self.opening_stockpile_inventories.clear_AMT_stockpile_database()
        self.AMT_data_request_signature = ""
        self.AMT_enrichment_signature = ""
        self.set_AMT_cache_status("All AMT footprints are excluded; conventional inventory stockpiles can still be submitted." if self.excluded_amt_footprints() else "No AMT stockpiles are selected.")
        self.finish_AMT_stockpile_table(data_source, {}, reuse_prepared=True)

    @staticmethod
    def AMT_row_has_lineage_marker(row):
        """Recognise lineage columns regardless of Snowflake/SQLite casing."""
        if not isinstance(row, dict):
            return False
        column_names = {
            str(column_name).strip().upper()
            for column_name in row
        }
        return bool({
            "GRADE_BLOCK_LINEAGE_JSON",
            "LINEAGE_ENTRY_COUNT",
        } & column_names)

    def AMT_data_compatibility_issue(self, data_source):
        """Return why cached AMT rows cannot be reused, or an empty string."""
        AMT_stockpile_data = getattr(self, "AMT_stockpile_data", {}) or {}
        if not isinstance(AMT_stockpile_data, dict):
            return "the cached AMT snapshot is not a footprint dictionary"
        if not AMT_stockpile_data:
            return "no cached AMT opening snapshot is available"

        selected_footprints = {
            str(stockpile_name).strip().upper()
            for stockpile_name in (data_source or {})
        }
        saved_footprints = {
            str(footprint).strip().upper()
            for footprint, rows in AMT_stockpile_data.items()
            if rows
        }
        if not selected_footprints.issubset(saved_footprints):
            missing = sorted(selected_footprints - saved_footprints)
            return (
                "the cached AMT snapshot is missing selected footprint(s): "
                + ", ".join(missing)
            )

        # Saved AMT rows created before grade-block lineage still carry the
        # retired inventory-derived blend/upgrade streams.  Refresh those
        # projects from Snowflake instead of silently mixing both models.
        for footprint, rows in AMT_stockpile_data.items():
            footprint_key = str(footprint).strip().upper()
            if footprint_key not in selected_footprints:
                continue
            if not any(
                self.AMT_row_has_lineage_marker(row)
                for row in rows or []
            ):
                return (
                    f"cached AMT rows for {footprint_key} predate grade-block lineage"
                )

        return ""

    def has_compatible_AMT_data(self, data_source):
        return not self.AMT_data_compatibility_issue(data_source)

    def restore_loaded_AMT_data_to_database(self, data_source):
        # An exact saved request signature is authoritative even when a
        # selected AMT footprint returned no rows. Requiring every selected
        # footprint to exist in the row dictionary caused valid negative
        # results to trigger a needless Snowflake refresh and interrupt a
        # complete saved-timestamp project restore.
        request_signature = self.AMT_opening_request_signature(data_source)
        exact_saved_snapshot = (
            self.opening_request_signatures_match(
                getattr(self, "AMT_data_request_signature", ""),
                request_signature,
            )
        )
        compatible = self.has_compatible_AMT_data(data_source)
        if not compatible and exact_saved_snapshot:
            saved_rows = getattr(self, "AMT_stockpile_data", {}) or {}
            present_data = {
                name: values
                for name, values in (data_source or {}).items()
                if saved_rows.get(name)
            }
            compatible = bool(present_data) and self.has_compatible_AMT_data(
                present_data
            )
        if not compatible:
            return False
        self.AMT_stockpile_data = guard_amt_snapshot(self.included_AMT_snapshot(self.AMT_stockpile_data))
        self.prune_zeroed_amt_chunks()
        self.opening_stockpile_inventories.save_AMT_to_database(
            self.AMT_stockpile_data
        )
        return True

    def finish_AMT_stockpile_table_from_fetch(
        self, data_source, AMT_stockpile_data, request_signature=None
    ):
        current_source = self.selected_AMT_data_source()
        if request_signature and not self.opening_request_signatures_match(
            request_signature, self.AMT_opening_request_signature(current_source)
        ):
            self.set_AMT_cache_status("AMT selection changed during refresh; the outdated result was discarded. Refresh to load the current selection.", warning=True)
            return
        self.AMT_data_request_signature = str(request_signature or "")
        self.AMT_last_refresh_datetime = datetime.now()
        self.AMT_enrichment_signature = ""
        self.AMT_chunk_reconciliation_signature = ""
        self._available_mapping_fields_cache = {}
        self.set_AMT_cache_status(
            "AMT opening snapshot fetched from Snowflake and cached for this "
            "site, timestamp and build selection."
        )
        self.finish_AMT_stockpile_table(current_source, AMT_stockpile_data)

        if hasattr(self, "map_fields_available_list"):
            self.refresh_map_available_fields()

        if getattr(self, "project_load_waiting_for_AMT", False):
            self.project_load_waiting_for_AMT = False
            self.continue_project_load_after_stockpile_setup()

        if getattr(self, "agent_workflow_waiting_for_amt", False):
            self.agent_workflow_waiting_for_amt = False
            QTimer.singleShot(250, self.agent_workflow_apply_amt_stockpiles)

    def handle_AMT_stockpile_fetch_error(self, error_message):
        project_load_failed = bool(
            getattr(self, "project_load_restore_in_progress", False)
        )
        self.project_load_waiting_for_AMT = False
        self.agent_workflow_waiting_for_amt = False
        if getattr(self, "agent_workflow_active", False):
            self.stop_agent_workflow_apply(f"Agent workflow stopped while fetching AMT stockpile data: {error_message}")
        self.project_load_restore_in_progress = False
        self.set_AMT_cache_status(
            "AMT Snowflake refresh failed; any previous cached snapshot has "
            "been retained.",
            warning=True,
        )
        if project_load_failed:
            self.finish_project_load_ui(success=False)
        message = str(error_message or "")
        if "57014" in message or "SQL execution canceled" in message:
            message = (
                "Snowflake cancelled the AMT opening query before it completed. "
                "BlendMaster has narrowed this query and allows up to 15 minutes; "
                "please retry. If it repeats, provide the scenario start time and "
                "selected AMT footprints so the Snowflake execution can be profiled."
            )
        self.show_error_popup(message)

    def finish_AMT_stockpile_table(
        self, data_source, AMT_stockpile_data, reuse_prepared=False,
        refresh_prepared_map=False
    ):
        headers = self.amt_stockpile_headers()
        self.AMT_stockpile_data = compact_amt_stockpile_data(
            guard_amt_snapshot(self.included_AMT_snapshot(AMT_stockpile_data))
        )
        self.prune_zeroed_amt_chunks()
        zeroed = zeroed_amt_footprints(self.AMT_stockpile_data)
        if zeroed:
            reuse_prepared = False
        if not reuse_prepared:
            if self.AMT_stockpile_data:
                self.refresh_AMT_enrichment_if_needed(
                    data_source, force=True, persist=True, refresh_map=False,
                    allow_pending=True
                )
            else:
                self.opening_stockpile_inventories.clear_AMT_stockpile_database()
        self.start_dash_AMT_map_thread()
        if not reuse_prepared or refresh_prepared_map:
            self.refresh_AMT_map_data_from_database()

        # Excluded footprints stay visible here to allow restoration.
        data_source = {name: row for name, row in (vars(self).get("updated_stockpile_data") or data_source or {}).items() if row.get("amt", False)}
        excluded = self.excluded_amt_footprints()
        self.AMT_stockpile_table.blockSignals(True)
        self.AMT_stockpile_table.clearContents()
        # Set Table Dimensions
        self.AMT_stockpile_table.setRowCount(len(data_source))

        # Populate Stockpile Data
        for row_idx, (stockpile_name, attributes) in enumerate(data_source.items()):
           
            if attributes["amt"]:

                # Stockpile Name (Center-align)
                stockpile_item = QTableWidgetItem(str(stockpile_name))
                stockpile_item.setFlags(Qt.ItemIsEnabled)  # Non-editable
                stockpile_item.setTextAlignment(Qt.AlignCenter)  # Center-align the stockpile name
                self.AMT_stockpile_table.setItem(row_idx, 0, stockpile_item)

                include_item = QTableWidgetItem()
                include_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsUserCheckable)
                is_excluded = str(stockpile_name).strip().upper() in excluded
                include_item.setCheckState(Qt.Unchecked if is_excluded else Qt.Checked)
                include_item.setToolTip("Uncheck to skip this whole footprint. Recheck and refresh AMT data to restore it.")
                self.AMT_stockpile_table.setItem(row_idx, headers.index("Include footprint"), include_item)
                if is_excluded:
                    record = normalize_amt_exclusions(vars(self).get("AMT_footprint_exclusions"))[str(stockpile_name).strip().upper()]
                    status = QTableWidgetItem("Excluded")
                    status.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                    status.setToolTip(f"{record.get('exclusion_reason', '')}\n{record.get('excluded_at', '')}")
                    self.AMT_stockpile_table.setItem(row_idx, headers.index("AMT Total WMT"), status)
                    continue

                amt_total_wmt, inventory_total_wmt = (
                    self.AMT_footprint_totals(stockpile_name, attributes)
                )
                raw_signed_amt_wmt = self.AMT_raw_signed_footprint_total(
                    stockpile_name
                )
                chunk_setting = self.get_AMT_chunk_setting(stockpile_name)
                average_reclaim_rate = chunk_setting.get(
                    "average_reclaim_rate", DEFAULT_AMT_RECLAIM_RATE_TPH
                )
                chunk_reclaim_hours = chunk_setting.get(
                    "chunk_reclaim_hours", DEFAULT_AMT_TARGET_CHUNK_HOURS
                )
                chunk_plan = self.calculate_AMT_chunk_plan(
                    amt_total_wmt,
                    average_reclaim_rate,
                    chunk_reclaim_hours,
                )

                for caption, value in (
                    ("Raw Signed AMT WMT", raw_signed_amt_wmt),
                    ("AMT Total WMT", amt_total_wmt),
                    ("Inventory Stockpile Total WMT", inventory_total_wmt),
                ):
                    display = "" if value is None else f"{value:,.0f}"
                    item = QTableWidgetItem(display)
                    item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                    item.setTextAlignment(Qt.AlignCenter)
                    self.AMT_stockpile_table.setItem(
                        row_idx, headers.index(caption), item
                    )
                    if caption == "AMT Total WMT":
                        first = (self.AMT_stockpile_data.get(stockpile_name) or [{}])[0]
                        reason = first.get("SPATIAL_RECON_REASON", "")
                        item.setToolTip(reason)
                        if str(stockpile_name).strip().upper() in zeroed:
                            item.setText("0 · zeroed")

                average_rate_item = QTableWidgetItem(f"{average_reclaim_rate:.2f}")
                average_rate_item.setTextAlignment(Qt.AlignCenter)
                self.AMT_stockpile_table.setItem(
                    row_idx,
                    headers.index("Average Reclaim Rate (t/h)"),
                    average_rate_item,
                )

                chunk_hours_item = QTableWidgetItem(f"{chunk_reclaim_hours:g}")
                chunk_hours_item.setTextAlignment(Qt.AlignCenter)
                self.AMT_stockpile_table.setItem(
                    row_idx,
                    headers.index("Target Hours per Chunk"),
                    chunk_hours_item,
                )

                for caption, display in (
                    (
                        "Calculated Number of Chunks",
                        str(chunk_plan["chunk_count"]),
                    ),
                    (
                        "Calculated Chunk Size (WMT)",
                        f'{chunk_plan["chunk_size"]:,.0f}',
                    ),
                ):
                    item = QTableWidgetItem(display)
                    item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                    item.setTextAlignment(Qt.AlignCenter)
                    self.AMT_stockpile_table.setItem(
                        row_idx, headers.index(caption), item
                    )

                footprint_rows = (self.AMT_stockpile_data or {}).get(stockpile_name, []) or []
                provenance = footprint_rows[0] if footprint_rows else {}
                matched_name = str(
                    provenance.get("AMT_INVENTORY_STOCKPILE")
                    or provenance.get("INTERNAL_RECON_INVENTORY_STOCKPILE")
                    or provenance.get("internal_recon_inventory_stockpile")
                    or ""
                )
                lineage_summary, product_coverage_summary = self.amt_lineage_summary(
                    footprint_rows
                )
                for caption, summary in (
                    ("Grade-block Lineage", lineage_summary),
                    ("Modelled Product Coverage", product_coverage_summary),
                ):
                    factor_item = QTableWidgetItem(summary)
                    factor_item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                    factor_item.setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter)
                    self.AMT_stockpile_table.setItem(
                        row_idx, headers.index(caption), factor_item
                    )

                match_status = bool(
                    provenance.get("AMT_INVENTORY_MATCHED")
                    if "AMT_INVENTORY_MATCHED" in provenance
                    else provenance.get(
                        "INTERNAL_RECON_MATCHED",
                        provenance.get("internal_recon_matched", False),
                    )
                )
                provenance_cells = {
                    "Inventory Match": "Matched" if match_status else "Not matched",
                    "Matched Inventory Stockpile": matched_name,
                    "Matched Inventory Build": str(
                        provenance.get("AMT_INVENTORY_BUILD")
                        or provenance.get("INTERNAL_RECON_INVENTORY_BUILD")
                        or provenance.get("internal_recon_inventory_build")
                        or ""
                    ),
                    "Matched Inventory Time": str(
                        provenance.get("AMT_INVENTORY_TRANSACTION_DATETIME")
                        or provenance.get("INTERNAL_RECON_INVENTORY_TRANSACTION_DATETIME")
                        or provenance.get("internal_recon_inventory_transaction_datetime")
                        or ""
                    ),
                }
                streams = self.aggregate_AMT_footprint_grade_streams(
                    footprint_rows
                )
                first_brand = (
                    configured_brands(self.product_brand_labels_choice) or [None]
                )[0]
                provenance_cells["Modelled ROM Grades"] = format_grade_stream_vector(
                    streams, "modelled_rom", first_brand
                )
                for brand in configured_brands(self.product_brand_labels_choice):
                    provenance_cells.update({
                        f"Adjusted ROM Grades ({brand})": format_grade_stream_vector(
                            streams, "adjusted_rom", brand
                        ),
                        f"Modelled Product Grades ({brand})": format_grade_stream_vector(
                            streams, "modelled_product", brand
                        ),
                        f"Adjusted Product Grades ({brand})": format_grade_stream_vector(
                            streams, "adjusted_product", brand
                        ),
                    })
                for caption, display_value in provenance_cells.items():
                    column = headers.index(caption)
                    item = QTableWidgetItem(display_value)
                    item.setFlags(Qt.ItemIsEnabled | Qt.ItemIsSelectable)
                    item.setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter)
                    item.setToolTip(display_value)
                    self.AMT_stockpile_table.setItem(row_idx, column, item)

        # Resize Columns
        for column in range(len(headers)):
            self.AMT_stockpile_table.horizontalHeader().setSectionResizeMode(
                column, QHeaderView.ResizeToContents
            )
        self.store_AMT_chunk_settings()
        self.AMT_stockpile_table.blockSignals(False)
        self.ensure_AMT_map_panel()

        # A freshly created web view has no URL.  Restored projects already
        # contain their AMT rows and selected chunks, so reconnect the view
        # automatically instead of requiring an otherwise unexplained button
        # click.  The second reload covers slower Dash start-up on some PCs.
        if getattr(self, "project_load_restore_in_progress", False):
            QTimer.singleShot(250, self.reload_AMT_map_view)
            QTimer.singleShot(1500, self.reload_AMT_map_view)

    @staticmethod
    def aggregate_AMT_footprint_grade_streams(rows):
        """Tonne-weight grade streams across every positive hex in a footprint."""
        weighted_sums = {}
        denominators = {}
        for row in rows or []:
            row = row or {}
            tonnes = None
            for key in ("FINAL_WMT", "final_wmt", "BALANCE", "balance", "WMT", "wmt"):
                tonnes = numeric(row.get(key))
                if tonnes is not None:
                    break
            tonnes = max(tonnes or 0.0, 0.0)
            if tonnes <= 0:
                continue
            streams = normalise_grade_streams(
                row.get("GRADE_STREAMS") or row.get("grade_streams") or {}
            )
            for stream, brand_map in streams.items():
                for brand, grades in (brand_map or {}).items():
                    for analyte in ANALYTES:
                        value = numeric((grades or {}).get(analyte))
                        if value is None:
                            continue
                        key = (stream, brand, analyte)
                        weighted_sums[key] = weighted_sums.get(key, 0.0) + value * tonnes
                        denominators[key] = denominators.get(key, 0.0) + tonnes

        result = {stream: {} for stream in STREAMS}
        for (stream, brand, analyte), weighted_sum in weighted_sums.items():
            result[stream].setdefault(brand, {})[analyte] = (
                weighted_sum / denominators[(stream, brand, analyte)]
            )
        return result

    def amt_lineage_summary(self, rows):
        """Summarise footprint lineage and EXPIT product-property coverage."""
        rows = rows or []
        grade_blocks = set()
        final_wmt = 0.0
        matched_final_wmt = 0.0
        for row in rows:
            row = row or {}
            final_wmt += numeric(row.get("LINEAGE_FINAL_WMT")) or 0.0
            matched_final_wmt += (
                numeric(row.get("LINEAGE_MATCHED_FINAL_WMT")) or 0.0
            )
            lineage_json = row.get("GRADE_BLOCK_LINEAGE_JSON")
            try:
                lineage = (
                    json.loads(lineage_json)
                    if isinstance(lineage_json, str) else lineage_json
                )
            except (TypeError, ValueError):
                lineage = []
            for entry in lineage if isinstance(lineage, list) else []:
                key = str((entry or {}).get("lineage_key") or "")
                if key and key.upper() != "UNMATCHED":
                    grade_blocks.add(key)

        coverage = matched_final_wmt / final_wmt * 100.0 if final_wmt > 0 else None
        unmatched = max(final_wmt - matched_final_wmt, 0.0)
        lineage_summary = (
            f"{len(grade_blocks)} grade blocks | "
            f"{coverage:.2f}% attributed | {unmatched:,.2f} t unmatched"
            if coverage is not None else "No positive AMT balance"
        )

        slot = amt_modelled_product_slot(self.opf_input_choice)
        if is_dry_plant(self.opf_input_choice):
            return lineage_summary, "Dry plant: product follows adjusted ROM"
        if slot is None:
            return lineage_summary, "No confirmed EXPIT product channel"
        labels = {"fe": "Fe", "si": "SiO₂", "al": "Al₂O₃", "p": "P", "mn": "Mn"}
        product_coverage = []
        source_prefix = f"MODELLED_{slot.upper()}"
        for analyte in ANALYTES:
            source_name = {"si": "SIO2", "al": "AL2O3"}.get(
                analyte, analyte.upper()
            )
            weighted_coverage = 0.0
            total_tonnes = 0.0
            for row in rows:
                tonnes = numeric((row or {}).get("FINAL_WMT")) or 0.0
                pct = numeric((row or {}).get(
                    f"{source_prefix}_{source_name}_COVERAGE_PCT"
                ))
                if tonnes > 0:
                    total_tonnes += tonnes
                    weighted_coverage += (pct or 0.0) * tonnes
            pct = weighted_coverage / total_tonnes if total_tonnes > 0 else 0.0
            product_coverage.append(f"{labels[analyte]} {pct:.2f}%")
        return lineage_summary, f"{slot.upper()} | " + ", ".join(product_coverage)

    def enrich_AMT_grade_streams(self, data_source, amt_data):
        """Attach lineage-derived AMT streams and inventory-instance provenance."""
        application = self.reconciliation_application()
        enriched = guard_amt_snapshot(self.included_AMT_snapshot(amt_data))
        enrichment_signature = reconciliation_fingerprint(self.AMT_enrichment_request_signature()) if application else ""
        for footprint, rows in enriched.items():
            for row in rows or []:
                row = row or {}
                raw_amt_fields = flatten_available_source_fields(row)
                canonical = apply_field_mappings(
                    row,
                    vars(self).get("field_definitions"),
                    vars(self).get("field_mappings", []),
                    "amt",
                )
                row["defined_fields"] = canonical
                # Clearing a mapping must also clear a previous enrichment's
                # baseline; otherwise advanced refresh can reuse a stale grade.
                row.update(canonical)
                source_properties = {
                    key: value for key, value in canonical.items()
                    if value is not None
                }
                row["source_properties"] = source_properties
                strict_mappings = bool(
                    vars(self).get("field_definitions") is not None
                    or vars(self).get("field_mapping_schema_version", 0) >= 3
                )
                insitu = (
                    {
                        f"insitu_{analyte}": row.get(f"insitu_{analyte}")
                        for analyte in ANALYTES
                    }
                    if strict_mappings else {
                        "grade_fe": row.get("FE"),
                        "grade_si": row.get("SIO2"),
                        "grade_al": row.get("AL2O3"),
                        "grade_p": row.get("P"),
                        "grade_mn": row.get("MN"),
                    }
                )
                streams = amt_grade_streams(
                    insitu,
                    row if strict_mappings else {**raw_amt_fields, **row},
                    self.product_brand_labels_choice,
                    self.historical_recon_factors,
                    self.opf_input_choice,
                    strict_mappings=strict_mappings,
                )
                streams = self.apply_source_reconciliation(application, row, streams, footprint, "amt")
                if application:
                    row["reconciliation"]["enrichment_signature"] = enrichment_signature
                row["GRADE_STREAMS"] = streams
                row["grade_streams"] = streams
                self.sync_canonical_grade_fields(row, streams)
                if (
                    self.is_cloudbreak_site()
                    and str(vars(self).get(
                        "cb_lump_fines_mode", "derived"
                    ) or "derived") == "calculated"
                ):
                    # Calculated CB by-products are intentionally deferred until
                    # member hexes have been aggregated into scheduling chunks.
                    # This preserves partial-lineage weighting and validates the
                    # source at the same granularity used by the optimiser.
                    row["CB_SPLIT_METHOD"] = "calculated_at_amt_chunk_submission"
                    row["CB_SPLIT_WARNING"] = ""
                    cb_split_warning = ""
                else:
                    cb_split_warning = self.apply_cb_split_to_amt_row(row)
                inventory_name = str(row.get("FOOTPRINT") or footprint or "")
                inventory_build = str(row.get("LOCATION_NAME") or "")
                inventory_transaction_datetime = str(
                    row.get("INVENTORY_TRANSACTION_DATETIME") or ""
                )
                inventory_matched = bool(
                    inventory_name
                    and inventory_build
                    and row.get("INVENTORY_BALANCE_WMT") is not None
                )
                match_rule = (
                    "latest inventory build at or before scenario start"
                    if inventory_matched else "no inventory instance"
                )
                row["AMT_INVENTORY_MATCHED"] = inventory_matched
                row["AMT_INVENTORY_STOCKPILE"] = inventory_name
                row["AMT_INVENTORY_BUILD"] = inventory_build
                row["AMT_INVENTORY_TRANSACTION_DATETIME"] = (
                    inventory_transaction_datetime
                )
                row["AMT_INVENTORY_MATCH_RULE"] = match_rule
                lineage_warning = str(row.get("LINEAGE_WARNING") or "").strip()
                source_warnings = [lineage_warning] if lineage_warning else []
                source_warnings.extend(row.get("reconciliation", {}).get("warnings", []))
                if cb_split_warning:
                    source_warnings.append(cb_split_warning)
                product_slot = amt_modelled_product_slot(self.opf_input_choice)
                if product_slot and not is_dry_plant(self.opf_input_choice):
                    labels = {
                        "fe": "Fe", "si": "SiO₂", "al": "Al₂O₃",
                        "p": "P", "mn": "Mn",
                    }
                    for analyte in ANALYTES:
                        source_name = {"si": "SIO2", "al": "AL2O3"}.get(
                            analyte, analyte.upper()
                        )
                        coverage = numeric(raw_amt_fields.get(
                            f"MODELLED_{product_slot.upper()}_{source_name}_COVERAGE_PCT"
                        ))
                        if (numeric(row.get("FINAL_WMT")) or 0.0) <= 0:
                            continue
                        if coverage is None or coverage <= 0:
                            source_warnings.append(
                                f"{product_slot.upper()} {labels[analyte]} is unavailable; "
                                "the selected product stream will fall back for this analyte."
                            )
                        elif coverage < 99.999999:
                            source_warnings.append(
                                f"{product_slot.upper()} {labels[analyte]} covers "
                                f"{coverage:.2f}% of final hex WMT; the modelled grade uses "
                                "only covered lineage tonnes."
                            )
                row["GRADE_STREAM_WARNINGS"] = list(dict.fromkeys(
                    warning for warning in source_warnings if warning
                ))
                for warning in row["GRADE_STREAM_WARNINGS"]:
                    self.historical_recon_warnings.append(
                        f"{footprint}/{row.get('HEX', '')}: {warning}"
                    )
        self.historical_recon_warnings = list(dict.fromkeys(self.historical_recon_warnings))
        return compact_amt_stockpile_data(enriched)

    def refresh_AMT_map_data_from_database(self):
        draw_AMT_map = getattr(self, "draw_AMT_map", None)
        if draw_AMT_map is None:
            return

        # Canonical mappings are persisted at hex granularity. Fetch those
        # rows before rebuilding any already-generated chunk snapshots.
        draw_AMT_map.excluded_footprints = self.excluded_amt_footprints()
        draw_AMT_map.data = draw_AMT_map.fetch_data()
        self.reconcile_saved_AMT_chunk_grade_streams()
        draw_AMT_map.update_chunk_settings(copy.deepcopy(self.AMT_chunk_settings))
        draw_AMT_map.selected_points = copy.deepcopy(self.hex_sequence_table or [])
        draw_AMT_map.unique_footprints = draw_AMT_map.get_unique_footprints()
        draw_AMT_map.clean_up_hex_sequence_table()
        draw_AMT_map.update_sequence_counter()

    def AMT_chunk_reconciliation_request_signature(self):
        """Identify every input that can change a submitted AMT chunk."""
        chunks = (
            getattr(self, "hex_sequence_table", [])
            or getattr(self, "hex_sequence_table_argument", [])
            or []
        )
        membership = []
        for chunk in chunks:
            if not isinstance(chunk, dict):
                continue
            member_hexes = chunk.get("member_hexes") or []
            if isinstance(member_hexes, str):
                member_hexes = [
                    value.strip() for value in member_hexes.split(",")
                    if value.strip()
                ]
            membership.append({
                "footprint": str(chunk.get("footprint") or ""),
                "sequence": numeric(chunk.get("sequence")),
                "member_hexes": sorted(str(value) for value in member_hexes),
            })
        payload = {
            "version": AMT_CHUNK_RECONCILIATION_VERSION,
            "enrichment": self.AMT_enrichment_request_signature(),
            "membership": membership,
        }
        return json.dumps(
            payload, sort_keys=True, default=str, separators=(",", ":")
        )

    def reconcile_saved_AMT_chunk_grade_streams(self, force=False):
        """Refresh derived brand streams in saved AMT chunks.

        Projects saved before partial-lineage aggregation was corrected can
        contain a valid modelled product but a blank adjusted product. Chunk
        membership and modelled values remain authoritative; only the derived
        brand copies and historical reconciliation layers are rebuilt here.
        """
        self.prune_zeroed_amt_chunks()
        request_signature = self.AMT_chunk_reconciliation_request_signature()
        if (
            not force
            and str(vars(self).get(
                "AMT_chunk_reconciliation_signature", ""
            ) or "") == request_signature
        ):
            return 0

        brands = configured_brands(
            getattr(self, "product_brand_labels_choice", None)
        )
        if not brands:
            self.AMT_chunk_reconciliation_signature = request_signature
            return 0

        factors = getattr(self, "historical_recon_factors", None)
        opf = getattr(self, "opf_input_choice", None)
        application = self.reconciliation_application()
        enrichment_signature = reconciliation_fingerprint(self.AMT_enrichment_request_signature()) if application else ""
        refreshed = 0

        def first_vector(brand_map, brand=None):
            if not isinstance(brand_map, dict):
                return None
            candidates = []
            if brand:
                candidates.append(brand_map.get(brand))
            candidates.append(brand_map.get("*"))
            candidates.extend(brand_map.values())
            return next(
                (value for value in candidates if isinstance(value, dict)),
                None,
            )

        def reconcile_rows(rows):
            nonlocal refreshed
            result = list(rows or [])
            for chunk in result:
                if not isinstance(chunk, dict):
                    continue
                raw_streams = (
                    chunk.get("grade_streams")
                    or chunk.get("GRADE_STREAMS")
                )
                if not isinstance(raw_streams, dict):
                    continue
                audit = chunk.get("reconciliation") or {}
                if application and audit.get("enrichment_signature") == enrichment_signature:
                    # Current member-hex grades already carry the advanced
                    # adjustments. A global chunk factor would erase them.
                    continue
                streams = normalise_grade_streams(raw_streams)
                rom_by_brand = streams.setdefault("modelled_rom", {})
                base_rom = first_vector(rom_by_brand)
                product_by_brand = streams.setdefault(
                    "modelled_product", {}
                )

                for brand in brands:
                    if isinstance(base_rom, dict):
                        rom = copy.deepcopy(base_rom)
                        rom_by_brand[brand] = copy.deepcopy(rom)
                        adjusted_rom = {
                            analyte: (
                                numeric(rom.get(analyte))
                                * historical_factor(
                                    factors, brand, "blend", analyte
                                )
                                if numeric(rom.get(analyte)) is not None
                                else None
                            )
                            for analyte in ANALYTES
                        }
                        streams.setdefault("adjusted_rom", {})[
                            brand
                        ] = adjusted_rom
                    else:
                        adjusted_rom = None

                    if is_dry_plant(opf) and adjusted_rom is not None:
                        streams.setdefault("modelled_product", {})[
                            brand
                        ] = copy.deepcopy(adjusted_rom)
                        streams.setdefault("adjusted_product", {})[
                            brand
                        ] = copy.deepcopy(adjusted_rom)
                        continue

                    modelled_product = first_vector(product_by_brand, brand)
                    if not isinstance(modelled_product, dict):
                        continue
                    modelled_product = copy.deepcopy(modelled_product)
                    product_by_brand[brand] = copy.deepcopy(modelled_product)
                    streams.setdefault("adjusted_product", {})[brand] = {
                        analyte: (
                            numeric(modelled_product.get(analyte))
                            * historical_factor(
                                factors, brand, "regression", analyte
                            )
                            if numeric(modelled_product.get(analyte)) is not None
                            else None
                        )
                        for analyte in ANALYTES
                    }

                if application:
                    streams, audit = application.apply(
                        streams, source_id=str(chunk.get("hex") or chunk.get("footprint") or ""),
                        source_kind="amt", source_wmt=max(numeric(chunk.get("balance")) or 0.0, 0.0),
                        contributing_blocks=[], warnings=[
                            "Current member-hex reconciliation is unavailable; this chunk uses global factors."
                        ],
                    )
                    audit["source_kind"] = "amt_chunk"
                    chunk["reconciliation"] = audit
                else:
                    chunk.pop("reconciliation", None)
                chunk["grade_streams"] = streams
                chunk["GRADE_STREAMS"] = streams
                refreshed += 1
            return result

        draw_amt = vars(self).get("draw_AMT_map")
        draw_data = getattr(draw_amt, "data", None) if draw_amt is not None else None
        can_rebuild = (
            draw_amt is not None
            and hasattr(draw_amt, "rebuild_saved_chunk_records")
            and isinstance(draw_data, pd.DataFrame)
            and not draw_data.empty
        )
        canonical_rows = (
            getattr(self, "hex_sequence_table", [])
            or getattr(self, "hex_sequence_table_argument", [])
            or []
        )
        expected_rebuilds = sum(
            1 for row in canonical_rows
            if isinstance(row, dict) and bool(row.get("member_hexes"))
        )
        rebuild_complete = expected_rebuilds == 0
        if can_rebuild:
            canonical_rows, rebuilt_count = (
                draw_amt.rebuild_saved_chunk_records(canonical_rows)
            )
            refreshed += rebuilt_count
            rebuild_complete = rebuilt_count >= expected_rebuilds
        canonical_rows = reconcile_rows(canonical_rows)
        self.hex_sequence_table = canonical_rows

        # Rebuilding a chunk from its member hexes necessarily restores the
        # raw/mapped hex lump and fines properties.  In calculated CB mode the
        # scheduling source is the chunk, so immediately replace those raw
        # values with the user-percentage split before Database View, solver,
        # project load, or reports consume the rebuilt snapshot.
        if (
            self.is_cloudbreak_site()
            and str(
                vars(self).get("cb_lump_fines_mode", "derived") or "derived"
            ) == "calculated"
        ):
            self.apply_cb_split_to_amt_chunks(self.hex_sequence_table)
        # The argument table is a solver-boundary snapshot of the one
        # canonical chunk table. It must not be independently rebuilt.
        self.hex_sequence_table_argument = copy.deepcopy(
            self.hex_sequence_table
        )
        if rebuild_complete or not self.hex_sequence_table:
            self.AMT_chunk_reconciliation_signature = request_signature
        return refreshed

    def get_AMT_stockpile_data(self, builds):
        data_source = self.selected_AMT_data_source()
        if data_source:
            self.AMT_stockpile_data = self.opening_stockpile_inventories.call_opening_AMT_stockpile_inventories(
                [row["build"] for row in data_source.values()], self.start_time_choice,
            )
        else:
            self.AMT_stockpile_data = {}
            self.opening_stockpile_inventories.clear_AMT_stockpile_database()

    def handle_AMT_submit_clicked(self, _checked=False):
        """Ignore QPushButton.checked and always advance to Database View."""
        return self.store_hex_sequence_table(navigate=True)

    def store_hex_sequence_table(self, navigate=True):
        try:
            self.validate_AMT_participation()
        except ValueError as exc:
            QMessageBox.warning(self, "AMT Stockpiles", str(exc))
            return False
        self.prune_zeroed_amt_chunks()
        if not self.store_AMT_chunk_settings():
            return

        draw = vars(self).get("draw_AMT_map")
        candidate_chunks = copy.deepcopy(draw.return_hex_sequence() or []) if draw is not None else copy.deepcopy(vars(self).get("hex_sequence_table") or [])

        if any(not isinstance(item, dict) for item in candidate_chunks):
            QMessageBox.warning(
                self,
                "BlendMaster",
                "Invalid entries detected!\nPlease regenerate chunks for the "
                "selected AMT stockpiles.",
            )
            return False

        selected_footprints = self.selected_amt_footprints()
        zeroed = zeroed_amt_footprints(vars(self).get("AMT_stockpile_data")) | self.excluded_amt_footprints()
        candidate_chunks = [row for row in candidate_chunks if self.amt_chunk_footprint(row) not in zeroed]
        chunk_footprints = {
            self.amt_chunk_footprint(chunk)
            for chunk in candidate_chunks
            if self.amt_chunk_footprint(chunk)
        }
        missing_footprints = sorted(
            selected_footprints - chunk_footprints
        )
        if missing_footprints:
            QMessageBox.warning(
                self,
                "AMT Stockpiles",
                "No submitted AMT chunks were found for: "
                + ", ".join(missing_footprints)
                + ". Regenerate or resubmit these footprints before continuing.",
            )
            return False

        self.hex_sequence_table = candidate_chunks

        if not any(not isinstance(item, dict) for item in self.hex_sequence_table):
            try:
                # AMT calculated by-products belong to the scheduling source,
                # which is the submitted chunk rather than each underlying hex.
                self.apply_cb_split_to_amt_chunks(self.hex_sequence_table)
            except ValueError as exc:
                QMessageBox.warning(self, "AMT Stockpiles", str(exc))
                return False
            self.hex_sequence_table_argument = copy.deepcopy(self.hex_sequence_table)
            self.total_AMT_stockpile_balances = {}
            self.populate_total_AMT_stockpile_balances()
            self.save_active_scenario_state()
            self.set_page_enabled(self.database_view_tab_index, True)
            self.database_view_refresh_pending = True
            if navigate:
                self.open_database_view()
            return True
        else:
            QMessageBox.warning(self, "BlendMaster", "Invalid entries detected!\nPlease regenerate chunks for the selected AMT stockpiles.")
            return False
    
    def populate_total_AMT_stockpile_balances(self):
        self.prune_excluded_AMT_state()
        # Extract unique footprints from the hex sequence table
        unique_footprints = set(hex_entry.get('footprint') for hex_entry in self.hex_sequence_table if 'footprint' in hex_entry)

        # Calculate the total balance for each unique footprint
        for footprint in unique_footprints:
            filtered_hexes = [
                hex_entry for hex_entry in self.hex_sequence_table
                if hex_entry.get('footprint') == footprint
            ]
            total_balance = sum(max(float(hex_entry.get('balance', 0) or 0), 0) for hex_entry in filtered_hexes)
            self.total_AMT_stockpile_balances[footprint] = total_balance
        
    def planning_period_count(self):
        if hasattr(self, "planning_period_count_input"):
            return PeriodManager.normalize_period_count(
                self.planning_period_count_input.value()
            )
        return PeriodManager.normalize_period_count(
            getattr(self, "planning_period_count_choice", 3)
        )

    def planning_period_labels(self):
        return PeriodManager.period_labels_for_count(
            self.planning_period_count()
        )

    def setup_calendar(self):
        """Setup for the main table with a Submit button."""
            
        period_labels = self.planning_period_labels()
        period_count = len(period_labels)
        self.calendar_headers = ["", *period_labels]
        self.calendar_rows = []

        # Static Rows with default values of 0
        direct_tip_enabled = self.is_direct_tip_enabled()
        direct_tip_editables = [direct_tip_enabled] * period_count
        direct_tip_max_defaults = ["1"] * period_count if direct_tip_enabled else ["0"] * period_count
        stockpile_reclaim_rates = self.is_total_feed_operating_crusher()
        reclaim_rate_editables = [not stockpile_reclaim_rates] * period_count
        reclaim_rate_defaults = (
            ["Per stockpile"] * period_count
            if stockpile_reclaim_rates
            else ["1000"] * period_count
        )
        configured_calendar_brands = configured_brands(self.product_brand_labels_choice)
        calendar_brand_default = configured_calendar_brands[0] if configured_calendar_brands else ""

        self.calendar_rows.extend([
            ("Reclaim Equipment", [False] * period_count, "green", [""] * period_count),
            {"reclaim_equipment_max_reclaim_rate": (
                "  Max Reclaim Rate",
                reclaim_rate_editables,
                "green",
                reclaim_rate_defaults,
            )},

            ("Crusher", [False] * period_count, "blue", [""] * period_count),
            {"crusher_brand": ("  Brand", [True] * period_count, "blue", [calendar_brand_default] * period_count)},
            {"crusher_rate": ("  Rate", [True] * period_count, "blue", ["1000"] * period_count)},
            ("  Direct Tip Ratio", [False] * period_count, "blue", [""] * period_count),
            {"crusher_direct_tip_ratio_min": ("    Min", direct_tip_editables, "blue", ["0"] * period_count)},
            {"crusher_direct_tip_ratio_max": ("    Max", direct_tip_editables, "blue", direct_tip_max_defaults)},

            ("  Target", [False] * period_count, "blue", [""] * period_count),
            ("    Fe", [False] * period_count, "blue", [""] * period_count),
            {"crusher_target_fe_min": ("      Min", [True] * period_count, "blue", ["0"] * period_count)},
            {"crusher_target_fe_max": ("      Max", [True] * period_count, "blue", ["100"] * period_count)},

            ("    Si", [False] * period_count, "blue", [""] * period_count),
            {"crusher_target_si_min": ("      Min", [True] * period_count, "blue", ["0"] * period_count)},
            {"crusher_target_si_max": ("      Max", [True] * period_count, "blue", ["100"] * period_count)},

            ("    Al", [False] * period_count, "blue", [""] * period_count),
            {"crusher_target_al_min": ("      Min", [True] * period_count, "blue", ["0"] * period_count)},
            {"crusher_target_al_max": ("      Max", [True] * period_count, "blue", ["100"] * period_count)},

            ("    P", [False] * period_count, "blue", [""] * period_count),
            {"crusher_target_p_min": ("      Min", [True] * period_count, "blue", ["0"] * period_count)},
            {"crusher_target_p_max": ("      Max", [True] * period_count, "blue", ["100"] * period_count)},

            ("    Mn", [False] * period_count, "blue", [""] * period_count),
            {"crusher_target_mn_min": ("      Min", [True] * period_count, "blue", ["0"] * period_count)},
            {"crusher_target_mn_max": ("      Max", [True] * period_count, "blue", ["100"] * period_count)},
        ])

        custom_constraints = [
            definition
            for definition in self.normalized_solver_config().get(
                "custom_constraints", []
            )
            if definition.get("enabled", True)
        ]
        if custom_constraints:
            self.calendar_rows.append((
                "  Custom Constraints",
                [False] * period_count,
                "blue",
                [""] * period_count,
            ))
            for definition in custom_constraints:
                key = constraint_key(definition.get("key") or definition.get("name"))
                min_key = f"crusher_custom_constraint_{key}_min"
                max_key = f"crusher_custom_constraint_{key}_max"
                saved_min = (self.calendar_inputs or {}).get(min_key, {})
                saved_max = (self.calendar_inputs or {}).get(max_key, {})
                self.calendar_rows.extend([
                    (
                        f"    {definition.get('name') or key}",
                        [False] * period_count,
                        "blue",
                        [""] * period_count,
                    ),
                    {
                        min_key: (
                            "      Min",
                            [True] * period_count,
                            "blue",
                            [saved_min.get(label, "") for label in period_labels],
                        )
                    },
                    {
                        max_key: (
                            "      Max",
                            [True] * period_count,
                            "blue",
                            [saved_max.get(label, "") for label in period_labels],
                        )
                    },
                ])

        self.calendar_expit_material_brand_rows = {}
        try:
            expit_material_types = (
                ExpitDataHandler.distinct_expit_material_types(
                    getattr(self, "file_path_24hr_choice", "")
                )
                if getattr(self, "file_path_24hr_choice", "") else []
            )
        except Exception as error:
            expit_material_types = []
            print(
                "Unable to read APS material types for Calendar: "
                f"{error}"
            )
        if expit_material_types and configured_calendar_brands:
            self.calendar_rows.append((
                "  Expit Material Type → Product Brand Incentive ($/t)",
                [False] * period_count,
                "blue",
                [""] * period_count,
            ))
            for material_type in expit_material_types:
                for brand in configured_calendar_brands:
                    key = (
                        "crusher_expit_material_brand_incentive_"
                        f"{constraint_key(material_type)}_"
                        f"{constraint_key(brand)}"
                    )
                    self.calendar_expit_material_brand_rows[key] = {
                        "material_type": material_type,
                        "brand": brand,
                    }
                    saved = (self.calendar_inputs or {}).get(key, {})
                    self.calendar_rows.append({
                        key: (
                            f"    {material_type} → {brand}",
                            [True] * period_count,
                            "blue",
                            [saved.get(label, 0) for label in period_labels],
                        )
                    })

        # Dynamically Add Stockpile Rows with default values
        self.calendar_rows.append(("Stockpiles", [False] * period_count, "red", [""] * period_count))
        self.calendar_stockpile_start_index = len(self.calendar_rows)

        selected_stockpiles = list(getattr(self, "updated_stockpile_data_keys", []) or [])
        selected_stockpile_keys = {str(stockpile).strip().upper() for stockpile in selected_stockpiles}
        aps_destination_stockpiles = []
        if getattr(self, "file_path_choice", None):
            try:
                aps_destination_stockpiles = ExpitDataHandler.get_distinct_stockpile_destinations(
                    self.file_path_choice
                )
            except Exception as error:
                print(f"Unable to read APS destination stockpiles for Calendar: {error}")

        self.calendar_build_only_stockpiles = {
            str(stockpile).strip().upper()
            for stockpile in aps_destination_stockpiles
            if str(stockpile).strip().upper() not in selected_stockpile_keys
        }
        self.calendar_stockpile_names = selected_stockpiles + [
            stockpile
            for stockpile in aps_destination_stockpiles
            if str(stockpile).strip().upper() not in selected_stockpile_keys
        ]

        for stockpile in self.calendar_stockpile_names:
            default_state = (
                "Build"
                if str(stockpile).strip().upper() in self.calendar_build_only_stockpiles
                else "Auto"
            )
            self.calendar_rows.append({f"stockpiles_{stockpile.lower()}" : (f"  {stockpile}", [False] * period_count, "red", [""] * period_count)})
            self.calendar_rows.append({f"stockpiles_{stockpile.lower()}_state" : (f"    State", [True] * period_count, "red", [default_state] * period_count)})
            self.calendar_rows.append({f"stockpiles_{stockpile.lower()}_maximum_quantity": (f"    Maximum Quantity", [True] * period_count, "red", ["100000"] * period_count)})

        self.populate_calendar()
       
        if self.setup_calendar_first_call:
            # Add Submit Button at bottom-Right
            submit_button = QPushButton("Submit")
            submit_button.clicked.connect(self.store_calendar_inputs)  # Connect to store_calendar_inputs method

            # Align button to bottom-right
            button_layout = QHBoxLayout()
            
            button_layout.addWidget(submit_button) 
            button_layout.addStretch()  # Push any other content (if any) to the right

            # Add table and button layout to the main tab layout
            self.main_tab_layout.addLayout(button_layout)
            self.setup_calendar_first_call = False
        
        self.load_calendar_inputs()
        self.calendar_table_refresh_pending = False
    
    def populate_calendar(self):
        # Define Parent Colors
        parent_colors = {
            "green": QColor("#e5f7ed"),
            "blue": QColor("#e8f0ff"),
            "red": QColor("#ffe7ea"),
        }
        section_colors = {
            "green": QColor("#c8f0d6"),
            "blue": QColor("#d7e4ff"),
            "red": QColor("#ffd3da"),
        }
        section_foreground = {
            "green": QColor("#14532d"),
            "blue": QColor("#1e3a8a"),
            "red": QColor("#7f1d1d"),
        }

        # Rebuilding the Calendar can insert or remove dynamic custom-constraint
        # rows ahead of the stockpile rows.  Drop the old rows first so Qt also
        # removes their cell widgets; otherwise an old stockpile State combo can
        # remain painted over a newly inserted numeric Min/Max cell.
        self.main_table.setRowCount(0)
        self.main_table.setColumnCount(0)

        # Configure the main table
        self.main_table.setColumnCount(len(self.calendar_headers))
        self.main_table.setRowCount(len(self.calendar_rows))
        self.main_table.setHorizontalHeaderLabels(self.calendar_headers)
        self.main_table.verticalHeader().setVisible(False)
        self.main_table.setAlternatingRowColors(True)
        self.main_table.setSelectionBehavior(QAbstractItemView.SelectItems)
        self.main_table.setSelectionMode(QAbstractItemView.ExtendedSelection)
        self.main_table.setShowGrid(True)
        self.main_table.setStyleSheet("""
            QTableWidget {
                background-color: #ffffff;
                alternate-background-color: #f8fafc;
                gridline-color: #d8e0ea;
                border: 1px solid #d8e0ea;
                border-radius: 6px;
                selection-background-color: #bfdbfe;
                selection-color: #0f172a;
            }
            QHeaderView::section {
                background-color: #f1f5f9;
                color: #172033;
                font-weight: 700;
                border: 0;
                border-right: 1px solid #d8e0ea;
                border-bottom: 1px solid #cbd5e1;
                padding: 7px 8px;
            }
            QTableWidget::item {
                padding: 5px 8px;
            }
            QComboBox {
                background-color: #ffffff;
                border: 1px solid #cbd5e1;
                border-radius: 4px;
                padding: 3px 8px;
            }
        """)

        # Bold Font for Captions
        bold_font = QFont()
        bold_font.setBold(True)

        # Populate Table
        for row_idx, row in enumerate(self.calendar_rows):
            row_key = None
            if isinstance(row, tuple):  # Unpack tuples
                caption, editables, color_group, default_values = row
                # Process the tuple as needed
            elif isinstance(row, dict):  # Handle dictionaries
                for key, value in row.items():
                    row_key = key
                    caption, editables, color_group, default_values = value
                    # Process the dictionary value (tuple) as needed
            is_section_row = not any(editables)
            
            # Caption Column
            item_caption = QTableWidgetItem(caption)
            item_caption.setFlags(Qt.ItemIsEnabled)  # Non-editable
            item_caption.setFont(bold_font)
            item_caption.setForeground(QBrush(section_foreground[color_group]))
            item_caption.setBackground(QBrush(
                section_colors[color_group] if is_section_row else parent_colors[color_group]
            ))
            if row_key:
                item_caption.setData(Qt.UserRole, row_key)
            if (
                row_key == "reclaim_equipment_max_reclaim_rate"
                and self.is_total_feed_operating_crusher()
            ):
                item_caption.setToolTip(
                    "Total_Feed scenarios use Max Reclaim Rate from each "
                    "Stockpile Inventories footprint."
                )
            self.main_table.setItem(row_idx, 0, item_caption)

            # Editable and Non-Editable Cells with Default Values
            for col_idx, (is_editable, default_value) in enumerate(zip(editables, default_values), start=1):
                if row_key == "crusher_brand":
                    brand_combo = QComboBox()
                    brand_combo.setProperty("useCurrentData", True)
                    if self.product_targets:
                        brand_combo.addItem("From Product Build", "")
                        brand_combo.setEnabled(False)
                    else:
                        for brand in configured_brands(self.product_brand_labels_choice):
                            brand_combo.addItem(brand, brand)
                        brand_index = brand_combo.findData(str(default_value or "").strip().upper())
                        brand_combo.setCurrentIndex(max(brand_index, 0))
                    self.main_table.setCellWidget(row_idx, col_idx, brand_combo)
                    continue
                if is_editable and self.is_calendar_stockpile_state_row(row_key):
                    state_combo = QComboBox()
                    state_options = ["Auto", "Build", "Reclaim"]
                    state_value = str(default_value)
                    if state_value not in state_options:
                        state_options.append(state_value)
                    state_combo.addItems(state_options)
                    state_combo.setCurrentText(state_value)
                    state_combo.setStyleSheet("QComboBox { qproperty-alignment: AlignCenter; }")
                    self.main_table.setCellWidget(row_idx, col_idx, state_combo)
                    continue

                display_value = default_value
                if row_key and (
                    "_target_" in row_key
                    or row_key.startswith("crusher_custom_constraint_")
                    or row_key.endswith("_maximum_quantity")
                ):
                    try:
                        display_value = f"{float(default_value):.2f}"
                    except (TypeError, ValueError):
                        pass
                item = QTableWidgetItem(str(display_value))
                item.setTextAlignment(Qt.AlignCenter)  # Center align all values
                if not is_editable:
                    item.setFlags(Qt.ItemIsEnabled)  # Non-editable
                    item.setBackground(QBrush(
                        section_colors[color_group] if is_section_row else QColor("#eef2f7")
                    ))
                    if (
                        row_key == "reclaim_equipment_max_reclaim_rate"
                        and self.is_total_feed_operating_crusher()
                    ):
                        item.setToolTip(
                            "Configured per footprint in Stockpile Inventories."
                        )
                    if is_section_row:
                        item.setFont(bold_font)
                else:
                    item.setBackground(QBrush(QColor("#ffffff")))
                self.main_table.setItem(row_idx, col_idx, item)
            self.main_table.setRowHeight(row_idx, 30)

        # Resize Columns
        self.main_table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        self.main_table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeToContents)
        self.main_table.setColumnWidth(0, max(260, self.main_table.columnWidth(0)))

    @staticmethod
    def is_calendar_stockpile_state_row(row_key):
        """Return whether a Calendar key represents a stockpile State row."""
        key = str(row_key or "").strip().lower()
        return key.startswith("stockpiles_") and key.endswith("_state")

    def load_calendar_inputs(self):
        if self.calendar_inputs:
            if self.calendar_inputs.get("min_stockpiles") is not None:
                self.min_stockpiles = self.calendar_inputs["min_stockpiles"]
            if self.calendar_inputs.get("max_stockpiles") is not None:
                self.max_stockpiles = self.calendar_inputs["max_stockpiles"]
            if self.calendar_inputs.get("min_stockpile_contribution_ratio") is not None:
                self.min_stockpile_contribution_ratio = self.calendar_inputs["min_stockpile_contribution_ratio"]
            self.solver_config = self.normalized_solver_config(
                self.calendar_inputs.get("solver_config", self.solver_config)
            )
            self.load_solver_config_inputs()

        if self.is_project_loaded or not self.submit_calendar_first_call:
            period_count = len(self.calendar_headers) - 1
            period_labels = self.calendar_headers[1:]
            def calendar_values(key, defaults, fallback_key=None):
                saved_values = self.calendar_inputs.get(key, {}) if self.calendar_inputs else {}
                if not saved_values and fallback_key:
                    saved_values = self.calendar_inputs.get(fallback_key, {}) if self.calendar_inputs else {}
                return [
                    saved_values.get(header, defaults.get(header))
                    for header in self.calendar_headers[1:]
                ]
            
            zero_defaults = {period: 0 for period in period_labels}
            one_defaults = {period: 1 for period in period_labels}
            hundred_defaults = {period: 100 for period in period_labels}
            thousand_defaults = {period: 1000 for period in period_labels}
            direct_tip_enabled = self.is_direct_tip_enabled()
            direct_tip_editables = [direct_tip_enabled] * period_count
            direct_tip_min_values = (
                calendar_values("crusher_direct_tip_ratio_min", zero_defaults, "crusher_direct_feed_ratio_min")
                if direct_tip_enabled
                else [0] * period_count
            )
            direct_tip_max_values = (
                calendar_values("crusher_direct_tip_ratio_max", one_defaults, "crusher_direct_feed_ratio_max")
                if direct_tip_enabled
                else [0] * period_count
            )

            stockpile_reclaim_rates = self.is_total_feed_operating_crusher()
            self.calendar_rows[1]["reclaim_equipment_max_reclaim_rate"] = (
                "  Max Reclaim Rate",
                [not stockpile_reclaim_rates] * period_count,
                "green",
                (
                    ["Per stockpile"] * period_count
                    if stockpile_reclaim_rates
                    else calendar_values(
                        "reclaim_equipment_max_reclaim_rate",
                        thousand_defaults,
                    )
                ),
            )
            brand_defaults = {
                period: (configured_brands(self.product_brand_labels_choice) or [""])[0]
                for period in period_labels
            }
            self.calendar_rows[3]["crusher_brand"] = (
                "  Brand", [True] * period_count, "blue",
                calendar_values("crusher_brand", brand_defaults),
            )
            self.calendar_rows[4]["crusher_rate"] = ("  Rate", [True] * period_count, "blue", calendar_values("crusher_rate", thousand_defaults))
            self.calendar_rows[6]["crusher_direct_tip_ratio_min"] = ("    Min", direct_tip_editables, "blue", direct_tip_min_values)
            self.calendar_rows[7]["crusher_direct_tip_ratio_max"] = ("    Max", direct_tip_editables, "blue", direct_tip_max_values)
            self.calendar_rows[10]["crusher_target_fe_min"] = ("      Min", [True] * period_count, "blue", calendar_values("crusher_target_fe_min", zero_defaults))
            self.calendar_rows[11]["crusher_target_fe_max"] = ("      Max", [True] * period_count, "blue", calendar_values("crusher_target_fe_max", hundred_defaults))
            self.calendar_rows[13]["crusher_target_si_min"] = ("      Min", [True] * period_count, "blue", calendar_values("crusher_target_si_min", zero_defaults))
            self.calendar_rows[14]["crusher_target_si_max"] = ("      Max", [True] * period_count, "blue", calendar_values("crusher_target_si_max", hundred_defaults))
            self.calendar_rows[16]["crusher_target_al_min"] = ("      Min", [True] * period_count, "blue", calendar_values("crusher_target_al_min", zero_defaults))
            self.calendar_rows[17]["crusher_target_al_max"] = ("      Max", [True] * period_count, "blue", calendar_values("crusher_target_al_max", hundred_defaults))
            self.calendar_rows[19]["crusher_target_p_min"] = ("      Min", [True] * period_count, "blue", calendar_values("crusher_target_p_min", zero_defaults))
            self.calendar_rows[20]["crusher_target_p_max"] = ("      Max", [True] * period_count, "blue", calendar_values("crusher_target_p_max", hundred_defaults))
            self.calendar_rows[22]["crusher_target_mn_min"] = ("      Min", [True] * period_count, "blue", calendar_values("crusher_target_mn_min", zero_defaults))
            self.calendar_rows[23]["crusher_target_mn_max"] = ("      Max", [True] * period_count, "blue", calendar_values("crusher_target_mn_max", hundred_defaults))

            
            start_index = getattr(
                self, "calendar_stockpile_start_index", 25
            )
            calendar_index = start_index  # Start populating calendar_rows after the static crusher rows

            for stockpile in getattr(self, "calendar_stockpile_names", self.updated_stockpile_data_keys):
                default_state = (
                    "Build"
                    if str(stockpile).strip().upper() in getattr(self, "calendar_build_only_stockpiles", set())
                    else "Auto"
                )
                # Populate the rows using calendar_index
                self.calendar_rows[calendar_index][f"stockpiles_{stockpile.lower()}"] = (
                    f"  {stockpile}", [False] * period_count, "red", [""] * period_count
                )
                self.calendar_rows[calendar_index + 1][f"stockpiles_{stockpile.lower()}_state"] = (
                    f"    State", [True] * period_count, "red",
                    calendar_values(
                        f"stockpiles_{stockpile.lower()}_state",
                        {header: default_state for header in self.calendar_headers[1:]},
                    )
                )
                self.calendar_rows[calendar_index + 2][f"stockpiles_{stockpile.lower()}_maximum_quantity"] = (
                    f"    Maximum Quantity", [True] * period_count, "red",
                    calendar_values(
                        f"stockpiles_{stockpile.lower()}_maximum_quantity",
                        {header: 100000 for header in self.calendar_headers[1:]},
                    )
                )
                calendar_index += 3
                    
            self.populate_calendar()
            self.store_calendar_inputs_no_run()

    def get_main_table_cell_text(self, row_idx, col_idx):
        widget = self.main_table.cellWidget(row_idx, col_idx)
        if isinstance(widget, QComboBox):
            if widget.property("useCurrentData"):
                return str(widget.currentData() or "").strip()
            return widget.currentText().strip()

        item = self.main_table.item(row_idx, col_idx)
        return item.text().strip() if item and item.text().strip() else None

    @staticmethod
    def normalized_calendar_input_value(outer_key, value):
        if value is None or "state" in str(outer_key).lower():
            return value
        try:
            return float(value)
        except (TypeError, ValueError):
            return value

    def store_calendar_inputs_no_run(self):
        """Extract and store user entries from the table into a structured format with concatenated keys and modified types. Also calls the main optimised run"""

        self.submit_calendar_first_call = False
        
        self.calendar_inputs = {}

        # Connect the error signal to a popup display method
        self.run_program.case_bridge.error_signal.connect(self.show_error_popup)
        
        # Capture column headers for periods
        headers = [self.main_table.horizontalHeaderItem(col).text().strip() for col in range(1, self.main_table.columnCount())]

        # A stack to track the current hierarchy
        hierarchy = []

        for row_idx in range(self.main_table.rowCount()):
            # Get the caption for the row (e.g., "Crusher", "  Rate")
            caption_item = self.main_table.item(row_idx, 0)
            if not caption_item:
                continue  # Skip if no caption exists (shouldn't happen)

            caption = caption_item.text()

            # Adjust hierarchy based on indentation
            indent_level = (len(caption) - len(caption.lstrip()))/2
            while len(hierarchy) > indent_level:
                hierarchy.pop()

            # Add the current name to the hierarchy
            current_name = caption.strip().replace(" ", "_").lower()
            hierarchy.append(current_name)

            # Dictionary rows carry stable keys so renaming a displayed custom
            # constraint does not orphan its saved Calendar values.
            explicit_key = caption_item.data(Qt.UserRole)
            full_key = str(explicit_key) if explicit_key else "_".join(hierarchy)

            # Retrieve the values for Preplan, Period_1, Period_2, etc.
            row_data = {}
            for col_idx, header in enumerate(headers, start=1):
                value = self.get_main_table_cell_text(row_idx, col_idx)
                row_data[header] = value

            # Store the data in the dictionary
            self.calendar_inputs[full_key] = row_data

        # Modify types
        self.calendar_inputs = {
            outer_key: {
                inner_key: (
                    self.normalized_calendar_input_value(
                        outer_key, inner_value
                    )
                )
                for inner_key, inner_value in outer_value.items()
            }
            for outer_key, outer_value in self.calendar_inputs.items()
        }

        # Calendar Cash is retained in the project schema for compatibility,
        # but it is no longer a user input or an optimisation objective term.
        zero_cash = {header: 0.0 for header in headers}
        for stockpile in getattr(self, "calendar_stockpile_names", []):
            self.calendar_inputs[
                f"stockpiles_{str(stockpile).lower()}_cash"
            ] = copy.deepcopy(zero_cash)

        self.store_stockpile_constraint_inputs()
        self.calendar_inputs["planning_period_count"] = self.planning_period_count()
        self.calendar_inputs = migrate_product_target_state(self.calendar_inputs or {})
        self.calendar_inputs["product_targets"] = copy.deepcopy(getattr(self, "product_targets", []))
        self.calendar_inputs["product_brand_labels"] = copy.deepcopy(self.product_brand_options())
        self.calendar_inputs["expit_material_brand_pairs"] = copy.deepcopy(
            getattr(self, "calendar_expit_material_brand_rows", {})
        )

