    def available_optimisation_plan_rows(self):
        fallback_count = int(
            self.normalized_solver_config().get(
                "contingency_plan_count", 0
            ) or 0
        )
        fallback = [{
            "plan_id": (
                "Primary" if index == 0 else f"Contingency {index}"
            ),
            "plan_rank": index,
            "status": "not run",
            "message": "",
        } for index in range(fallback_count + 1)]
        connection = sqlite3.connect(get_database_path())
        try:
            return pd.read_sql(
                """
                SELECT plan_id, plan_rank, status, message
                FROM optimisation_plan_status
                ORDER BY plan_rank
                """,
                connection,
            ).to_dict(orient="records")
        except (sqlite3.Error, pd.errors.DatabaseError):
            return fallback
        finally:
            connection.close()

    def refresh_optimisation_plan_selectors(self):
        rows = self.available_optimisation_plan_rows()
        plan_ids = [str(row["plan_id"]) for row in rows]
        for selector_name in (
            "optimisation_plan_selector",
            "manual_plan_selector",
        ):
            selector = getattr(self, selector_name, None)
            if selector is None:
                continue
            current = selector.currentText()
            selector.blockSignals(True)
            selector.clear()
            selector.addItems(plan_ids)
            if current in plan_ids:
                selector.setCurrentText(current)
            elif plan_ids:
                selector.setCurrentIndex(0)
            selector.blockSignals(False)
        self.handle_optimisation_plan_selection()

    def selected_optimisation_plan_id(self):
        selector = getattr(self, "optimisation_plan_selector", None)
        return (
            selector.currentText().strip()
            if selector is not None and selector.currentText().strip()
            else "Primary"
        )

    def handle_optimisation_plan_selection(self):
        selector = getattr(self, "optimisation_plan_selector", None)
        preview = getattr(self, "optimisation_plan_preview", None)
        if selector is None or preview is None:
            return
        plan_id = self.selected_optimisation_plan_id()
        rows = self.available_optimisation_plan_rows()
        status = next(
            (
                row for row in rows
                if str(row.get("plan_id")) == plan_id
            ),
            {},
        )
        self.optimisation_plan_status_label.setText(
            f"{status.get('status', '')}: {status.get('message', '')}".strip(
                ": "
            )
        )
        chart = getattr(self, "draw_gantt_chart", None)
        if chart is not None:
            chart.set_plan_id(plan_id)
            chart.set_report_configuration(
                getattr(self, "optimisation_detail_selected_columns", None),
                getattr(self, "optimisation_detail_column_aliases", {}),
                getattr(self, "optimisation_detail_column_widths", {}),
                getattr(self, "optimisation_detail_wrap_text", True),
            )
        report = self.fetch_optimised_blend_report(plan_id)
        self.populate_optimisation_plan_preview(report)

    @staticmethod
    def default_optimisation_snapshot_columns(columns):
        """Return a compact, useful opening view of the report snapshot."""
        preferred = [
            "start_datetime", "end_datetime", "steady_state_number",
            "blend_ID", "source", "source_id", "source_type",
            "source_opening_balance", "source_actual_tonnes",
            "source_closing_balance", "source_blend_ratio",
            "selected_grade_stream", "selected_grade_brand",
            "source_grade_fe", "source_grade_si", "source_grade_al",
            "source_grade_p", "source_grade_mn",
        ]
        available = set(columns) if columns is not None else set()
        return [column for column in preferred if column in available]

    def optimisation_snapshot_columns(self, report):
        # ``DataFrame.columns`` is a pandas Index and intentionally has no
        # truth value. Project loading refreshes this preview immediately, so
        # do not use ``or []`` here.
        columns = self.optimisation_snapshot_available_columns(report)
        selected = getattr(self, "optimisation_snapshot_selected_columns", None)
        if selected is None:
            selected = self.default_optimisation_snapshot_columns(columns)
            self.optimisation_snapshot_selected_columns = list(selected)
        else:
            # Keep saved user choices, but add newly introduced useful fields
            # when a newer report schema is opened.
            known = set(getattr(self, "optimisation_snapshot_known_columns", []) or [])
            selected = [column for column in selected if column in columns]
            selected.extend(
                column for column in self.default_optimisation_snapshot_columns(columns)
                if column not in known and column not in selected
            )
            self.optimisation_snapshot_selected_columns = list(
                dict.fromkeys(selected)
            )
        self.optimisation_snapshot_known_columns = list(columns)
        return [
            column for column in columns
            if column in set(self.optimisation_snapshot_selected_columns or [])
        ]

    @staticmethod
    def optimisation_snapshot_available_columns(report):
        """Remove compatibility aliases that duplicate clearer report fields."""
        columns = list(getattr(report, "columns", []))
        available = set(columns)
        result = []
        for column in columns:
            name = str(column)
            if name.endswith("_actual_depletion"):
                continue
            if name.startswith("source_property_source_wmt"):
                continue
            if name.startswith("custom_constraint_") and name.endswith(
                "_source_numerator"
            ):
                replacement = name + "_coefficient"
                if replacement in available:
                    continue
            if name.startswith("custom_constraint_") and name.endswith(
                "_source_denominator"
            ):
                replacement = name + "_coefficient"
                if replacement in available:
                    continue
            result.append(column)
        return balance_triplet_columns(result)

    def optimisation_snapshot_is_additive_field(self, column):
        key = canonical_property_key(column)
        if source_property_kind(
            key, getattr(self, "source_property_kinds", {})
        ) == "additive":
            return True
        return (
            key.endswith(("_tonnes", "_wmt", "_dmt", "_mass", "_volume"))
            or "tonnes" in key
            or key.endswith("_balance")
            or key in {"payload", "crusher_actual_tonnes"}
        )

    def format_optimisation_snapshot_value(self, column, value):
        if value is None or pd.isna(value):
            return ""
        numeric_value = numeric(value)
        if numeric_value is None:
            return str(value)
        key = canonical_property_key(column)
        if self.optimisation_snapshot_is_additive_field(key):
            return f"{numeric_value:,.0f}"
        if key.endswith(("_count", "_number", "_option", "_sequence")):
            return f"{numeric_value:,.0f}"
        return f"{numeric_value:.2f}"

    def optimisation_snapshot_column_label(self, column):
        """Use the database's underscore naming convention verbatim."""
        return str(column)

    def populate_optimisation_plan_preview(self, report):
        preview = getattr(self, "optimisation_plan_preview", None)
        if preview is None:
            return
        columns = self.optimisation_snapshot_columns(report)
        preview.clearContents()
        preview.setRowCount(min(len(report), 200))
        preview.setColumnCount(len(columns))
        preview.setHorizontalHeaderLabels([
            self.optimisation_snapshot_column_label(column)
            for column in columns
        ])
        for row_index, (_, row) in enumerate(report.head(200).iterrows()):
            for column_index, column in enumerate(columns):
                preview.setItem(
                    row_index,
                    column_index,
                    QTableWidgetItem(
                        self.format_optimisation_snapshot_value(
                            column, row.get(column)
                        )
                    ),
                )
        preview.resizeColumnsToContents()

    def choose_optimisation_snapshot_columns(self):
        report = self.fetch_optimised_blend_report(
            self.selected_optimisation_plan_id()
        )
        columns = self.optimisation_snapshot_available_columns(report)
        if not columns:
            QMessageBox.information(
                self, "Optimised Blend Sequence",
                "Run or load an optimisation plan before choosing snapshot fields.",
            )
            return
        selected = set(self.optimisation_snapshot_columns(report))
        dialog = QDialog(self)
        dialog.setWindowTitle("Optimised Blend Sequence Snapshot Fields")
        dialog.resize(520, 620)
        layout = QVBoxLayout(dialog)
        layout.addWidget(QLabel(
            "Choose the report fields shown in the data snapshot above the chart."
        ))
        field_list = QListWidget()
        for column in columns:
            item = QListWidgetItem(
                self.optimisation_snapshot_column_label(column)
            )
            item.setToolTip(str(column))
            item.setData(Qt.UserRole, column)
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
            item.setCheckState(
                Qt.Checked if column in selected else Qt.Unchecked
            )
            field_list.addItem(item)
        layout.addWidget(field_list)

        buttons = QHBoxLayout()
        defaults_button = QPushButton("Defaults")
        select_all_button = QPushButton("Select All")
        apply_button = QPushButton("Apply")
        cancel_button = QPushButton("Cancel")
        buttons.addWidget(defaults_button)
        buttons.addWidget(select_all_button)
        buttons.addStretch()
        buttons.addWidget(apply_button)
        buttons.addWidget(cancel_button)
        layout.addLayout(buttons)

        def set_checked(chosen):
            chosen = set(chosen)
            for index in range(field_list.count()):
                item = field_list.item(index)
                item.setCheckState(
                    Qt.Checked if item.data(Qt.UserRole) in chosen else Qt.Unchecked
                )

        defaults_button.clicked.connect(
            lambda: set_checked(self.default_optimisation_snapshot_columns(columns))
        )
        select_all_button.clicked.connect(lambda: set_checked(columns))
        apply_button.clicked.connect(dialog.accept)
        cancel_button.clicked.connect(dialog.reject)
        if dialog.exec_() != QDialog.Accepted:
            return
        self.optimisation_snapshot_selected_columns = [
            field_list.item(index).data(Qt.UserRole)
            for index in range(field_list.count())
            if field_list.item(index).checkState() == Qt.Checked
        ] or self.default_optimisation_snapshot_columns(columns)
        self.optimisation_snapshot_known_columns = list(columns)
        self.populate_optimisation_plan_preview(report)
        self.save_active_scenario_state()

    def configure_report_columns_dialog(
        self, title, columns, selected_columns, aliases, widths=None,
        wrap_text=True, defaults=None
    ):
        schema_columns = balance_triplet_columns(columns)
        selected_order = [
            column for column in (selected_columns or [])
            if column in schema_columns
        ]
        columns = balance_triplet_columns([
            *selected_order,
            *[column for column in schema_columns if column not in selected_order],
        ])
        selected = set(
            selected_columns if selected_columns is not None
            else (defaults or columns)
        )
        dialog = QDialog(self)
        dialog.setWindowTitle(title)
        dialog.resize(980, 720)
        layout = QVBoxLayout(dialog)
        layout.addWidget(QLabel(
            "Select fields and optionally enter the column label shown on the UI. "
            "Stored database field names are not changed."
        ))
        table = QTableWidget(len(columns), 4)
        table.setHorizontalHeaderLabels([
            "Show", "Field", "UI Alias", "Width (px)"
        ])
        table.setSelectionBehavior(QAbstractItemView.SelectRows)
        table.setSelectionMode(QAbstractItemView.SingleSelection)
        table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeToContents)
        table.horizontalHeader().setSectionResizeMode(1, QHeaderView.Stretch)
        table.horizontalHeader().setSectionResizeMode(2, QHeaderView.Stretch)
        table.horizontalHeader().setSectionResizeMode(3, QHeaderView.ResizeToContents)
        for row, column in enumerate(columns):
            show_item = QTableWidgetItem()
            show_item.setFlags(show_item.flags() | Qt.ItemIsUserCheckable)
            show_item.setCheckState(Qt.Checked if column in selected else Qt.Unchecked)
            field_item = QTableWidgetItem(str(column))
            field_item.setFlags(field_item.flags() & ~Qt.ItemIsEditable)
            alias_item = QTableWidgetItem(str((aliases or {}).get(column, "")))
            width_item = QTableWidgetItem(str(
                int((widths or {}).get(column, 150) or 150)
            ))
            table.setItem(row, 0, show_item)
            table.setItem(row, 1, field_item)
            table.setItem(row, 2, alias_item)
            table.setItem(row, 3, width_item)
        layout.addWidget(table)
        display_controls = QHBoxLayout()
        move_up_button = QPushButton("Move Up")
        move_down_button = QPushButton("Move Down")
        wrap_checkbox = QCheckBox("Wrap header and cell text")
        wrap_checkbox.setChecked(bool(wrap_text))
        display_controls.addWidget(move_up_button)
        display_controls.addWidget(move_down_button)
        display_controls.addSpacing(20)
        display_controls.addWidget(wrap_checkbox)
        display_controls.addStretch()
        layout.addLayout(display_controls)
        buttons = QHBoxLayout()
        defaults_button = QPushButton("Defaults")
        select_all_button = QPushButton("Select All")
        apply_button = QPushButton("Apply")
        cancel_button = QPushButton("Cancel")
        buttons.addWidget(defaults_button)
        buttons.addWidget(select_all_button)
        buttons.addStretch()
        buttons.addWidget(apply_button)
        buttons.addWidget(cancel_button)
        layout.addLayout(buttons)

        def move_row(offset):
            row = table.currentRow()
            destination = row + offset
            if row < 0 or destination < 0 or destination >= table.rowCount():
                return
            items = [table.takeItem(row, column) for column in range(4)]
            other = [
                table.takeItem(destination, column) for column in range(4)
            ]
            for column in range(4):
                table.setItem(row, column, other[column])
                table.setItem(destination, column, items[column])
            table.selectRow(destination)

        move_up_button.clicked.connect(lambda: move_row(-1))
        move_down_button.clicked.connect(lambda: move_row(1))

        def set_checked(chosen):
            chosen = set(chosen)
            for row in range(table.rowCount()):
                column = table.item(row, 1).text()
                table.item(row, 0).setCheckState(
                    Qt.Checked if column in chosen else Qt.Unchecked
                )

        defaults_button.clicked.connect(lambda: set_checked(defaults or columns))
        select_all_button.clicked.connect(lambda: set_checked(columns))
        apply_button.clicked.connect(dialog.accept)
        cancel_button.clicked.connect(dialog.reject)
        if dialog.exec_() != QDialog.Accepted:
            return None
        chosen = []
        chosen_aliases = {}
        chosen_widths = {}
        for row in range(table.rowCount()):
            column = table.item(row, 1).text()
            if table.item(row, 0).checkState() == Qt.Checked:
                chosen.append(column)
            alias = table.item(row, 2).text().strip()
            if alias:
                chosen_aliases[column] = alias
            try:
                width = int(float(table.item(row, 3).text().strip()))
            except (TypeError, ValueError):
                width = 150
            chosen_widths[column] = max(50, min(800, width))
        return (
            balance_triplet_columns(chosen or list(defaults or columns)),
            chosen_aliases,
            chosen_widths,
            wrap_checkbox.isChecked(),
        )

    def choose_optimisation_detail_columns(self):
        report = self.fetch_optimised_blend_report(
            self.selected_optimisation_plan_id()
        )
        columns = self.optimisation_snapshot_available_columns(report)
        if not columns:
            QMessageBox.information(
                self, "Optimised Blend Sequence",
                "Run or load an optimisation plan before configuring the report.",
            )
            return
        result = self.configure_report_columns_dialog(
            "Optimised Blend Sequence Detail Report",
            columns,
            getattr(self, "optimisation_detail_selected_columns", None),
            getattr(self, "optimisation_detail_column_aliases", {}),
            getattr(self, "optimisation_detail_column_widths", {}),
            getattr(self, "optimisation_detail_wrap_text", True),
            defaults=self.default_optimisation_snapshot_columns(columns),
        )
        if result is None:
            return
        (
            self.optimisation_detail_selected_columns,
            self.optimisation_detail_column_aliases,
            self.optimisation_detail_column_widths,
            self.optimisation_detail_wrap_text,
        ) = result
        chart = getattr(self, "draw_gantt_chart", None)
        if chart is not None:
            chart.set_report_configuration(*result)
        self.save_active_scenario_state()

    def load_AMT_map(self):
        self.ensure_AMT_map_panel()
        if getattr(self, "draw_AMT_map", None) is None:
            self.start_dash_AMT_map_thread()
        if not self.store_AMT_chunk_settings():
            return

        try:
            requests.post("http://localhost:8054/trigger-refresh", timeout=5)

        except requests.exceptions.RequestException:
            print("Refresh timed out.")

        self.AMT_map_view.setUrl(QUrl("http://localhost:8054"))

        self.load_AMT_map_first_call = False

    def reload_AMT_map_view(self):
        """Reconnect a restored AMT view after the Dash worker has started."""
        view = getattr(self, "AMT_map_view", None)
        if view is None:
            return
        if view.url().isEmpty():
            view.setUrl(QUrl("http://localhost:8054"))
        else:
            view.reload()

    def load_gantt_chart(self):
        plan_id = self.selected_optimisation_plan_id()
        chart = getattr(self, "draw_gantt_chart", None)
        if chart is not None:
            chart.set_plan_id(plan_id)
        self.resize_results_chart_area()
        # A unique query string forces QWebEngine to reload both Dash
        # callbacks after changing the selected plan.
        refresh_token = uuid.uuid4().hex
        self.gantt_chart_view.setUrl(QUrl(
            "http://localhost:8050/"
            f"?plan={plan_id}&refresh={refresh_token}"
        ))

    def resize_results_chart_area(self):
        desired_height = 520

        try:
            data = self.fetch_optimised_blend_report(
                self.selected_optimisation_plan_id()
            )

            if not data.empty:
                blend_count = max(data["blend_ID"].nunique(), 1)
                row_count = len(
                    data[["blend_ID", "steady_state_number"]]
                    .drop_duplicates()
                )
                graph_height = min(max(280, 190 + (blend_count * 55)), 720)
                table_height = min(360, 120 + (min(row_count, 8) * 34))
                desired_height = graph_height + table_height + 90
        except Exception:
            desired_height = 520

        available_height = self.results_tab.height() - self.load_chart_button.sizeHint().height() - 92
        available_height = max(420, available_height)
        desired_height = max(420, min(desired_height, available_height))

        self.top_frame.setMinimumHeight(desired_height)
        self.top_frame.setMaximumHeight(desired_height)
    
    def load_manual_gantt_chart(self):
        # Load the Dash app into the QWebEngineView
        self.manual_gantt_view.setUrl(QUrl("http://localhost:8052"))
        
