    @staticmethod
    def default_sqlite_report_query(table_name):
        escaped_table_name = str(table_name).replace('"', '""')
        return f'SELECT * FROM "{escaped_table_name}" LIMIT 100'

    def handle_sqlite_report_selection(self):
        table_name = self.sqlite_report_selector.currentText()
        if not table_name:
            self.clear_sqlite_report_preview()
            return
        self.sqlite_report_query.setText(
            self.default_sqlite_report_query(table_name)
        )
        self.execute_sqlite_report_query()

    def clear_sqlite_report_preview(self):
        self.sqlite_report_table.clearContents()
        self.sqlite_report_table.setRowCount(0)
        self.sqlite_report_table.setColumnCount(0)
        self.sqlite_report_status.setText("")
        self.current_sqlite_report_df = pd.DataFrame()

    @staticmethod
    def is_read_only_report_query(query):
        normalized = str(query or "").strip()
        if normalized.endswith(";"):
            normalized = normalized[:-1].rstrip()
        if not normalized or ";" in normalized:
            return False
        first_word = normalized.split(None, 1)[0].lower()
        return first_word in {"select", "with"}

    @staticmethod
    def configure_read_only_sqlite_connection(conn):
        conn.execute("PRAGMA query_only = ON")

        denied_actions = {
            getattr(sqlite3, name)
            for name in (
                "SQLITE_INSERT",
                "SQLITE_UPDATE",
                "SQLITE_DELETE",
                "SQLITE_CREATE_INDEX",
                "SQLITE_CREATE_TABLE",
                "SQLITE_CREATE_TEMP_INDEX",
                "SQLITE_CREATE_TEMP_TABLE",
                "SQLITE_CREATE_TEMP_TRIGGER",
                "SQLITE_CREATE_TEMP_VIEW",
                "SQLITE_CREATE_TRIGGER",
                "SQLITE_CREATE_VIEW",
                "SQLITE_DROP_INDEX",
                "SQLITE_DROP_TABLE",
                "SQLITE_DROP_TEMP_INDEX",
                "SQLITE_DROP_TEMP_TABLE",
                "SQLITE_DROP_TEMP_TRIGGER",
                "SQLITE_DROP_TEMP_VIEW",
                "SQLITE_DROP_TRIGGER",
                "SQLITE_DROP_VIEW",
                "SQLITE_ALTER_TABLE",
                "SQLITE_REINDEX",
                "SQLITE_ANALYZE",
                "SQLITE_ATTACH",
                "SQLITE_DETACH",
            )
            if hasattr(sqlite3, name)
        }

        def authorize(action_code, _arg1, _arg2, _database_name, _trigger_name):
            if action_code in denied_actions:
                return sqlite3.SQLITE_DENY
            return sqlite3.SQLITE_OK

        conn.set_authorizer(authorize)

    def load_selected_sqlite_report(self):
        """Compatibility alias for callers that previously loaded by table."""
        self.handle_sqlite_report_selection()

    def execute_sqlite_report_query(self):
        query = self.sqlite_report_query.text().strip()
        if not self.is_read_only_report_query(query):
            QMessageBox.warning(
                self,
                "Reports",
                "Reports accepts one read-only SELECT or WITH query at a time.",
            )
            return

        try:
            conn = sqlite3.connect(get_database_path())
            try:
                self.configure_read_only_sqlite_connection(conn)
                df = pd.read_sql_query(query, conn)
            finally:
                conn.close()
        except Exception as e:
            self.sqlite_report_status.setText(f"Query failed: {e}")
            QMessageBox.warning(self, "Reports", f"Unable to run query: {e}")
            return

        self.sqlite_report_status.setText(
            f"Query returned {len(df):,} row{'s' if len(df) != 1 else ''}."
        )
        self.current_sqlite_report_df = df.copy()
        self.populate_dataframe_table(self.sqlite_report_table, df)

    def current_sqlite_report_frame(self):
        query = self.sqlite_report_query.text().strip()
        if not self.is_read_only_report_query(query):
            raise ValueError(
                "Reports accepts one read-only SELECT or WITH query at a time."
            )
        connection = sqlite3.connect(get_database_path())
        try:
            self.configure_read_only_sqlite_connection(connection)
            return pd.read_sql_query(query, connection)
        finally:
            connection.close()

    @staticmethod
    def report_export_stem(value):
        stem = re.sub(
            r"[^A-Za-z0-9._-]+", "_", str(value or "report")
        ).strip("._")
        return stem or "report"

    def export_current_sqlite_report(self, export_format):
        table_name = self.sqlite_report_selector.currentText() or "sqlite_report"
        stem = self.report_export_stem(table_name)
        timestamp = datetime.now()
        suffix = str(export_format).lower()
        file_filter = (
            "Excel Workbooks (*.xlsx)" if suffix == "xlsx"
            else "CSV Files (*.csv)"
        )
        file_path, _ = self.report_save_file_name(
            "Export Database Report",
            f"{stem}_{timestamp.strftime('%Y%m%d_%H%M')}.{suffix}",
            file_filter,
        )
        if not file_path:
            return
        if not file_path.lower().endswith(f".{suffix}"):
            file_path += f".{suffix}"
        try:
            report = self.current_sqlite_report_frame()
        except Exception as exc:
            QMessageBox.warning(
                self, "Export Database Report", f"Unable to run query: {exc}"
            )
            return
        try:
            if suffix == "xlsx":
                SpreadsheetReportExporter.export_xlsx(
                    file_path,
                    [(table_name, report)],
                    report_title=f"BlendMaster - {table_name}",
                    report_datetime=timestamp,
                )
            else:
                SpreadsheetReportExporter.export_csv(file_path, report)
        except (SpreadsheetReportExportError, OSError, ValueError) as exc:
            QMessageBox.warning(
                self, "Export Database Report", str(exc)
            )
            return
        QMessageBox.information(
            self,
            "Export Database Report",
            f"Database report exported to:\n{file_path}",
        )

    def export_all_sqlite_reports_xlsx(self):
        tables = self.get_sqlite_report_tables()
        if not tables:
            QMessageBox.information(
                self, "Export Database Reports", "No report tables are available."
            )
            return
        timestamp = datetime.now()
        file_path, _ = self.report_save_file_name(
            "Export All Database Reports",
            timestamp.strftime("blendmaster_database_reports_%Y%m%d_%H%M.xlsx"),
            "Excel Workbooks (*.xlsx)",
        )
        if not file_path:
            return
        if not file_path.lower().endswith(".xlsx"):
            file_path += ".xlsx"
        connection = sqlite3.connect(get_database_path())
        try:
            self.configure_read_only_sqlite_connection(connection)
            sheets = []
            for table_name in tables:
                escaped_name = str(table_name).replace('"', '""')
                sheets.append((
                    table_name,
                    pd.read_sql_query(
                        f'SELECT * FROM "{escaped_name}"', connection
                    ),
                ))
        except Exception as exc:
            QMessageBox.warning(
                self, "Export Database Reports",
                f"Unable to read database reports: {exc}",
            )
            return
        finally:
            connection.close()
        try:
            SpreadsheetReportExporter.export_xlsx(
                file_path,
                sheets,
                report_title="BlendMaster - Database Reports",
                report_datetime=timestamp,
            )
        except (SpreadsheetReportExportError, OSError, ValueError) as exc:
            QMessageBox.warning(
                self, "Export Database Reports", str(exc)
            )
            return
        QMessageBox.information(
            self,
            "Export Database Reports",
            f"All database tables exported to:\n{file_path}",
        )

    @staticmethod
    def is_additive_tonne_column(header):
        """Return whether a displayed field is a mass/tonnage quantity."""
        normalized = str(header or "").strip().lower()
        if not normalized:
            return False
        normalized = re.sub(r"[^a-z0-9]+", "_", normalized).strip("_")
        if any(marker in normalized for marker in (
            "_rate", "rate_", "_tph", "per_hour", "per_source_wmt",
            "_ratio", "_pct", "_percent", "coverage",
        )):
            return False
        if source_property_kind(normalized) == "additive":
            return True
        return (
            normalized
            in {"tonnes", "wmt", "dmt", "balance", "payload", "max_quantity"}
            or "tonne" in normalized
            or normalized.endswith(("_balance", "_payload", "_chunk_size"))
            or normalized.startswith("balance_")
        )

    @classmethod
    def is_two_decimal_quantity_column(cls, header):
        normalized = str(header or "").strip().lower()
        return not cls.is_additive_tonne_column(header) and "grade" in normalized

    def format_table_display_value(self, value, header=None):
        try:
            if pd.isna(value):
                return ""
        except (TypeError, ValueError):
            pass

        if isinstance(value, bool):
            return str(value)

        if hasattr(value, "strftime"):
            return value.strftime("%Y-%m-%d %H:%M:%S")

        force_zero_decimal_tonnes = self.is_additive_tonne_column(header)
        force_two_decimals = self.is_two_decimal_quantity_column(header)
        if force_zero_decimal_tonnes:
            try:
                return f"{float(value):,.0f}"
            except (TypeError, ValueError):
                pass
        if isinstance(value, Real) and (
            force_two_decimals or not isinstance(value, Integral)
        ):
            return f"{float(value):.2f}"

        if isinstance(value, str):
            stripped_value = value.strip()
            if len(stripped_value) >= 10 and stripped_value[4:5] == "-" and stripped_value[7:8] == "-":
                parsed_datetime = pd.to_datetime(stripped_value, errors="coerce")
                if not pd.isna(parsed_datetime):
                    return parsed_datetime.strftime("%Y-%m-%d %H:%M:%S")
            if stripped_value and ("." in stripped_value or "e" in stripped_value.lower()):
                try:
                    return f"{float(stripped_value):.2f}"
                except ValueError:
                    pass
            if force_two_decimals:
                try:
                    return f"{float(stripped_value):.2f}"
                except ValueError:
                    pass

        return str(value)

    def populate_dataframe_table(self, table_widget, df):
        table_widget.clearContents()
        table_widget.setRowCount(len(df))
        table_widget.setColumnCount(len(df.columns))
        table_widget.setHorizontalHeaderLabels([str(column) for column in df.columns])
        table_widget.verticalHeader().setVisible(False)

        header_font = table_widget.horizontalHeader().font()
        header_font.setBold(True)
        table_widget.horizontalHeader().setFont(header_font)

        for row_idx, row in enumerate(df.itertuples(index=False)):
            for col_idx, value in enumerate(row):
                item = QTableWidgetItem(self.format_table_display_value(
                    value,
                    df.columns[col_idx],
                ))
                item.setTextAlignment(Qt.AlignCenter)
                table_widget.setItem(row_idx, col_idx, item)

        table_widget.resizeColumnsToContents()

